pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Super-linear waste penalty: tiny leftovers are nearly unusable later.
    if post_residual == 0 {
        score -= 70.0;
    } else if post_residual < 8 {
        score += 30.0;
    } else if post_residual < 16 {
        score += 12.0;
    } else if post_residual as f64 > cap * 0.6 {
        score -= 10.0; // large leftover is flexible space
    }

    // Lookahead chain: how well does post_residual serve the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 55.0;
            } else if slack < 8 {
                score -= 25.0;
            } else if slack < 25 {
                score -= 10.0;
            } else {
                score -= 4.0;
            }
        } else {
            // Dead space for next item: penalize proportionally to what's stranded.
            score += 10.0 + (next_item_size as f64) * 0.2;
        }
    }

    // Two-item lookahead: if next item also fits a known residual pattern, favor tight fills.
    if next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && rem2 < item_size {
            score -= 6.0; // leftover then too small for similar items: good compaction
        }
    }

    // Last-chance bin: strong consolidation pressure.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    // New-bin candidate: open only under saturation pressure or early flexibility.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if pressure < 0.22 || (progress < 0.15 && open_bins_count < 4) {
            score -= 25.0;
        } else {
            score += 18.0;
        }
    }

    // Prefer bins below mean residual, scaled by how tight the packing is.
    let tightness = 1.0 - mean_residual / cap;
    score += (mean_residual - bin_residual as f64) * (0.2 + 0.4 * tightness);

    // Consolidation: mild penalty per open bin, stronger late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 + 0.6 * progress);

    // Complementarity: medium leftovers pair with mid-size items.
    if post_residual >= 10 && post_residual < 30 && item_size >= bin_capacity / 4 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fraction buckets (1..=10 deciles).
    let frac = (item_size * 10 + bin_capacity / 2) / bin_capacity; // 1..=10
    let next_frac = if next_item_size == 0 { 0 } else { (next_item_size * 10 + bin_capacity / 2) / bin_capacity };

    // Reward exact / near-exact fits (post_residual in low harmonic classes).
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let post_class = (post_residual * 10 + bin_capacity / 2) / bin_capacity; // 0..=9
        // Dead space penalty grows super-linearly for tiny leftovers (hard to reuse).
        if post_residual < 10 {
            score += 25.0;
        } else if post_residual < 20 {
            score += 10.0;
        } else if post_class >= 7 {
            // Large post_residual is reusable: mild reward.
            score -= 8.0;
        }
    }

    // Lookahead coupling: bonus if the post_residual can host the next item's class.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Next item fits snugly into the created space.
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 45.0; // perfect chain fit
        } else if slack < 10 {
            score -= 20.0;
        } else {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // The leftover would be dead space for the next item.
        score += 12.0 + (next_item_size as f64) * 0.15;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are very full.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if pressure < 0.25 {
            score -= 20.0; // open bins nearly saturated -> prefer fresh bin
        } else {
            score += 15.0; // plenty of room left in open bins
        }
    }

    // Prefer filling bins that deviate below the mean residual (balance load).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Early in the stream, be more willing to open bins (future flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 && bin_residual == bin_capacity {
        score -= 5.0;
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    // Harmonic class tiebreak: odd decile items pair well with even-decile leftovers.
    if frac % 2 == 0 && post_residual >= 10 && post_residual < 30 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Base: two-step waste — leftover after ideally seating the lookahead item too.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Aggressive exact two-step match: lookahead item would close this bin perfectly.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 12.0 + 6.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 5.0;
        } else if slack < 20 {
            score -= 2.0;
        }
    }

    // Perfect closure: item exactly fills the bin now.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 10 {
        score += 8.0;
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Dead-space risk: leftover smaller than the incoming lookahead item.
    // Strengthened: quadratic in the unusable gap, scaled by stream progress,
    // since dead space created early is more costly over a long stream.
    if nxt > 0.0 && post > 0.0 && post < nxt {
        let gap = (nxt - post).min(cap);
        score += 0.5 * gap + 0.02 * gap * gap + 4.0 * (1.0 - 0.5 * progress);
    }

    // Mean-relative coupling: penalize leftovers above the average slack.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Relative-waste refinement: penalize the fraction of the bin left empty.
    score += 0.3 * (post / resid);

    // Last-chance fitting bin: strongly prefer the only open bin that fits.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 8.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 1.5;
    }

    // Opening cost for a brand-new bin: only attractive when open bins are nearly
    // saturated. Refined: also weigh how reusable the current bin's post-residual
    // is; if the chosen open bin leaves a large void, a fresh bin is competitive.
    if is_new_bin {
        let pressure = mean / cap;
        if pressure < 0.25 {
            score -= 6.0 + 3.0 * progress;
        } else if pressure < 0.45 {
            score += 1.0 + 3.0 * progress;
        } else {
            score += 8.0 + 5.0 * progress;
        }
    }

    // Consolidation pressure: many open bins favor filling existing ones.
    score += open_bins_count as f64 * 0.05;

    // Reward bins whose residual exactly matches the next item size (chain closure).
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Penalize residual too small for both current and next item — stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 2.5 * (1.0 - progress);
    }

    // Tight absolute fit regardless of lookahead.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing: small leftovers pair with even-class items, making them reusable.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.0;
    }

    // Endgame tightening — late in the stream, avoid opening bins unless nearly closed.
    if progress > 0.85 && is_new_bin {
        score += 6.0 * (progress - 0.85) / 0.15;
    }

    // Snug fit now, independent of lookahead — encourages closing bins fully.
    if !is_new_bin && bin_residual >= item_size {
        let snug = bin_residual - item_size;
        if snug < 5 {
            score -= 2.5;
        }
    }

    // Refinement 1: graded snugness — near-perfect placements beat merely-tight ones.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        if snug < 15.0 {
            score -= 1.0 * (1.0 - snug / 15.0);
        }
    }

    // Refinement 2: lookahead chain — reusable leftover after seating the next item.
    if nxt > 0.0 && post_residual >= next_item_size && next_item_size > 0 {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
    }

    // Refinement 3: dead-space ratio penalty — unrecoverable voids beyond mean slack.
    if post > mean && cap > 0.0 {
        let excess_ratio = (post - mean) / cap;
        if excess_ratio > 0.15 {
            score += 2.0 * excess_ratio;
        }
    }

    // Refinement 4 (new): residual-reuse outlook — quantify how well the post-fit
    // residual can absorb a typical future item (approximated by mean residual as
    // a demand proxy). A post-residual that cannot host anything near the mean
    // slack is a void; scale the penalty with progress so late voids hurt more.
    if !is_new_bin && post > 0.0 && cap > 0.0 {
        let reuse_deficit = (mean - post).max(0.0) / cap;
        if reuse_deficit > 0.10 {
            score += 3.0 * reuse_deficit * (0.5 + progress);
        }
    }

    // Refinement 5 (new): lookahead feasibility gradient — if the next item fits
    // the post-residual with room to spare, reward proportionally to how snug the
    // two-step chain is; this sharpens preference for chainable bins.
    if nxt > 0.0 && post_residual >= next_item_size {
        let chain_slack = post_residual - next_item_size;
        if chain_slack <= 8 {
            score -= 2.0 * (1.0 - chain_slack as f64 / 8.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the minimum
    // item size (1) are not penalized as hard as "awkward" gaps, but any
    // gap below the typical item floor creates unusable slack.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        // Dead space penalty: the smaller the unusable gap, the worse.
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: discourage spreading across too many bins,
    // but only mildly, so tight fits still win.
    score += (open_bins_count as f64) * 0.35;

    // If this bin is the last chance to fit, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // More attractive when existing residuals are large/fragmented.
        score += mean_residual * 0.2;
        // Less attractive when few bins are open (reuse them instead).
        score -= (open_bins_count as f64) * 1.5;
        // If the next item fits better in a fresh bin, encourage opening.
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 20.0;
        }
    }

    // Lookahead coupling: reward leaving post_residual that can host the
    // next item exactly; penalize leaving a gap that just barely misses it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_leftover = post_residual - next_item_size;
            if next_leftover == 0 {
                score -= 20.0;
            } else if (next_leftover as f64) < dead_threshold {
                score -= 8.0;
            }
        } else if post_residual > 0 {
            // Gap too small for the next item: awkward residual.
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 90.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that is hard to reuse (small post_residual but not zero).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // Perfect-fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor
    // (high fit_ratio spread) or many bins are already open and fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bin late in stream or when existing bins are highly fragmented.
        score += 30.0 - 20.0 * fragmentation / bin_capacity as f64 - 25.0 * pressure - 15.0 * progress;
        // If the current item is large relative to mean residual, opening fresh is good.
        if (item_size as f64) > mean_residual * 0.7 {
            score -= 35.0;
        }
    }

    // Mild global balance: discourage stuffing bins far above the mean residual
    // when many bins are open (keeps residual distribution usable).
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Base: two-step waste — leftover after ideally seating the lookahead item too.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Perfect closure / small leftovers.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score += 14.0 + 3.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 5.0;
    } else {
        let post_class = (post_residual * 10 + bin_capacity / 2) / bin_capacity;
        if post_class >= 7 {
            score -= 4.0;
        }
    }

    // Aggressive exact two-step match.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 25.0 + 8.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 10.0;
        } else if slack < 20 {
            score -= 4.0;
        }
    } else if nxt > 0.0 && post > 0.0 && post < nxt {
        let waste_frac = (nxt - post) / nxt;
        score += 0.6 * (nxt - post).min(cap)
            + 7.0
            + 3.5 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.5 * waste_frac * (1.0 - progress);
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

