        }
    }

    // Mutation V: new-bin exact-chain gate.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if (new_post - nxt).abs() < 1.0 {
            score -= 4.0 * (1.0 - progress);
        } else if new_post < nxt && progress > 0.5 {
            score += 2.5 * (progress - 0.5) / 0.5;
        }
    }

    // Mutation W: dead-space ratio diagnostic — convex penalty on
    // fleet-mean excess leftover, mild early-stream grace.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.05 {
            score += 4.5 * (excess_frac - 0.05) * (excess_frac - 0.05) / (excess_frac + 0.05) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation X: complementarity bonus — reward leftovers that pair with
    // the fleet-average residual into a jointly fillable whole.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_sum = after + mean;
        let pair_frac = pair_sum / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation Y: lookahead-fit calibration — escalate the exact-fill
    // reward late in the stream.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation Z: waste-shape guard — penalize awkward middle-band
    // leftovers (16..=29).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AA (gen 40): residual-band anticipation — when the post
    // leftover falls just short of holding the next item, but the bin's
    // own remaining residual (before this item) could have held it, the
    // placement wastes the next-item slot; penalize proportionally to how
    // close the miss is, weighted by how few fitting alternatives exist.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 8.0 {
            let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
            score += (3.0 - miss * 0.3) * (1.0 + scarcity) * (0.4 + 0.8 * progress);
        }
    }

    // Mutation AB (gen 40): dual-lookahead exact-pair reward — if the
    // leftover after the next item equals the current item size, the bin
    // becomes perfectly refillable by the same item class two steps out;
    // reward this closure cycle, stronger early when cycles repeat more.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 == item_size as f64 && item_size > 0 {
            score -= 4.5 * (1.2 - progress);
        }
    }

    // Mutation AC (gen 40): fleet-residual matching — prefer bins whose
    // post leftover lands close to the fleet mean residual, so future
    // mid-size items fit uniformly across bins; graded by deviation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let dev = (after - mean).abs() / cap;
        if dev < 0.08 {
            score -= 2.2 * (1.0 - dev / 0.08) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AD (gen 40): new-bin final-fill hedge — late in the stream,
    // opening a new bin is only justified if the item is large relative to
    // what the fleet can still absorb; tighten the gate with progress.
    if is_new_bin && progress > 0.6 {
        let fleet_absorb = mean * open_bins_count as f64;
        if fleet_absorb > item_size as f64 * (1.0 + 2.0 * (progress - 0.6)) {
            score += 4.0 * (progress - 0.6) / 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);
    let resid = bin_residual.max(1) as f64;

    // Base: two-step waste — leftover after ideally seating the lookahead item.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Perfect closure: item exactly fills the bin now.
    if post_residual == 0 {
        score -= 22.0;
    } else if post_residual < 10 {
        // Tiny leftovers are hard to reuse: super-linear dead-space penalty.
        score += 8.0 + 0.5 * (10.0 - post);
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Aggressive exact two-step match: lookahead item closes this bin perfectly.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 14.0 + 6.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 6.0;
        } else if slack < 20 {
            score -= 2.0;
        }
    }

    // Dead-space risk: leftover too small for the incoming lookahead item.
    if nxt > 0.0 && post > 0.0 && post < nxt {
        score += 0.5 * (nxt - post).min(cap) + 4.0;
        // Extra penalty if stranded residual is far below half the next item.
        if post < 0.5 * nxt {
            score += 2.5 * (1.0 - progress);
        }
    }

    // Mean-relative coupling: penalize leftovers above the average slack.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Relative-waste refinement: penalize the fraction of the bin left empty.
    score += 0.3 * (post / resid);

    // Last-chance fitting bin: strongly prefer the only open bin that fits.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 10.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 1.5;
    }

    // New-bin handling: pressure-gated, scaled by stream progress.
    if is_new_bin {
        let pressure = mean / cap;
        if pressure < 0.22 {
            score -= 8.0 + 3.0 * progress;
        } else if pressure < 0.45 {
            score += 1.0 + 3.0 * progress;
        } else {
            score += 9.0 + 5.0 * progress;
        }
        // Early stream: more willing to open bins for future flexibility.
        if progress < 0.2 {
            score -= 4.0;
        }
    }

    // Consolidation pressure: many open bins favor filling existing ones.
    score += open_bins_count as f64 * 0.05;

    // Chain closure bonus: residual exactly matches the next item size.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Tight absolute fit regardless of lookahead.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item completion
        } else if next_item_size <= post_residual {
            // next item fits; reward tightness of the chain
            let chain_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 30.0 * chain_tightness;
        } else {
            // next item would NOT fit here after placing current item: penalize
            let overflow_gap = (next_item_size - post_residual) as f64;
            score += 0.15 * overflow_gap.min(50.0);
        }
    }

    // Compare post_residual to mean residual: prefer leaving residuals near the mean
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Penalize small unusable dead space (post_residual too small for typical items)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin fit is very poor
    if bin_residual == bin_capacity {
        // neutral baseline; open new bin only if it beats existing options
        score += 5.0 - 0.1 * (open_bins_count as f64);
    }

    // Late in stream: prefer consolidating into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * progress * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: prefer tight fits (low post_residual), with a non-linear penalty
    // on very small residuals (dead space) that grows faster than linear.
    let mut score = post;
    let dead_zone = post / cap;
    score += 30.0 * dead_zone * dead_zone * cap;

    // Smooth stream-progress coupling: late in the stream, dead space matters more.
    let late = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += late * post * 0.5;

    // Reward perfect-ish fits: item_size close to bin_residual.
    let fit_gap = (bin_residual as f64 - item).abs();
    score -= (1.0 - fit_gap / cap) * 8.0;

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next > 0.0 {
        let gap_next = (post - next).abs();
        score -= (1.0 - gap_next / cap) * 10.0 * (1.0 + late);
        // Penalize if post_residual is too small for next item (fragmentation risk)
        if post < next {
            score += 5.0 * late * (next - post) / cap * cap.sqrt();
        }
    }

    // Last-chance bonus: only one bin fits; strongly prefer using it over new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - late);

    // New-bin candidate: make empty bin moderately attractive only when
    // current item is large relative to mean residual (poor fits elsewhere).
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item).abs();
        score = cap * 0.9 + mean_gap - 15.0 * (1.0 - late);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: penalize wasted space, with non-linear (quadratic) growth
    let mut score = pr + 12.0 * norm_pr * norm_pr * cap;

    // Smooth coupling of post_residual with stream progress:
    // early in stream, prefer leaving flexible residuals; later, prefer tight fits.
    let flex = (1.0 - progress) * (1.0 - progress);
    let tight = progress * progress;
    score += flex * 8.0 * norm_pr - tight * 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Non-linear interaction between item fill ratio and progress
    let fill = item_size as f64 / cap;
    score -= tight * 10.0 * fill * fill;

    // Lookahead: reward residual that can fit the next item (smoothly)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let fit_quality = 1.0 - (pr - nx) / cap; // tight fit for next item is best
            score -= 7.0 * fit_quality * fit_quality;
        } else {
            // residual too small for next item: dead-space penalty, smooth in gap
            let gap = (nx - pr) / cap;
            score += 9.0 * gap * gap * cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 5.0 * (1.0 - norm_pr);
    }

    // Mild penalty when many bins are open and residual is large (fragmentation pressure)
    let ob = open_bins_count as f64;
    score += 0.4 * (ob / (ob + 4.0)) * norm_pr * cap;

    // Deviation from mean residual: prefer bins near the mean (keeps residuals balanced)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: neutral-ish score so it is chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score = pr + 6.0 * (1.0 - tight) + 4.0 * (ob / (ob + 3.0));
    }

    score
}

