        score += 6.0 * (next_item_size - post_residual) as f64 / 100.0;
    }
    // Reward if the lookahead item fits exactly into the post residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when current fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin; rises with number of open bins (consolidation pressure).
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if the current bin would leave a lot of dead space, new bin becomes competitive.
        score -= 0.15 * post_residual as f64;
        // Late in the stream, prefer consolidation over opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer bins whose residual is below the mean (tighter bins get used first).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild penalty for leaving residual in a "bad zone" (11..=19) where few items fit.
    if post_residual >= 11 && post_residual <= 19 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Base: prefer small post residual, but with diminishing returns (smooth quadratic)
    let mut score = post * (1.0 + 0.5 * post / cap);

    // Non-linear coupling: as stream progresses, tighten preference for tight fits
    let tightness = post / cap;
    score += 40.0 * tightness * tightness * (0.5 + progress);

    // Reward using a bin whose residual matches the item well (smooth interaction)
    let fill_ratio = item_size as f64 / cap;
    score -= 30.0 * fill_ratio * (1.0 - tightness) * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - tightness * tightness);
    }

    // Lookahead: penalize leaving a residual that barely fails next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 10.0 * (1.0 - ((post - nxt) / cap).min(1.0));
        } else {
            score += 8.0 * ((nxt - post) / cap);
        }
    }

    // Prefer filling existing bins over opening new ones as bins accumulate
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress + (open_bins_count as f64).sqrt() * 3.0;
    } else {
        score -= 5.0 * (1.0 - progress);
    }

    // Smooth mean-residual coupling: avoid leaving bins far from mean residual
    score += 0.15 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a quadratic penalty.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Harmonic class of post_residual: classify dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score -= 6.0; // roomy leftover: still very reusable
    } else if frac > 0.25 {
        score -= 2.0;
    } else if post_residual > 0 {
        score += 8.0; // narrow sliver: near-dead space
    } else {
        score -= 15.0; // perfect fill
    }

    // Integer-division harmonic classes on post_residual (buckets of 10).
    let bucket = post_residual / 10;
    score -= match bucket {
        0 => 0.0,
        1 => -4.0,
        2 => -6.0,
        3 => -5.0,
        4 => -7.0,
        _ => -8.0,
    } as f64;

    // Modulo coupling: if next item's size class divides into post_residual nicely.
    if next_item_size > 0 {
        let next = next_item_size as u32;
        if next <= post_residual {
            // Reward when post_residual is a near-multiple of next item size.
            let m = post_residual % next.max(1);
            if m == 0 {
                score -= 10.0;
            } else {
                score += (m as f64) * 0.5;
            }
            // Reward if next item fits with tight slack too.
            let slack = post_residual - next;
            score -= (slack as f64).min(20.0) * 0.2;
        } else {
            // Next item cannot use this bin's remainder: penalize wasting good space.
            score += 5.0 + (next - post_residual) as f64 * 0.15;
        }
    } else {
        // Last item: perfect fit is everything.
        score -= post_residual as f64 * 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: neutral baseline; only attractive when current
    // bins are all fragmented.
    if bin_residual == bin_capacity {
        let fragmented = mean_residual < bin_capacity as f64 * 0.35;
        if fragmented {
            score -= 9.0;
        } else {
            score += 10.0 + open_bins_count as f64 * 0.5;
        }
    }

    // Late in stream: consolidation matters more; keep small residuals penalized.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += frac * progress * 4.0;

    // Slight preference to fill already-open bins over spreading load.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..100 range,
    // but gaps below ~10 are dead) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small awkward gaps that few item sizes can use.
    if post_residual >= 10 && post_residual <= 20 {
        score += 12.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // If the lookahead item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual can't host the next item: mild penalty scaled by gap size.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize creating new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 2.0;
    }

    // Prefer bins tighter than the mean residual (good packing density).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Early in the stream, be slightly more willing to open bins (better structure later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Base: two-step waste — leftover remaining after ideally seating the
    // lookahead item in this bin as well. Bins where the next item also fits
    // tightly get credit for the space the next item will consume.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Aggressive exact two-step match: post_residual == next_item_size
    // (the lookahead item would close this bin perfectly).
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 1.5 + 1.0 * (1.0 - progress);
    }

    // Perfect closure: item exactly fills the bin now.
    if post_residual == 0 {
        score -= 2.0;
    }

    // Dead-space risk: leftover is smaller than the incoming lookahead item,
    // so the remaining space is likely unusable.
    if nxt > 0.0 && post > 0.0 && post < nxt {
        score += 0.25 * (nxt - post).min(cap);
    }

    // Mean-relative coupling: penalize leftovers above the average slack of
    // open bins; mildly reward tighter-than-average bins.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Relative-waste refinement: penalize the fraction of the bin left empty.
    score += 0.3 * (post / resid);

    // Last-chance fitting bin: strongly prefer the only open bin that fits,
    // to avoid opening an unnecessary new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 3.0;
    }

    // Opening cost for a brand-new bin; grows as the stream progresses since
    // fresh capacity becomes less likely to be amortized.
    if is_new_bin {
        score += 1.0 + 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: residual left behind that is small and hard to reuse.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 25.0 - 2.5 * dead; // tiny slivers are wasted
        } else {
            score += 60.0 / dead; // larger leftovers are more reusable
        }
    } else {
        score -= 15.0; // perfect fill
    }

    // Lookahead: reward if the next item can also fit in the post residual (chaining),
    // penalize otherwise.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 12.0;
        } else if (post_residual as i64) < (next_item_size as i64) && post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins unattractive unless current open bins
    // would create bad fits or the item is large relative to capacity.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Large items are fine in fresh bins.
        if item_size > bin_capacity / 2 {
            score -= 55.0;
        }
        // Late in the stream with many open bins, avoid bin proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress * (open_bins_count as f64).sqrt();
        // If mean residual is high, open bins are underused -> opening a new one is bad.
        score += 0.3 * mean_residual;
    }

    // Slight preference for bins below mean residual (balance the load).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) shaping.
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth stream-progress coupling: later in the stream, waste is costlier.
    let late = progress * progress;
    score += 60.0 * late * norm_pr * cap;

    // Penalize post-residual that is large relative to mean residual (dead-space divergence).
    let mr = if mean_residual.is_finite() { mean_residual } else { cap };
    score += 25.0 * ((pr - mr) / cap).abs();

    // Reward using a bin when few bins fit (last-chance bonus, smooth in fitting count).
    let fit_term = 1.0 / (fitting_bins_count.max(1) as f64);
    score -= 55.0 * fit_term;

    // Lookahead: reward leaving space compatible with the next item (smooth coupling).
    let ni = next_item_size as f64;
    if ni > 0.0 {
        let gap = (pr - ni) / cap;
        let compat = (-gap * gap * 30.0).exp(); // peaks when pr ~ next_item_size
        score -= 35.0 * compat;
    }

    // Mild penalty on opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // New bin more attractive early in the stream.
        score -= 40.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot size" class the leftover falls into.
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let half = bin_capacity / 2;

    // Penalize dead space in awkward modular classes (residuals that few item sizes can use).
    let class_penalty: f64 = if pr == 0 {
        -30.0 // perfect fit is king
    } else if pr < eighth {
        40.0 // tiny unusable sliver
    } else if pr % 10 == 0 {
        -12.0 // round residual: many item sizes fit
    } else if pr >= half {
        -8.0 // large residual, still very usable
    } else if pr % 5 == 0 {
        -4.0
    } else {
        10.0 // odd/awkward class
    };
    score += class_penalty;

    // Integer-division threshold: how many items of the lookahead size would the post residual hold?
    if next_item_size > 0 {
        let fits_next = pr >= next_item_size;
        if fits_next {
            let count = pr / next_item_size.max(1);
            score -= 6.0 * count as f64; // room for the known next item(s)
        } else {
            score += 18.0; // post residual can't host the lookahead item
        }
        // Modulo coupling: does next item exactly divide the post residual?
        if next_item_size > 0 && pr % next_item_size == 0 && pr > 0 {
            score -= 15.0; // harmonic alignment with lookahead
        }
    } else {
        // Last item: only perfect fits matter.
        score += pr as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 3 {
        score += 3.0 * (fitting_bins_count as f64 - 3.0).min(4.0); // mild de-prioritization when many options
    }

    // New-bin candidate handling: only attractive when item is large relative to mean residual
    // or open bins are mostly full (harmonic capacity fraction threshold).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_frac = mean_residual / cap;
        let item_frac = item_size as f64 / cap;
        if mean_frac < 0.25 && item_frac > 0.5 {
            score -= 20.0; // open fresh bin for big items when existing space is fragmented
        } else {
            score += 35.0; // default: prefer existing bins
        }
        // Late in the stream, waste less: keep new bins expensive.
        if progress > 0.7 {
            score += 10.0 * progress;
        }
    }

    // Tie-break by tightness of fit, scaled by item size class.
    let waste_ratio = post_residual as f64 / cap;
    score += waste_ratio * waste_ratio * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Gaps too small for the next item are also dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize opening new bins, scaled by stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 30.0 * progress + open_bins_count as f64 * 2.0;
    } else {
        // Slight preference for bins tighter than the mean (good packing).
        score += (mean_residual - bin_residual as f64) * 0.1;
    }

    // Reward bins that can still host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain fit: excellent, especially if the second fit is also tight.
            let next_tightness = (post_residual - next_item_size) as f64;
            score -= 150.0 - next_tightness * 2.0;
        } else {
            // Next item won't fit here: penalize leaving awkward residual
            // that is too small to be useful (dead space).
            if post_residual < 10 {
                score += 100.0;
            } else {
                score += (next_item_size - post_residual) as f64 * 0.5;
            }
        }
    }

    // Compare against mean residual: prefer bins that are tighter than average
    // (best-fit-like behavior) when they fit well.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.7 {
        score -= 60.0 * fit_ratio;
    }

    // Penalize bins with residual far above mean (they are wastefully loose)
    // unless this is the only fitting bin.
    let residual_gap = bin_residual as f64 - mean_residual;
    if residual_gap > 0.0 {
        score += residual_gap * 0.3;
    }

    // Last-chance bonus: if this is the only open bin that fits, strongly
    // prefer using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when
    // no open bin offers a decent fit. Make empty bin moderately attractive
    // only when the current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio < 0.5 && post_residual > 30;
        if poor_fit {
            score -= 50.0;
        } else {
            score += 120.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins to build
    // a diverse residual pool; late in the stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 30.0 - progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Dead space penalty: post-residual too small for the smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // next item won't fit here; mild penalty proportional to wasted lookahead
            score += 2.0;
        }
    }

    // Prefer fuller bins over emptier ones when residuals are similar.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.3 * dev;

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // (post_residual large means this bin is a poor fit anyway).
    if bin_residual == bin_capacity {
        score += 18.0;
        // Late in the stream, opening new bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // If next item is large, a fresh bin is more flexible.
        if next_item_size >= item_size {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post-residual in [0,1]

    // Base: quadratic penalty on wasted space, weighted by stream progress
    let mut score = 2.0 * x + 3.0 * x * x;

    // Smooth progress coupling: later in stream, punish large residuals harder
    let progress_weight = 1.0 + 4.0 * progress * progress;
    score += progress_weight * x * x;

    // Reward tight fits (small post-residual) smoothly via cubic term
    score -= (1.0 - x) * (1.0 - x) * (1.0 - x) * 2.5;

    // Penalize bins whose residual deviates from mean residual (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.8 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 6.0;
    } else {
        // Mild penalty spread across many fitting bins to prefer concentrated fills
        score += (fitting_bins_count as f64).ln().max(0.0) * 0.3;
    }

    // Lookahead: reward if next item could fit into the resulting residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 1.5 * (1.0 - slack) * (1.0 - progress);
        } else {
            // post-residual too small for next item: mild penalty, worse early
            score += 1.0 * (1.0 - progress) * x;
        }
    }

    // New-bin candidate: empty bin has high residual; make it unattractive unless
    // no open bin fits well (post_residual == item_size would mean perfect fit anyway)
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * (1.0 - progress);
    }

    // Mild preference for fewer open bins early on
    score += 0.05 * (open_bins_count as f64).sqrt() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals 1..=9 are nearly unusable (min item is 10... but sizes 1..100 possible).
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 19 {
        score += 15.0;
    }

    // Harmonic class of post_residual: divisible by large item classes keeps bin usable.
    let cap = bin_capacity as f64;
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;

    if post_residual == half || post_residual == third || post_residual == quarter {
        score -= 40.0; // canonical residual values are highly reusable
    }
    if post_residual >= half {
        score -= 20.0; // large residual = flexible bin
    } else if post_residual >= third {
        score -= 10.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it packs
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 200.0; // chained perfect fit
            } else if slack <= 9 {
                score += 10.0; // would create dead space after next item
            } else {
                score -= 30.0;
            }
        } else {
            // next item won't fit here; if this is the only fitting bin, mild penalty
            // (encourages saving tight bins for the future item)
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, scaled by how many bins already fit the item
        score += 45.0 + 12.0 * fitting_bins_count as f64;
        // late in the stream, opening new bins is cheaper than fragmenting
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * progress;
        // if next item is large and mean residual is low, new bin is attractive
        if next_item_size as f64 > 0.6 * cap {
            score -= 15.0;
        }
    }

    // Slight preference for tighter bins among open bins (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    // Tie-break: prefer bins whose residual is close to mean (balance load).
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small for any future item
    // (assume minimum plausible item ~ 10) are pure waste -> heavy penalty.
    if post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual < 20 {
        // Semi-dead zone: only very small items can use it.
        score += 15.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward tight fits (post_residual near zero but still usable).
    if post_residual >= 10 {
        score -= 12.0 * (1.0 - post_residual as f64 / 30.0).max(0.0);
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into
    // existing bins (penalize the empty new-bin candidate).
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
        // If next item could pair with this item in a fresh bin, soften slightly.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity && open_bins_count < 3 {
            score -= 6.0;
        }
    }

    // Slight preference for bins below mean residual (keeps residuals uniform,
    // leaving large gaps concentrated in fewer bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Early in the stream, allow new bins more freely (exploration).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits perfectly here -> strong bonus.
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 25.0 + 20.0 * tightness;
        } else if next_item_size <= bin_residual {
            // Next item fits here only if this item goes elsewhere; mild penalty.
            score += 5.0;
        } else {
            // Next item won't fit either way; small bonus to keep bin alive.
            score -= 3.0;
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 10.0;
    }

    // Reward near-perfect fits of the current item (small post residual).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    } else if post_residual < 20 {
        score -= 5.0;
    }

    // Penalize creating dead space relative to the mean residual of open bins.
    if post_residual as f64 > mean_residual + 15.0 {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when nothing fits well or stream is early.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins more as the stream progresses and bins exist.
        score += 35.0 * desperation + 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 && open_bins_count > 0 {
            score += 10.0; // keep existing bins for future pairings
        }
    }

    // Slight preference for bins already below mean residual (consolidating space).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins where post_residual is small relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 18.0;

    // Penalize small dead space that nothing can use, reward mid-range residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 6.0; // usable pocket for small future items
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; slight penalty if we'd strand space.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item in stream: prefer fullest packing.
        score -= 20.0;
    }

    // Prefer bins below mean residual (pack fuller bins first) to consolidate space.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Time horizon: early in the stream, be conservative about opening new bins;
    // late in the stream, consolidate into existing bins even more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if current bins are fragmented
        // or the item is large and fits poorly elsewhere.
        score += 12.0 - 10.0 * progress;
        score += mean_residual * 0.10;
        if item_size > 60 {
            score -= 8.0;
        }
    } else {
        score -= 5.0 + 5.0 * progress;
    }

    // Mild penalty for proliferating bins.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;
    // smooth non-linear coupling: post_residual shaped by stream progress
    score += 24.0 * norm_post * norm_post * (0.5 + progress);
    score -= 18.0 * norm_item * norm_post * (1.0 - progress);
    // dead-space penalty: very small post residual is good, mid-range is bad
    score += 12.0 * (norm_post * (1.0 - norm_post)) * (1.0 - progress);
    // lookahead bonus: next item fits into post residual
    if next_item_size > 0 {
        let nd = next_item_size as f64 / bin_capacity as f64;
        if next_item_size <= post_residual {
            score -= 10.0 * nd * (0.5 + progress);
        } else {
            score += 6.0 * nd * (1.0 - norm_post);
        }
    }
    // last-chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_post);
    }
    // prefer bins tighter than the mean residual
    score += 4.0 * ((post_residual as f64) - mean_residual) / bin_capacity as f64;
    // slight penalty for spreading across too many bins late in the stream
    score += (open_bins_count as f64).ln() * norm_post * progress;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (large enough to host common small items) are rewarded.
    let pr = post_residual;
    let usable = if pr >= 10 && pr <= 20 {
        // prime leftover zone: likely dead space for typical item sizes
        -1.0
    } else if pr == 0 {
        6.0 // perfect fit
    } else if pr % 10 == 0 {
        3.0 // round leftover, easy to fill
    } else if pr >= 21 && pr <= 40 {
        1.5 // mid zone, still hostable by many items
    } else if pr > 40 {
        2.5 // large residual, flexible
    } else {
        0.0
    };
    score -= usable;

    // Modulo coupling between post_residual and next item: if the next item
    // divides/aligns with the leftover, this bin is a great chain candidate.
    if next_item_size > 0 && pr > 0 {
        if next_item_size == pr {
            score -= 8.0;
        } else if pr % next_item_size == 0 && pr >= next_item_size {
            score -= 4.0;
        } else if next_item_size % pr == 0 && pr >= 10 {
            score -= 2.0;
        }
        // penalize leftovers in the awkward band just below the next item
        if pr < next_item_size && pr >= (next_item_size as f64 * 0.5) as u32 {
            score += 3.0;
        }
    }

    // Integer-division thresholds on residual fraction of capacity.
    let frac = pr as f64 / bin_capacity as f64;
    let div_class = (pr * 4) / bin_capacity; // quarter classes 0..3
    match div_class {
        0 => score += 2.0 * frac,      // nearly full bin: small bonus to close it out
        1 => score -= 1.0,             // 25-50% residual: decent
        2 => score -= 0.5,             // 50-75% residual
        _ => {}                        // mostly empty
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Prefer tighter bins when many bins are open (consolidation pressure).
    score += (mean_residual - bin_residual as f64).abs() * 0.05;
    score -= (open_bins_count as f64).ln().max(0.0) * 0.2 * (1.0 - frac);

    // Mild novelty penalty for opening a brand-new bin unless stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 4.0 - 3.0 * progress;
        // opening a new bin is attractive if no open bin leaves a good residue
        if post_residual + item_size == bin_capacity && item_size >= 50 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Super-linear waste penalty: tiny leftovers are nearly unusable later.
    if post_residual == 0 {
        score -= 70.0;
    } else if post_residual < 8 {
        score += 30.0;
    } else if post_residual < 16 {
        score += 12.0;
    } else if post_residual as f64 > cap * 0.6 {
        score -= 10.0; // large leftover is flexible space
    }

    // Lookahead chain: how well does post_residual serve the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 55.0;
            } else if slack < 8 {
                score -= 25.0;
            } else if slack < 25 {
                score -= 10.0;
            } else {
                score -= 4.0;
            }
        } else {
            // Dead space for next item: penalize proportionally to what's stranded.
            score += 10.0 + (next_item_size as f64) * 0.2;
        }
    }

    // Two-item lookahead: if next item also fits a known residual pattern, favor tight fills.
    if next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && rem2 < item_size {
            score -= 6.0; // leftover then too small for similar items: good compaction
        }
    }

    // Last-chance bin: strong consolidation pressure.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    // New-bin candidate: open only under saturation pressure or early flexibility.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if pressure < 0.22 || (progress < 0.15 && open_bins_count < 4) {
            score -= 25.0;
        } else {
            score += 18.0;
        }
    }

    // Prefer bins below mean residual, scaled by how tight the packing is.
    let tightness = 1.0 - mean_residual / cap;
    score += (mean_residual - bin_residual as f64) * (0.2 + 0.4 * tightness);

    // Consolidation: mild penalty per open bin, stronger late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 + 0.6 * progress);

    // Complementarity: medium leftovers pair with mid-size items.
    if post_residual >= 10 && post_residual < 30 && item_size >= bin_capacity / 4 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Waste-centric core: penalize leftover space weighted by how hard it is to reuse.
    // Small leftovers (< ~capacity/8) are the main source of waste; large leftovers stay usable.
    let small_thresh = bin_capacity / 8;
    if post_residual == 0 {
        score -= 70.0; // perfect fit: strongest reward
    } else if post_residual < small_thresh {
        // Super-linear dead-space penalty scaled by item's own size share.
        let tightness = item_size as f64 / cap_f;
        score += 30.0 + 40.0 * (1.0 - post_residual as f64 / small_thresh as f64) * (0.5 + tightness);
    } else if post_residual < 2 * small_thresh {
        score += 8.0;
    } else {
        // Large leftover is reusable: mild reward, stronger if it can host the next item.
        score -= 6.0;
    }

    // Lookahead chain bonus: does the post residual serve the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 55.0; // perfect chain
            } else if slack < small_thresh {
                score -= 25.0;
            } else {
                score -= 8.0;
            }
        } else {
            // Leftover is dead for next item; penalize more when next item is large
            // (large next items need big chunks, so preserve big residuals).
            let next_frac = next_item_size as f64 / cap_f;
            score += 10.0 + next_frac * 25.0;
        }
    }

    // Last-chance bin: strong preference to fill the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: open a fresh bin only under saturation pressure or early flexibility.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap_f;
        if pressure < 0.30 {
            score -= 25.0;
        } else {
            score += 18.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.15 {
            score -= 6.0;
        } else if progress > 0.85 {
            // Late stream: closing out — strongly discourage new bins.
            score += 12.0;
        }
    }

    // Prefer bins below mean residual (balance), but damp when many bins are open
    // to avoid spreading load across too many bins.
    let balance_gain = if open_bins_count > 8 { 0.15 } else { 0.35 };
    score += (mean_residual - bin_residual as f64) * balance_gain;

    // Consolidation pressure: penalize open-bin count, growing mildly with progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 + 0.5 * progress);

    // Harmonic pairing: even-decile items pair well with mid-range leftovers.
    let frac = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if frac % 2 == 0 && post_residual >= 10 && post_residual < 30 {
        score -= 4.0;
    }

    // Big-item urgency: when the current item is large, prefer the tightest possible
    // placement so large leftovers survive for other large items.
    if item_size * 2 >= bin_capacity && post_residual > 0 && post_residual < item_size {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Base: two-step waste — leftover remaining after ideally seating the
    // lookahead item in this bin as well.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Aggressive exact two-step match: the lookahead item would close this bin
    // perfectly after placement.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 12.0 + 6.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        // Snug chain fit: small slack after seating the next item.
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 5.0;
        } else if slack < 20 {
            score -= 2.0;
        }
    }

    // Perfect closure: item exactly fills the bin now.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 10 {
        // Tiny leftovers are near-dead space; strong penalty.
        score += 8.0;
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Dead-space risk: leftover smaller than the incoming lookahead item.
    if nxt > 0.0 && post > 0.0 && post < nxt {
        score += 0.5 * (nxt - post).min(cap) + 4.0;
    }

    // Mean-relative coupling: penalize leftovers above the average slack.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Relative-waste refinement: penalize the fraction of the bin left empty.
    score += 0.3 * (post / resid);

    // Last-chance fitting bin: strongly prefer the only open bin that fits,
    // to avoid opening an unnecessary new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 8.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 1.5;
    }

    // Opening cost for a brand-new bin: only attractive when open bins are
    // nearly saturated (mean slack low); otherwise penalize fresh capacity.
    if is_new_bin {
        let pressure = mean / cap;
        if pressure < 0.25 {
            score -= 6.0 + 3.0 * progress;
