    // Refinement 1: graded snugness — scale the reward with how close the fit is.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        if snug < 15.0 {
            score -= 1.0 * (1.0 - snug / 15.0);
        }
    }

    // Refinement 2: lookahead chain — reusable leftover that can host the next item
    // and still leave room within the current item's size class.
    if nxt > 0.0 && post_residual >= next_item_size && next_item_size > 0 {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
    }

    // Refinement 3: dead-space ratio penalty — penalize leftovers that exceed the
    // mean slack by a large fraction of capacity (unrecoverable voids).
    if post > mean && cap > 0.0 {
        let excess_ratio = (post - mean) / cap;
        if excess_ratio > 0.15 {
            score += 2.0 * excess_ratio;
        }
    }

    // Mutation A: prefer the fullest fitting bin via explicit residual tiebreak.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
    }

    // Mutation B: near-closure the next item cannot use — amplify the reward.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // Mutation C: new-bin gate — open a fresh bin only when fits elsewhere are poor.
    if is_new_bin && nxt > 0.0 {
        let fits_poorly = fitting_bins_count > 0 && (bin_capacity as f64 - mean) > item_size as f64 * 1.5;
        if fits_poorly {
            score -= 3.0;
        }
    }

    // Mutation D (gen 9): continuous fine-grained snugness — smooth quadratic reward
    // for tight fits up to a quarter of capacity, replacing hard thresholds with a
    // graded curve so near-perfect placements dominate everywhere.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        let scale = cap * 0.25;
        if snug < scale {
            score -= 3.0 * (1.0 - snug / scale) * (1.0 - snug / scale);
        }
    }

    // Mutation E (gen 9): lookahead-aware dead-space avoidance — if the post-fit
    // leftover cannot host the next item, penalize proportionally to how much of
    // the next item's demand is stranded, scaled by remaining stream length.
    if nxt > 0.0 && post_residual > 0 && post_residual < next_item_size {
        let stranded = (next_item_size - post_residual) as f64;
        score += (stranded / cap) * (4.0 + 6.0 * progress);
    }

    // Mutation F (gen 9): two-step compaction chain — reward bins where the current
    // item AND the next item both fit with a small combined remainder, encouraging
    // deep lookahead packing into a single bin.
    if nxt > 0.0 && post_residual >= next_item_size {
        let tail = post_residual - next_item_size;
        if tail <= 3 {
            score -= 4.0 + 3.0 * (1.0 - progress);
        } else if tail <= 8 {
            score -= 2.0;
        }
    }

    // Mutation G (gen 9): adaptive new-bin threshold — when many bins are open and
    // the item fits none of them well (residual margin large), discourage opening
    // unless the mean slack genuinely cannot host the item.
    if is_new_bin && fitting_bins_count == 0 && open_bins_count > 3 {
        if (mean as u32) >= item_size {
            score += 10.0; // some open bin could have hosted it — punish new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: penalize wasted residual, quadratic in normalized post residual
    let mut score = norm_pr * norm_pr * cap;

    // Smooth non-linear coupling: post residual weighted by stream progress
    score += 30.0 * norm_pr * (progress * progress);

    // Tight fit reward, smoothly scaled by progress
    score -= 25.0 * fit * (1.0 - fit) * (1.0 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - norm_pr);
    }

    // Dead-space penalty if residual too small for typical next item (smooth via ratio)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let unusable = (norm_pr - nx).max(0.0);
        let waste = (nx - norm_pr).max(0.0);
        score += 20.0 * waste * waste * cap / cap;
        score -= 10.0 * unusable * (1.0 - progress);
    }

    // Mild spread penalty relative to mean residual (smooth)
    score += 0.5 * (norm_pr * cap - mean_residual).abs() / (1.0 + progress);

    // New-bin candidate: penalize mildly, softened late in stream
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Base: two-step waste — leftover after ideally seating the lookahead item too.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Aggressive exact two-step match: lookahead item would close this bin perfectly.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 12.0 + 6.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 5.0;
        } else if slack < 20 {
            score -= 2.0;
        }
    }

    // Perfect closure: item exactly fills the bin now.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 10 {
        score += 8.0;
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Dead-space risk: leftover smaller than the incoming lookahead item.
    // MUTATION: scale penalty by how far below the next item the leftover falls,
    // and by stream progress (late-stream dead space is more costly).
    if nxt > 0.0 && post > 0.0 && post < nxt {
        let dead_frac = (nxt - post) / nxt;
        score += 0.5 * (nxt - post).min(cap) + 4.0 + 3.0 * dead_frac * (0.5 + progress);
    }

    // Mean-relative coupling: penalize leftovers above the average slack.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Relative-waste refinement: penalize the fraction of the bin left empty.
    score += 0.3 * (post / resid);

    // Last-chance fitting bin: strongly prefer the only open bin that fits.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 8.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 1.5;
    }

    // Opening cost for a brand-new bin: only attractive when open bins are nearly saturated.
    // MUTATION: couple the opening decision to the lookahead item — a fresh bin is
    // more attractive when the next item is large (existing bins will be fragmented).
    if is_new_bin {
        let pressure = mean / cap;
        let nxt_large = nxt / cap;
        let lookahead_bonus = if nxt_large > 0.5 { 2.0 } else { 0.0 };
        if pressure < 0.25 {
            score -= 6.0 + 3.0 * progress + lookahead_bonus;
        } else if pressure < 0.45 {
            score += 1.0 + 3.0 * progress + lookahead_bonus;
        } else {
            score += 8.0 + 5.0 * progress + lookahead_bonus;
        }
    }

    // Consolidation pressure: many open bins favor filling existing ones.
    score += open_bins_count as f64 * 0.05;

    // Reward bins whose residual exactly matches the next item size (two-bin chain closure).
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Penalize residual too small for both current and next item — stranded dead space.
    // MUTATION: graded penalty proportional to the shortfall ratio.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 2.5 * (1.0 - progress) + 2.0 * (1.0 - post / nxt);
    }

    // Tight absolute fit regardless of lookahead.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing: small leftovers pair with even-class items, making them reusable.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.0;
    }

    // Endgame tightening — late in the stream, avoid opening bins unless nearly closed.
    if progress > 0.85 && is_new_bin {
        score += 6.0 * (progress - 0.85) / 0.15;
    }

    // Snug fit now, independent of lookahead — encourages closing bins fully.
    if !is_new_bin && bin_residual >= item_size {
        let snug = bin_residual - item_size;
        if snug < 5 {
            score -= 2.5;
        }
    }

    // Refinement 1: graded snugness — scale the reward with how close the fit is,
    // so near-perfect placements beat merely-tight ones.
    // MUTATION: widen the snugness window slightly and weight by remaining stream.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        if snug < 20.0 {
            score -= (1.0 + 0.5 * progress) * (1.0 - snug / 20.0);
        }
    }

    // Refinement 2: lookahead chain — if the post-fit residual can also host the
    // item after next (two-item lookahead depth), reward the reusable leftover.
    if nxt > 0.0 && post_residual >= next_item_size && next_item_size > 0 {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
    }

    // Refinement 3: dead-space ratio penalty — penalize leftovers that exceed the
    // mean slack by a large fraction of capacity (unrecoverable voids).
    // MUTATION: sharper knee and stronger slope for extreme voids.
    if post > mean && cap > 0.0 {
        let excess_ratio = (post - mean) / cap;
        if excess_ratio > 0.12 {
            score += 3.0 * excess_ratio;
        }
    }

    // Refinement 4 (new): reusable-void check — a large leftover is only acceptable
    // if it can still host the next item; otherwise penalize proportionally to
    // how much capacity is stranded relative to the next item.
    if nxt > 0.0 && !is_new_bin && post >= nxt {
        let usable = post - nxt;
        if usable > 0.0 && usable < 0.25 * cap {
            score += 1.0 * (1.0 - usable / (0.25 * cap));
        }
    }

    // Refinement 5 (new): when several bins fit, prefer the one whose post-residual
    // is closest to a multiple of typical small item sizes (divisibility pairing).
    if !is_new_bin && fitting_bins_count > 1 && post_residual > 0 {
        let half_cap = cap / 2.0;
        if (post - half_cap).abs() < 3.0 {
            score -= 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: residues mod 10 define "dead-space bands".
    // Residues 1..9 (non-zero, small) are awkward gaps; 0 and exact-halves are good.
    let post_mod = post_residual % 10;
    let post_mod_f = post_mod as f64;
    if post_mod != 0 {
        // penalize awkward residues more the smaller they are (unusable slivers)
        score += (10.0 - post_mod_f) * 1.5;
    } else {
        score -= 6.0; // residue 0: perfectly harmonic gap
    }

    // Exact-fraction classes of post_residual w.r.t. capacity: 0, 1/4, 1/3, 1/2, 2/3, 3/4
    let fracs = [0u32, 25, 33, 50, 66, 75];
    let mut harmonic_bonus = 0.0;
    for &f in &fracs {
        if (post_residual as i64 - (bin_capacity as i64 * f as i64) / 100).abs() <= 1 {
            harmonic_bonus = match f {
                0 => 18.0,
                25 | 75 => 10.0,
                33 | 66 => 8.0,
                50 => 14.0,
                _ => 0.0,
            };
            break;
        }
    }
    score -= harmonic_bonus;

    // Small post_residual that is nonzero => dead space; big penalty via quadratic term
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post) * (10.0 - post) * 0.6;
    }

    // --- Next-item harmonic coupling: does next item divide into post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let nxt_mod = next_item_size % 10;
            // reward if next item's harmonic class matches the gap class
            if nxt_mod == post_mod && post_mod != 0 {
                score -= 5.0;
            }
            // exact fill by next item is excellent
            if next_item_size == post_residual {
                score -= 20.0;
            } else {
                let rem2 = post_residual - next_item_size;
                // penalize leaving another awkward sliver for the step after next
                let rem2_mod = rem2 % 10;
                if rem2_mod != 0 && rem2 < 10 {
                    score += (10 - rem2_mod) as f64 * 0.8;
                }
            }
        } else {
            // next item cannot use this gap at all: gap is likely permanent dead space
            score += nxt * 0.15;
        }
    }

    // --- Tightness reward: relative fill of the bin by this item
    score -= (item / cap) * 12.0;

    // --- Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // --- New-bin candidate handling: bin_residual == bin_capacity
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin; offset if current fit is poor
        score += 8.0;
        // if placing here leaves a bad residue in an existing bin elsewhere,
        // new bin becomes attractive when item is large (fewer future fragments)
        if post_mod != 0 && post_residual < 20 {
            score -= 12.0;
        }
        // large items start fresh bins happily (classic best-fit behavior)
        if item_size >= 50 {
            score -= 4.0;
        }
    }

    // --- Stream progression: late in stream, prefer closing bins tightly
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * (1.0 - post / cap);

    // --- Congestion: many open bins => consolidate, penalize spreading
    if open_bins_count > 4 {
        score += (open_bins_count as f64).ln() * 2.0;
    }

    // --- Mean residual context: bins far below mean residual are poor targets
    let dev = mean_residual - post;
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
