        if snug < 15.0 {
            score -= 1.0 * (1.0 - snug / 15.0);
        }
    }

    // Refinement 2: lookahead chain — if the post-fit residual can also host the
    // item after next (two-item lookahead depth), reward the reusable leftover.
    if nxt > 0.0 && post_residual >= next_item_size && next_item_size > 0 {
        let second_left = post_residual - next_item_size;
