        }
    }

    // Refinement 4: reusable-void check — a large post-fit residual is only bad if
    // it cannot host the lookahead item; if it can, reward its continued usability
    // proportionally to how much of it remains after the next item seats.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

