    // one whose post-residual stays closest to the mean slack (keeps the open-bin
    // pool homogeneous and future-fit).
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny sliver = pure waste
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0; // only fits the smallest items
    }

    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward residual that still accommodates typical small items (>=10).
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits into post_residual, this placement is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + next_item_size as f64 * 0.2;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.5 + 2.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins are healthy, allow when desperate.
        score += 20.0 + pressure * 3.0 - (mean_residual - item_size as f64).max(0.0) * 0.5;
    } else {
        // Consolidation bonus: filling fuller bins first.
        score -= (bin_capacity - bin_residual) as f64 * 0.15;
        // Mild penalty for using a bin far below mean residual (fragmentation risk).
        if (bin_residual as f64) > mean_residual + 30.0 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
