    }

    // NEW: variance-aware consolidation — when residual spread is low (homogeneous pool),
    // keep it homogeneous: penalize outliers from the mean more aggressively.
    if !is_new_bin && mean > 0.0 && cap > 0.0 {
        let rel_dev = ((post - mean) / mean).abs();
        if rel_dev > 0.6 {
            score += 1.0 * (rel_dev - 0.6).min(2.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
