    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Base: two-step waste — leftover after ideally seating the lookahead item too.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Aggressive exact two-step match: lookahead item would close this bin perfectly.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 14.0 + 7.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 6.0;
        } else if slack < 20 {
            score -= 2.5;
        }
    }

    // Perfect closure: item exactly fills the bin now.
    if post_residual == 0 {
        score -= 22.0;
    } else if post_residual < 10 {
        score += 8.0;
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Dead-space risk: leftover smaller than the incoming lookahead item.
    // Strengthened: scale waste by the fraction of the next item that cannot fit,
    // and weight more heavily early in the stream where dead space compounds.
    if nxt > 0.0 && post > 0.0 && post < nxt {
        let waste_frac = (nxt - post) / nxt;
        score += 0.7 * (nxt - post).min(cap) + 4.5 + 4.0 * waste_frac * (1.0 - 0.5 * progress);
    }

    // Mean-relative coupling: penalize leftovers above the average slack.
    if post > mean {
        score += 0.18 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Relative-waste refinement: penalize the fraction of the bin left empty.
    score += 0.3 * (post / resid);

    // Last-chance fitting bin: strongly prefer the only open bin that fits.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 9.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 1.5;
    }

    // Opening cost for a brand-new bin: only attractive when open bins are nearly saturated.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.25 {
            score -= 6.0 + 3.0 * progress;
        } else if pressure < 0.45 {
            score += 1.0 + 3.0 * progress;
        } else {
            score += 8.0 + 5.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 2.0;
        }
    }

    // Consolidation pressure: many open bins favor filling existing ones.
    score += open_bins_count as f64 * 0.05;

    // Reward bins whose residual exactly matches the next item size (two-bin chain closure).
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.5 + 4.0 * (1.0 - progress);
    }

    // Penalize residual too small for both current and next item — stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 3.0 * (1.0 - progress);
    }

    // Tight absolute fit regardless of lookahead.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing: small leftovers pair with even-class items, making them reusable.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.0;
