            score += 2.0 * excess_ratio + 4.5 * (excess_ratio - 0.15);
        }
    }

    // Reusable-void check — reward post-fit residual that can host the lookahead item,
    // proportional to how much of it remains usable.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.6 * (usable / cap);
        }
    }

    // Fragmentation guard — keep the open-bin pool homogeneous near the mean slack.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // NEW: dead-space utilization trade-off — when the post-fit residual is stranded
    // (cannot host the next item) but another small increment would have made it usable,
    // penalize proportionally; conversely reward placements that keep the residual
    // just above a "useful size" band so future small items can still land there.
    if !is_new_bin && nxt > 0.0 && post > 0.0 && post < nxt {
        let gap = nxt - post;
        if gap <= 5.0 {
            // Nearly-usable void: a tiny future item rescues it — soften penalty.
            score -= 1.5 * (1.0 - gap / 5.0);
        } else if gap > 20.0 {
