            score -= 0.8;
        }
    }

    // NEW: lookahead saturation guard — if the next item is large relative to
    // capacity, avoid creating mid-range residuals that neither it nor typical
    // items can use; instead prefer either near-full or highly reusable outcomes.
    if nxt > 0.5 * cap && !is_new_bin && post > 0.0 && post < nxt {
        score += 2.0 * (1.0 - progress);
    }

    score
}

