    // just below that band where space strands.
    if !is_new_bin && post_residual > 0 {
        let pr = post_residual as f64;
        if pr >= 15.0 && pr <= 35.0 {
            score -= 1.8 * (1.0 - 0.5 * progress);
        } else if pr > 35.0 && nxt > 0.0 && pr < nxt {
            // stranded zone: too big to ignore, too small to be useful
            score += 1.2 + 0.04 * (pr - 35.0);
        }
    }

    // Mutation K (new): best-fit sharpening — among fitting bins, scale the
    // preference for minimal leftover by how many alternatives exist; with
    // many options, commit harder to the tightest fit to preserve big voids.
    if !is_new_bin && bin_residual >= item_size {
        let leftover = (bin_residual - item_size) as f64;
        let alternatives = fitting_bins_count.max(1) as f64;
        score += 0.10 * (leftover / cap) * (1.0 + (alternatives - 1.0).min(4.0) * 0.25);
