        let slack_pressure = mean / cap;
        if slack_pressure > 0.35 && progress < 0.5 {
            score += 2.5 * (0.5 - progress);
        } else if slack_pressure < 0.15 && fitting_bins_count > 0 {
            score += 4.0;
        }
    }

    score
}

