    // post-residual lands close to the mean slack, creating uniform
    // residuals that future medium items can still fill.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let target = post - nxt;
        let dist = (target - mean).abs();
        if dist < 6.0 {
            score -= 1.2 * (1.0 - dist / 6.0);
        }
    }

    // Mutation L (new): waste-fraction floor — penalize bins where the
    // fraction of capacity stranded (unusable by next item) is high,
    // with a mid-stream emphasis where consolidation still pays off.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size && cap > 0.0 {
        let stranded_frac = post / cap;
        if stranded_frac < 0.12 && progress > 0.2 && progress < 0.9 {
            score += 2.0 * (1.0 - stranded_frac / 0.12);
        }
    }

    score
}

