    if !is_new_bin && post_residual >= 1 && post_residual <= 10 {
        score -= 0.5 + 0.04 * open_bins_count.min(40) as f64;
    }

    // Mutation O (new): new-bin threshold tied to best available slack —
    // only open a fresh bin when the mean residual suggests open bins are
