    if is_new_bin && nxt > 0.0 && fitting_bins_count > 0 {
        let usable_elsewhere = (fitting_bins_count as f64) * (mean - item_size as f64).max(0.0);
        let need_horizon = nxt * (1.0 + progress);
        if usable_elsewhere < need_horizon {
            score -= 2.5 + 2.0 * (1.0 - usable_elsewhere / need_horizon.max(1.0));
