    // number of open bins since more bins amplify fragmentation cost.
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let pull = ((post - mean) / cap).abs();
        let strength = 0.10 + 0.006 * open_bins_count.min(50) as f64;
        score += strength * pull * 10.0 * (1.0 - 0.3 * progress);
    }

    score
