            score += 4.0 + 2.0 * (1.0 - progress);
        }
    }

    // Mutation P (new): dead-space-ratio refinement — the diagnosed weakness is
    // residual dead space. Sharpen the post-vs-mean dead-space wedge into a
    // quadratic penalty on the fraction of capacity stranded below the next
    // item's reach, weighted by how many alternative bins exist (with more
    // alternatives, choosing a dead-space bin is less justified).
    if !is_new_bin && nxt > 0.0 && post_residual > 0 && post_residual < next_item_size {
        let stranded = nxt - post;
        let stranded_frac = stranded / nxt;
        let alt_pressure = 1.0 - 1.0 / (fitting_bins_count.max(1) as f64);
        score += 3.2 * stranded_frac * stranded_frac * stranded * alt_pressure * (0.5 + 0.5 * progress);
