        let after = (post_residual - next_item_size) as f64;
        if after >= 1.0 && after <= 12.0 {
            score -= 2.2 * (1.0 - after / 13.0) * (0.6 + 0.4 * progress);
        }
        let mean_dist = (after - mean).abs();
        if mean_dist <= 4.0 {
            score -= 1.0 * (1.0 - mean_dist / 5.0);
        }
    }

