        let x = (after / cap).min(1.0);
        let bump = 4.0 * x * (1.0 - x);
        score += 1.2 * bump * (0.5 + 0.5 * progress);
    }

    // Mutation Q: utilization-maximizing tiebreak (concave sqrt preference).
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Mutation R: lookahead-aware new-bin arbitration.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let open_can_chain = fitting_bins_count > 0
            && mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        let new_can_chain = new_post >= nxt;
        if open_can_chain && !new_can_chain {
            score += 5.0 + 3.0 * (1.0 - progress);
        } else if !open_can_chain && new_can_chain {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Mutation S: residual-variance damping.
    if !is_new_bin && mean > 0.0 {
        let dev = (post - mean) / cap;
        score += 1.0 * dev * dev * (1.2 - 0.6 * progress);
    }

    // Mutation T (gen 16): dead-space ratio targeting — when the post-residual
    // after the current item is a nontrivial dead fraction that cannot host
    // the lookahead item, penalize proportionally to how close it is to
    // "half-unusable" (the worst dead-space zone), sharpened late in the
    // stream when residual variance matters most.
    if !is_new_bin && nxt > 0.0 && post > 0.0 && post < nxt {
        let dead_frac = post / nxt;
        // Worst zone: dead space just below half the lookahead need.
        let zone = 1.0 - (dead_frac - 0.5).abs() * 2.0;
        if zone > 0.0 {
            score += 1.0 * zone * (0.6 + 0.8 * progress);
        }
    }

    // Mutation U (gen 16): exact-fill attraction via lookahead — reward bins
    // where the current item plus the next item exactly fills the bin, a
    // strong compaction signal that the parent only partially captures
    // (equality check was on post-residual only, missed via mean coupling).
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size && next_item_size <= 25 {
        score -= 2.5 * (1.0 - progress);
    }

    // Mutation V (gen 16): new-bin dead-space precheck — when opening a fresh
    // bin, penalize if the resulting residual is in the awkward mid-band
    // (25..60) that rarely hosts future items, and reward if it lands near a
    // reusable small residual. This tightens the opening decision.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if new_post >= 25.0 && new_post <= 60.0 {
            score += 2.0 * (1.0 - (new_post - 25.0) / 35.0) * (0.5 + 0.5 * progress);
        } else if new_post >= 1.0 && new_post <= 12.0 {
            score -= 1.5 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Base: two-step waste — leftover after ideally seating the lookahead item too.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Aggressive exact two-step match.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 12.0 + 6.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 5.0;
        } else if slack < 20 {
            score -= 2.0;
        }
    }

    // Perfect closure / small leftovers.
    if post_residual == 0 {
        score -= 24.0;
    } else if post_residual < 10 {
        score += 9.0 + 2.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Dead-space risk: quadratic waste penalty scaled by wasted fraction.
    if nxt > 0.0 && post > 0.0 && post < nxt {
        let waste_frac = (nxt - post) / nxt;
        score += 0.5 * (nxt - post).min(cap)
            + 4.0
            + 3.0 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.0 * waste_frac * (1.0 - progress);
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Void fraction, graded harder for large voids.
    let void_frac = post / resid;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.5 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 8.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 1.5;
    }

    // Opening cost for a brand-new bin.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 6.0 + 3.0 * progress;
        } else if pressure < 0.45 {
            score += 1.0 + 3.0 * progress;
        } else {
            score += 8.0 + 5.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.05;

    // Chain closure: residual exactly matches next item size.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 2.5 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.0;
    }

    // Endgame tightening.
    if progress > 0.85 && is_new_bin {
        score += 6.0 * (progress - 0.85) / 0.15;
    }

    // Snug fit, graded.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        if snug < 5.0 {
            score -= 2.5;
        }
        if snug < 15.0 {
            score -= 1.0 * (1.0 - snug / 15.0);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
    }

    // Dead-space ratio penalty, graded.
    if post > mean && cap > 0.0 {
        let excess_ratio = (post - mean) / cap;
        if excess_ratio > 0.15 {
            score += 2.0 * excess_ratio + 4.0 * (excess_ratio - 0.15);
        }
    }

    // Reusable-void check.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin via residual tiebreak.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // New-bin gate: open a fresh bin only when fits elsewhere are poor.
    if is_new_bin && nxt > 0.0 {
        let fits_poorly = fitting_bins_count > 0 && (bin_capacity as f64 - mean) > item_size as f64 * 1.5;
        if fits_poorly {
            score -= 3.0;
        }
    }

    // Depth-2 lookahead: small residual matching a future item class.
    if nxt > 0.0 && post_residual >= next_item_size {
        let two_left = post_residual - next_item_size;
        if two_left > 0 && two_left <= 10 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Exact-fit chain: post residual equals next item size with a small item.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size && next_item_size <= item_size {
        score -= 3.0 * (1.0 - progress);
    }

    // Mutation F: lookahead-aware dead-space hedge (sharpened weight).
    if nxt > 0.0 && !is_new_bin && post_residual < next_item_size && progress > 0.1 {
        let unusable = (next_item_size - post_residual) as f64;
        score += 0.75 * unusable * (1.0 - progress);
    }

    // Mutation G: residual homogeneity.
    if !is_new_bin && mean > 0.0 {
        let hom = ((post - mean).abs() / cap) as f64;
        score -= 0.8 * (1.0 - hom.min(1.0));
    }

    // Mutation H: dead-space ratio refinement vs fleet-average leftover fraction.
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let post_frac = post / cap;
        let mean_frac = (mean / cap).min(1.0);
        if post_frac > mean_frac {
            score += 3.5 * (post_frac - mean_frac) * (1.0 - 0.4 * progress);
        } else {
            score -= 1.2 * (mean_frac - post_frac);
        }
    }

    // Mutation I: anti-fragmentation sweep on large usable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let usable_left = post_residual - next_item_size;
        if usable_left > 25 {
            score += 0.06 * (usable_left as f64 - 25.0);
        }
    }

    // Mutation J: adaptive fit-quality gate.
    if !is_new_bin && post_residual > 0 {
        let leftover = post_residual as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        if leftover < nxt * 0.35 && nxt > 0.0 {
            score += 1.8 * scarcity * (1.0 - leftover / (nxt * 0.35));
        }
        if fitting_bins_count >= 3 {
            score += 0.05 * leftover;
        }
    }

    // Mutation K: target-residual attraction (widened band).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let target = post - nxt;
        let dist = (target - mean).abs();
        if dist < 8.0 {
            score -= 1.4 * (1.0 - dist / 8.0);
        }
    }

    // Mutation L: waste-fraction floor.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size && cap > 0.0 {
        let stranded_frac = post / cap;
        if stranded_frac < 0.12 && progress > 0.2 && progress < 0.9 {
            score += 2.0 * (1.0 - stranded_frac / 0.12);
        }
    }

    // Mutation M: dead-space-aware bin choice — penalize awkward mid-size leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 25 && after <= 60 {
            let mid_awkward = 1.0 - ((after - 25) as f64 / 35.0);
            score += 1.6 * mid_awkward * (0.4 + 0.6 * progress);
        }
    }

    // Mutation N: residual bucket symmetry — small post-residual bonus grows with open bins.
    if !is_new_bin && post_residual >= 1 && post_residual <= 10 {
        score -= 0.5 + 0.04 * open_bins_count.min(40) as f64;
    }

    // Mutation O: new-bin threshold tied to best available slack.
    if is_new_bin && fitting_bins_count > 0 {
        let avg_slack_after = mean - item_size as f64;
        if avg_slack_after > nxt * 0.5 {
            score += 4.0 + 2.0 * (1.0 - progress);
        }
    }

    // Mutation P: quadratic mid-leftover awkwardness bump.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let bump = 4.0 * x * (1.0 - x);
        score += 1.2 * bump * (0.5 + 0.5 * progress);
    }

    // Mutation Q: utilization-maximizing concave tiebreak.
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Mutation R: lookahead-aware new-bin arbitration.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let open_can_chain = fitting_bins_count > 0
            && mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        let new_can_chain = new_post >= nxt;
        if open_can_chain && !new_can_chain {
            score += 5.0 + 3.0 * (1.0 - progress);
        } else if !open_can_chain && new_can_chain {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Mutation S: residual-variance damping.
    if !is_new_bin && mean > 0.0 {
        let dev = (post - mean) / cap;
        score += 1.0 * dev * dev * (1.2 - 0.6 * progress);
    }

    // Mutation T (gen 15+): two-step dead-space ratio — measure how well the
    // post-residual can be consumed by the lookahead item, expressed as a
    // smooth ratio rather than a hard threshold. Bins whose post-residual is
    // just below the next item (worst case: nearly-fitting but unusable) get
    // a graded penalty; bins that fully absorb the lookahead get a graded
    // reward proportional to how little remains.
    if nxt > 0.0 && !is_new_bin {
        let absorb = (post / nxt).min(1.0);
        if post < nxt {
            // Fraction of the lookahead item that would be stranded.
            score += 1.1 * (1.0 - absorb) * absorb * (1.0 - 0.5 * progress);
        } else {
            let rem_frac = ((post - nxt) / cap).min(1.0);
            score -= 1.3 * absorb * (1.0 - rem_frac);
        }
    }

    // Mutation U (gen 15+): residual-class match reward — if the post-residual
    // (after seating the lookahead) is itself an exact divisor-style match for
    // the current item size class, this bin supports a long chain; reward it.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after == item_size as u32 {
            score -= 3.0 + 2.0 * (1.0 - progress);
        } else if item_size as u32 >= 2 && after % item_size.max(2) == 0 && after > 0 {
            score -= 1.2;
        }
    }

    // Mutation V (gen 15+): scarcity-weighted new-bin veto — when many bins
    // could fit the item, opening a new bin is almost always wasteful; scale
    // the opening penalty with fitting_bins_count so the fresh-bin candidate
    // only wins when it is genuinely the best option.
    if is_new_bin && fitting_bins_count > 0 {
        let veto = (fitting_bins_count as f64).min(6.0);
        score += 0.9 * veto * (1.0 - 0.3 * progress);
    }

    // Mutation W (gen 15+): late-stage compaction — in the final stretch,
    // strongly prefer bins whose post-residual is exactly zero (perfect
    // closure) even at the cost of a slightly worse immediate fit, since
    // closing bins late reduces the stranded-residual tail.
    if !is_new_bin && post_residual == 0 && progress > 0.6 {
        score -= 10.0 * (progress - 0.6) / 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
