    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Base: two-step waste — leftover after ideally seating the lookahead item too.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Perfect closure.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score += 14.0 * (1.0 - 0.5 * progress);
    } else if post_residual < 20 {
        score += 5.0;
    }

    // Exact two-step match: lookahead item closes this bin perfectly.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 25.0 + 8.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 8.0;
        } else if slack < 20 {
            score -= 3.0;
        }
    } else if nxt > 0.0 && post > 0.0 && post < nxt {
        // Dead-space risk, graded by wasted fraction.
        let waste_frac = (nxt - post) / nxt;
        score += 0.5 * (nxt - post).min(cap) + 6.0 + 3.0 * waste_frac * waste_frac;
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Concave fullest-bin preference (super-linear squeeze into full bins).
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Last-chance bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 18.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 2.5;
    }

    // New-bin candidate: attractive only when open bins are nearly saturated.
    if is_new_bin {
        let pressure = mean / cap;
        if pressure < 0.22 {
            score -= 10.0 + 4.0 * progress;
        } else if pressure < 0.45 {
            score += 2.0 + 4.0 * progress;
        } else {
            score += 9.0 + 6.0 * progress;
        }
        if progress < 0.2 {
            score -= 3.0;
        }
        // Lookahead-aware arbitration: don't open a bin that can't host next item
        // when some open bin can chain.
        if nxt > 0.0 {
            let new_post = cap - item_size as f64;
            let open_can_chain = fitting_bins_count > 0 && mean >= item_size as f64 && (mean - item_size as f64) >= nxt;
            let new_can_chain = new_post >= nxt;
            if open_can_chain && !new_can_chain {
                score += 5.0 + 3.0 * (1.0 - progress);
            } else if !open_can_chain && new_can_chain {
                score -= 2.0 * (1.0 - progress);
            }
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.2;

    // Chain closure: residual exactly matches next item size.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < next_item_size / 2 {
        score += 2.5 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let frac = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if frac % 2 == 0 && post_residual >= 10 && post_residual < 30 {
        score -= 2.5;
    }

    // Snug fit, graded.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        if snug < 5.0 {
            score -= 2.5;
        } else if snug < 15.0 {
            score -= 1.0 * (1.0 - snug / 15.0);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        } else if second_left > 25 {
            // Anti-fragmentation sweep on large usable leftovers.
            score += 0.06 * (second_left as f64 - 25.0);
        }
        // Target-residual attraction: leftover near fleet mean.
        let dist = (second_left as f64 - mean).abs();
        if dist < 8.0 {
            score -= 1.4 * (1.0 - dist / 8.0);
        }
    }

    // Dead-space-aware mid-band penalty (quadratic bump near awkward leftovers).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let bump = 4.0 * x * (1.0 - x);
        score += 1.0 * bump * (0.5 + 0.5 * progress);
    }

    // Residual-variance damping: pull post-residuals toward fleet mean.
    if !is_new_bin && mean > 0.0 {
        let dev = (post - mean) / cap;
        score += 1.0 * dev * dev * (1.2 - 0.6 * progress);
    }

    // Waste-fraction floor: penalize tiny stranded fractions mid-stream.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size && cap > 0.0 {
        let stranded_frac = post / cap;
        if stranded_frac < 0.12 && progress > 0.2 && progress < 0.9 {
            score += 2.0 * (1.0 - stranded_frac / 0.12);
        }
    }

    // Small post-residual bonus grows with open bins.
    if !is_new_bin && post_residual >= 1 && post_residual <= 10 {
        score -= 0.5 + 0.04 * open_bins_count.min(40) as f64;
    }

    // Endgame tightening: discourage fresh bins at the very end.
    if progress > 0.85 && is_new_bin {
        score += 6.0 * (progress - 0.85) / 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
