        }
    }

    // Mutation S: residual-variance damping.
    if !is_new_bin && mean > 0.0 {
        let dev = (post - mean) / cap;
        score += 1.0 * dev * dev * (1.2 - 0.6 * progress);
    }

    // Mutation T (new, gen 16): refillability-weighted leftover valuation.
    // Instead of only penalizing unusable leftovers, reward bins whose
    // post-residual after the lookahead item is a *common* size class
    // (divisible by small item sizes 3/4/5/10), since such residuals are
    // most likely to be exactly filled later. This directly attacks the
    // residual dead-space ratio weakness.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
