            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Mutation U (new, gen 16): gap-to-next-item monotone penalty.
    // When the post-residual falls just short of hosting the next item, the
    // waste is proportional to how close it came — a residual of nxt-1 is
    // nearly as bad as nxt itself in lost opportunity, but far worse in
    // expectation. Penalize the shortfall with a convex curve.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 15.0 {
            score += (2.5 - shortfall * 0.15) * (1.0 + 0.5 * progress);
        }
    }

    // Mutation V (new, gen 16): new-bin residual shaping.
    // When a new bin must be opened, prefer placements that leave a
    // refillable post-residual: penalize new-bin placements whose leftover
    // after the current item cannot host the lookahead item by a large margin.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if new_post < nxt {
            score += 0.8 * (nxt - new_post).min(cap) * (1.0 - progress);
        }
    }

    score
}

