    // on the lookahead item: peaks near nxt/cap, clamped to [0.30, 0.50].
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = (nxt / cap).clamp(0.30, 0.50);
        let skew = if x < peak { 0.8 } else { 1.25 };
        let bump = (x - peak) * (x - peak);
        score += 14.0 * skew * bump * (0.5 + 0.5 * progress);
    }

    // Mutation Q: utilization-maximizing tiebreak (concave fullest-bin pull).
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Mutation R: lookahead-aware new-bin arbitration.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let open_can_chain = fitting_bins_count > 0
            && mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        let new_can_chain = new_post >= nxt;
        if open_can_chain && !new_can_chain {
            score += 5.0 + 3.0 * (1.0 - progress);
        } else if !open_can_chain && new_can_chain {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Mutation S: residual-variance damping.
    if !is_new_bin && mean > 0.0 {
        let dev = (post - mean) / cap;
        score += 1.0 * dev * dev * (1.2 - 0.6 * progress);
    }

    // Mutation T (refined, gen 17): refillability-weighted leftover valuation,
    // now also rewarding residuals that can host a second copy of the lookahead
    // item (double-chain potential), a strong compaction signal.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        if nxt > 0.0 && (after as f64) >= nxt {
            refill += 1.6 * (1.0 - 0.5 * progress);
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Mutation U (refined, gen 17): gap-to-next-item monotone penalty with
    // scarcity coupling — the shortfall hurts more when few bins can host nxt.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 15.0 {
            let scarcity = 1.0 + 0.5 / (fitting_bins_count.max(1) as f64);
            score += (2.5 - shortfall * 0.15) * (1.0 + 0.5 * progress) * scarcity;
        }
    }

    // Mutation V: new-bin residual shaping.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if new_post < nxt {
            score += 0.8 * (nxt - new_post).min(cap) * (1.0 - progress);
        }
    }

    // Mutation W (new, gen 17): dual-candidate lookahead arbitration.
    // Compare this bin's post-residual against what a fresh bin would leave
    // after seating the same item; reward bins that strictly dominate the
    // new-bin outcome in chain potential, penalize near-ties wasted on
    // half-empty bins when the new bin would do just as well.
    if !is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let here_chains = post >= nxt;
        let new_chains = new_post >= nxt;
        if here_chains && !new_chains {
            score -= 3.0 * (1.0 - 0.3 * progress);
        } else if !here_chains && new_chains && post > 0.6 * new_post {
            score += 2.5 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
