            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Mutation U: gap-to-next-item monotone convex penalty on near-miss shortfall.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 15.0 {
            score += (2.5 - shortfall * 0.15) * (1.0 + 0.5 * progress);
        }
    }

    // Mutation V: new-bin residual shaping — prefer refillable new-bin leftover.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if new_post < nxt {
            score += 0.8 * (nxt - new_post).min(cap) * (1.0 - progress);
        }
    }

    // Mutation W (gen 17): scarcity-scaled snugness — when few bins can host
    // the item, sharpen the preference for the tightest fit by amplifying the
    // post-residual penalty in proportion to 1/fitting_bins_count. This pushes
    // near-perfect fills ahead of loose fits precisely when choices are rare,
    // attacking residual dead space without disturbing abundant-choice steps.
    if !is_new_bin && fitting_bins_count >= 1 && fitting_bins_count <= 4 {
        let scarcity_w = 1.0 / fitting_bins_count as f64;
        score += 0.9 * scarcity_w * (post / cap) * (0.6 + 0.4 * progress);
    }

    // Mutation X (gen 17): chain-pair bonus for divisible residual pairs —
    // when the leftover after the lookahead item is an exact multiple of a
    // small item class AND the current item shares that class, the bin forms
    // a perfect divisible chain; reward extra beyond Mutation T.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && item_size > 0 && (after % item_size.max(1)) == 0 {
            score -= 1.8 * (1.0 - 0.5 * progress);
        }
    }

    // Mutation Y (gen 17): endgame exact-closure surge — in the final stretch,
    // any placement that empties a bin outright is worth disproportionately
    // more, since remaining opportunities to consolidate vanish quickly.
    if post_residual == 0 && !is_new_bin && progress > 0.7 {
        score -= 10.0 * (progress - 0.7) / 0.3;
    }

    // Mutation Z (gen 17): soft new-bin dampening when open bins retain large
    // average slack — discourage opening fresh bins while the fleet still has
    // room, tightening compaction mid-stream.
    if is_new_bin && mean > item_size as f64 * 1.2 {
        score += 2.5 * ((mean - item_size as f64) / cap).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
