    // Reward bins where the leftover after the current item can host the
    // lookahead item AND the residual after that is small — a full 2-step
    // closure. Scaled by progress since late-stream exact chains are precious.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 6 {
