    if !is_new_bin && bin_residual >= item_size && fitting_bins_count <= 3 {
        let snug = (bin_residual - item_size) as f64;
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        if snug < 8.0 {
            score -= 1.5 * scarcity * (1.0 - snug / 8.0);
        }
    }

    // Mutation Z (gen 17): new-bin dead-space avoidance refinement.
    // When opening a new bin, penalize if an existing bin's post-residual
    // would be nearly as good as the new bin's (i.e. opening wastes the
    // existing slack). Compare new-bin post against the fleet mean post.
    if is_new_bin && nxt > 0.0 && fitting_bins_count > 0 && mean > 0.0 {
        let new_post = cap - item_size as f64;
        let existing_gain = (mean - item_size as f64).max(0.0);
        if new_post - existing_gain < nxt * 0.3 {
            score += 3.5 * (1.0 - progress);
        }
    }

    // Mutation AA (gen 17): progressive dead-space floor.
    // Late in the stream, any leftover below the lookahead item is nearly
    // permanent waste — apply a convex escalating penalty with progress.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size && progress > 0.6 {
        let stranded = post_residual as f64;
        let late = (progress - 0.6) / 0.4;
        score += 3.0 * late * (stranded / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
