    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Base: two-step waste — leftover after ideally seating the lookahead item too.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Aggressive exact two-step match: lookahead item would close this bin perfectly.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 12.0 + 6.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 5.0;
        } else if slack < 20 {
            score -= 2.0;
        }
    }

    // Perfect closure: item exactly fills the bin now.
    if post_residual == 0 {
        score -= 24.0;
    } else if post_residual < 10 {
        score += 9.0 + 2.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Dead-space risk: quadratic in the unusable gap, scaled by stream progress.
    if nxt > 0.0 && post > 0.0 && post < nxt {
        let gap = (nxt - post).min(cap);
        let waste_frac = gap / nxt;
        score += 0.5 * gap + 0.02 * gap * gap + 4.0 + 3.0 * waste_frac * waste_frac * (1.0 - 0.5 * progress);
    }

    // Mean-relative coupling: penalize leftovers above the average slack.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Relative-waste refinement: penalize the fraction of the bin left empty, graded.
    let void_frac = post / resid;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.5 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin: strongly prefer the only open bin that fits.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 8.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 1.5;
    }

    // Opening cost for a brand-new bin, gated by saturation pressure.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 6.0 + 3.0 * progress;
        } else if pressure < 0.45 {
            score += 1.0 + 3.0 * progress;
        } else {
            score += 8.0 + 5.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
    }

    // Consolidation pressure: many open bins favor filling existing ones.
    score += open_bins_count as f64 * 0.05;

    // Reward bins whose residual exactly matches the next item size (chain closure).
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Penalize residual too small for both current and next item — stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 2.5 * (1.0 - progress);
    }

    // Tight absolute fit regardless of lookahead.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing: small leftovers pair with even-class items.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.0;
    }

    // Endgame tightening — late in the stream, avoid opening bins unless nearly closed.
    if progress > 0.85 && is_new_bin {
        score += 6.0 * (progress - 0.85) / 0.15;
    }

    // Snug fit, graded — near-perfect placements beat merely-tight ones.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        if snug < 5.0 {
            score -= 2.5;
        }
        if snug < 15.0 {
            score -= 1.0 * (1.0 - snug / 15.0);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
    }

    // Dead-space ratio penalty beyond mean slack, graded harder for large voids.
    if post > mean && cap > 0.0 {
        let excess_ratio = (post - mean) / cap;
        if excess_ratio > 0.15 {
            score += 2.0 * excess_ratio + 4.0 * (excess_ratio - 0.15);
        }
    }

    // Reusable-void check: reward usable leftovers after the lookahead item.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    // Fragmentation guard: penalize deviation from fleet-average slack.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin via residual tiebreak.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // Depth-2 lookahead: small residual matching a future item class.
    if nxt > 0.0 && post_residual >= next_item_size {
        let two_left = post_residual - next_item_size;
        if two_left > 0 && two_left <= 10 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Exact-fit chain: post residual equals next item size with a small item.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size && next_item_size <= item_size {
        score -= 3.0 * (1.0 - progress);
    }

    // Asymmetric quadratic dead-space bump: penalizes awkward mid-size leftovers
    // after the lookahead item, peaking at the least-refillable residual fraction.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.42;
        let skew = if x < peak { 0.8 } else { 1.25 };
        let bump = (x - peak) * (x - peak);
        score += 14.0 * skew * bump * (0.5 + 0.5 * progress);
    }

    // Utilization-maximizing tiebreak (concave fullest-bin pull).
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Lookahead-aware new-bin arbitration: compare chaining ability of open bins
    // versus a fresh bin; penalize/reward accordingly.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let open_can_chain = fitting_bins_count > 0
            && mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        let new_can_chain = new_post >= nxt;
        if open_can_chain && !new_can_chain {
            score += 5.0 + 3.0 * (1.0 - progress);
        } else if !open_can_chain && new_can_chain {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Residual-variance damping.
    if !is_new_bin && mean > 0.0 {
        let dev = (post - mean) / cap;
        score += 1.0 * dev * dev * (1.2 - 0.6 * progress);
    }

    // Refillability-weighted leftover valuation: reward post-residuals that are
    // common size classes (divisible by small item sizes), since they are most
    // likely to be exactly filled later. Directly attacks residual dead space.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Gap-to-next-item monotone penalty: convex penalty on near-miss residuals.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 15.0 {
            score += (2.5 - shortfall * 0.15) * (1.0 + 0.5 * progress);
        }
    }

    // New-bin residual shaping: penalize fresh-bin placements whose leftover
    // after the current item cannot host the lookahead item by a large margin.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if new_post < nxt {
            score += 0.8 * (nxt - new_post).min(cap) * (1.0 - progress);
        }
    }

    // New mutation (gen 17): waste-fraction floor — small stranded residuals
    // that cannot host the lookahead item are pure loss; ramp the penalty in
    // mid-stream where recovery is still possible but bins are accumulating.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size && cap > 0.0 {
        let stranded_frac = post / cap;
        if stranded_frac < 0.12 && progress > 0.2 && progress < 0.9 {
            score += 2.0 * (1.0 - stranded_frac / 0.12);
        }
    }

    // New mutation (gen 17): target-residual attraction — reward bins whose
    // post-lookahead leftover lands near the fleet-mean slack, keeping the
    // open-bin residual distribution compact and refillable.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let target = post - nxt;
        let dist = (target - mean).abs();
        if dist < 8.0 {
            score -= 1.4 * (1.0 - dist / 8.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Base: two-step waste — leftover after ideally seating the lookahead item too.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Aggressive exact two-step match.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 12.0 + 6.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 5.0;
        } else if slack < 20 {
            score -= 2.0;
        }
    }

    // Perfect closure / small leftovers.
    if post_residual == 0 {
        score -= 24.0;
    } else if post_residual < 10 {
        score += 9.0 + 2.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Dead-space risk: quadratic waste penalty scaled by wasted fraction.
    if nxt > 0.0 && post > 0.0 && post < nxt {
        let waste_frac = (nxt - post) / nxt;
        score += 0.5 * (nxt - post).min(cap)
            + 4.0
            + 3.0 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.0 * waste_frac * (1.0 - progress);
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Void fraction, graded harder for large voids.
    let void_frac = post / resid;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.5 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 8.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 1.5;
    }

    // Opening cost for a brand-new bin.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 6.0 + 3.0 * progress;
        } else if pressure < 0.45 {
            score += 1.0 + 3.0 * progress;
        } else {
            score += 8.0 + 5.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.05;

    // Chain closure: residual exactly matches next item size.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 2.5 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.0;
    }

    // Endgame tightening.
    if progress > 0.85 && is_new_bin {
        score += 6.0 * (progress - 0.85) / 0.15;
    }

    // Snug fit, graded.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        if snug < 5.0 {
            score -= 2.5;
        }
        if snug < 15.0 {
            score -= 1.0 * (1.0 - snug / 15.0);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
    }

    // Dead-space ratio penalty, graded.
    if post > mean && cap > 0.0 {
        let excess_ratio = (post - mean) / cap;
        if excess_ratio > 0.15 {
            score += 2.0 * excess_ratio + 4.0 * (excess_ratio - 0.15);
        }
    }

    // Reusable-void check.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin via residual tiebreak.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // New-bin gate: open a fresh bin only when fits elsewhere are poor.
    if is_new_bin && nxt > 0.0 {
        let fits_poorly = fitting_bins_count > 0 && (bin_capacity as f64 - mean) > item_size as f64 * 1.5;
        if fits_poorly {
            score -= 3.0;
        }
    }

    // Depth-2 lookahead: small residual matching a future item class.
    if nxt > 0.0 && post_residual >= next_item_size {
        let two_left = post_residual - next_item_size;
        if two_left > 0 && two_left <= 10 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Exact-fit chain: post residual equals next item size with a small item.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size && next_item_size <= item_size {
        score -= 3.0 * (1.0 - progress);
    }

    // Mutation F: lookahead-aware dead-space hedge (sharpened weight).
    if nxt > 0.0 && !is_new_bin && post_residual < next_item_size && progress > 0.1 {
        let unusable = (next_item_size - post_residual) as f64;
        score += 0.75 * unusable * (1.0 - progress);
    }

    // Mutation G: residual homogeneity.
    if !is_new_bin && mean > 0.0 {
        let hom = ((post - mean).abs() / cap) as f64;
        score -= 0.8 * (1.0 - hom.min(1.0));
    }

    // Mutation H: dead-space ratio refinement vs fleet-average leftover fraction.
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let post_frac = post / cap;
        let mean_frac = (mean / cap).min(1.0);
        if post_frac > mean_frac {
            score += 3.5 * (post_frac - mean_frac) * (1.0 - 0.4 * progress);
        } else {
            score -= 1.2 * (mean_frac - post_frac);
        }
    }

    // Mutation I: anti-fragmentation sweep on large usable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let usable_left = post_residual - next_item_size;
        if usable_left > 25 {
            score += 0.06 * (usable_left as f64 - 25.0);
        }
    }

    // Mutation J: adaptive fit-quality gate.
    if !is_new_bin && post_residual > 0 {
        let leftover = post_residual as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        if leftover < nxt * 0.35 && nxt > 0.0 {
            score += 1.8 * scarcity * (1.0 - leftover / (nxt * 0.35));
        }
        if fitting_bins_count >= 3 {
            score += 0.05 * leftover;
        }
    }

    // Mutation K: target-residual attraction (widened band).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let target = post - nxt;
        let dist = (target - mean).abs();
        if dist < 8.0 {
            score -= 1.4 * (1.0 - dist / 8.0);
        }
    }

    // Mutation L: waste-fraction floor.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size && cap > 0.0 {
        let stranded_frac = post / cap;
        if stranded_frac < 0.12 && progress > 0.2 && progress < 0.9 {
            score += 2.0 * (1.0 - stranded_frac / 0.12);
        }
    }

    // Mutation M: dead-space-aware bin choice — penalize awkward mid-size leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 25 && after <= 60 {
            let mid_awkward = 1.0 - ((after - 25) as f64 / 35.0);
            score += 1.6 * mid_awkward * (0.4 + 0.6 * progress);
        }
    }

    // Mutation N: residual bucket symmetry — small post-residual bonus grows with open bins.
    if !is_new_bin && post_residual >= 1 && post_residual <= 10 {
        score -= 0.5 + 0.04 * open_bins_count.min(40) as f64;
    }

    // Mutation O: new-bin threshold tied to best available slack.
    if is_new_bin && fitting_bins_count > 0 {
        let avg_slack_after = mean - item_size as f64;
        if avg_slack_after > nxt * 0.5 {
            score += 4.0 + 2.0 * (1.0 - progress);
        }
    }

    // Mutation P (refined, gen 16): asymmetric quadratic dead-space bump.
    // The awkward-mid leftover penalty now peaks at x ≈ 0.42 (empirically the
    // least refillable residual fraction) and is skewed so leftovers below the
    // peak are penalized less than those above it (large unfillable voids are
    // the true waste driver). Weight ramps with progress since late-stream
    // dead space is unrecoverable.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.42;
        let skew = if x < peak { 0.8 } else { 1.25 };
        let bump = (x - peak) * (x - peak);
        score += 14.0 * skew * bump * (0.5 + 0.5 * progress);
    }

    // Mutation Q: utilization-maximizing tiebreak (concave fullest-bin pull).
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Mutation R: lookahead-aware new-bin arbitration.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let open_can_chain = fitting_bins_count > 0
            && mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        let new_can_chain = new_post >= nxt;
        if open_can_chain && !new_can_chain {
            score += 5.0 + 3.0 * (1.0 - progress);
        } else if !open_can_chain && new_can_chain {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Mutation S: residual-variance damping.
    if !is_new_bin && mean > 0.0 {
        let dev = (post - mean) / cap;
        score += 1.0 * dev * dev * (1.2 - 0.6 * progress);
    }

    // Mutation T: refillability-weighted leftover valuation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Mutation U: gap-to-next-item monotone penalty.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 15.0 {
            score += (2.5 - shortfall * 0.15) * (1.0 + 0.5 * progress);
        }
    }

    // Mutation V: new-bin residual shaping.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if new_post < nxt {
            score += 0.8 * (nxt - new_post).min(cap) * (1.0 - progress);
        }
    }

    // Mutation W (gen 17): dead-space-ratio attack — the diagnosed weakness is
    // residual dead space. Strengthen the refillability logic by coupling the
    // divisibility bonus to how well the leftover matches the fleet-average
    // residual scale, so refillable leftovers near the typical residual size
    // are rewarded more strongly (they are the ones actually likely to be
    // refilled by incoming items).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 && mean > 0.0 {
            let scale_match = 1.0 - ((after - mean).abs() / cap).min(1.0);
            if after % 10 == 0 {
                score -= 1.6 * scale_match * (1.0 - 0.3 * progress);
            } else if after % 5 == 0 {
                score -= 0.9 * scale_match;
            }
        }
    }

    // Mutation X (gen 17): bin-conservation on near-full fits. When the item
    // nearly closes the bin (post_residual tiny), reward proportionally to
    // open_bins_count so closure is preferred when many bins are open —
    // directly reducing total bins by draining the fleet.
    if !is_new_bin && post_residual > 0 && post_residual <= 4 {
        score -= 0.10 * open_bins_count.min(60) as f64;
    }

    // Mutation Y (gen 17): sharper new-bin veto. When at least one open bin
    // can fit the item with a snug leftover (<= item/2), opening a new bin is
    // almost always worse — apply a strong penalty so the oracle prefers the
    // existing bin and total bin count stays minimal.
    if is_new_bin && fitting_bins_count > 0 {
        let snug_exists = (bin_capacity as f64 - mean) <= item_size as f64 * 1.5;
        if snug_exists {
            score += 6.0 + 4.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
