    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let after = (post_residual - next_item_size) as f64;
        if after <= nxt * 0.5 {
            score -= 1.2 * scarcity * (1.0 - after / (nxt * 0.5));
        }
    }

    // Mutation X (new, gen 18): late-stream exactness — as the stream ends,
    // leftover opportunity vanishes, so tighten the dead-space bump weight
    // and add a mild exact-closure bonus scaling with progress.
    if !is_new_bin && post_residual == 0 && progress > 0.5 {
        score -= 3.0 * progress;
    }

    score
}

