            score += 0.06 * (usable_left as f64 - 25.0);
        }
    }

    // Mutation J (grafted): refillability-weighted leftover reward.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Mutation K (grafted): convex shortfall penalty for near-miss lookahead.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 15.0 {
            score += (2.5 - shortfall * 0.15) * (1.0 + 0.5 * progress);
        }
    }

    // Mutation L: asymmetric quadratic dead-space bump on the post-lookahead
    // leftover fraction (least-refillable zone near 0.38 of capacity).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
