    }

    // Mutation P: fleet-aware dead-space cap on excess post-lookahead leftover.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Mutation Q (new, gen 20): exact two-step closure bonus for the tightest
    // possible chain — post-lookahead leftover of exactly 1..=3 units, which
    // is nearly unusable, is actually optimal when it closes the bin cleanly.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 1 && after <= 3 {
            score -= 4.0 * (1.0 - 0.3 * progress);
        }
    }

    // Mutation R (new, gen 20): sharpen the residual tiebreak toward fullest
    // bins late in the stream, where closure quality dominates.
    if !is_new_bin && progress > 0.6 {
        score += 0.12 * (bin_residual as f64 / cap) * ((progress - 0.6) / 0.4);
    }

    score
}

