        // 30..=60 range are the least refillable for typical item sizes.
        if after >= 30 && after <= 60 && progress > 0.3 {
            score += 1.8 * (progress - 0.3) / 0.7;
        }
    }

    // Mutation R (gen 21): progress-adaptive snugness — tighten the snug-fit
    // reward band as the stream advances, since early loose fits can be
    // repaired later but late loose fits become permanent waste.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        let band = 20.0 - 10.0 * progress;
        if snug < band {
            score -= 1.6 * (1.0 - snug / band) * (0.5 + progress);
        }
    }

    // Mutation S (gen 21): new-bin saturation hedge — when many bins are open
    // and fleet mean residual is low, opening fresh bins fragments capacity;
    // scale the open penalty with open_bins_count relative to stream length.
    if is_new_bin && open_bins_count > 8 {
        let frag = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
        score += 0.9 * frag * (0.4 + 0.6 * progress);
    }

    score
}

