            score -= 1.6 * (1.0 - snug / band) * (0.5 + progress);
        }
    }

    // Mutation S: new-bin saturation hedge.
    if is_new_bin && open_bins_count > 8 {
        let frag = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
        score += 0.9 * frag * (0.4 + 0.6 * progress);
    }

    // Mutation T: sharpened dead-space bump (peak 0.32 of capacity).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak2 = 0.32;
        let skew2 = if x < peak2 { 0.6 } else { 1.6 };
        let bump2 = (x - peak2) * (x - peak2);
        score += 5.0 * skew2 * bump2 * (1.0 + progress);
    }

    // Mutation U: exact-closure ladder.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 15 {
            score -= 2.0 * (1.0 - after as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
    }

    // Mutation V: new-bin exact-chain gate.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if (new_post - nxt).abs() < 1.0 {
            score -= 4.0 * (1.0 - progress);
        } else if new_post < nxt && progress > 0.5 {
            score += 2.5 * (progress - 0.5) / 0.5;
        }
    }

    // Mutation W (gen 22): dual-peak dead-space sculpting — instead of a single
    // bump peak, reward leaving residuals that are exactly consumable by the
    // lookahead (post == nxt) and penalize the mid-gap zone (post just below
    // nxt) proportionally to how close post is to nxt from below, which
    // targets the diagnosed suboptimal-residual weakness.
    if !is_new_bin && nxt > 0.0 && post_residual > 0 && post_residual < next_item_size {
        let gap = nxt - post;
        if gap <= 25.0 {
            score += 1.8 * (1.0 - gap / 25.0) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation X (gen 22): lookahead-consistent dead-space floor — when the
    // post-lookahead leftover is tiny (<= 5), treat it as near-closure and
    // reward more strongly late in the stream, where every residual matters.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 5 {
            score -= 3.0 + 2.0 * progress;
        }
    }

    // Mutation Y (gen 22): residual-band specialization — post-lookahead
    // leftovers that are multiples of common item sizes (10/25/50) are far
    // more likely to be filled by future items; reward them with a mild,
    // progress-scaled discount.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let bonus = if after % 50 == 0 {
            2.5
        } else if after % 25 == 0 {
            1.8
        } else if after % 10 == 0 {
            1.2
        } else {
            0.0
        };
        score -= bonus * (0.5 + 0.5 * (1.0 - progress));
    }

    // Mutation Z (gen 22): adaptive new-bin threshold — the new-bin candidate
    // should only win when the best open fit would strand a large unusable
    // gap. Estimate the best open-bin post-fit leftover via the fleet mean
    // and penalize opening when that estimate is small.
    if is_new_bin && fitting_bins_count > 0 && mean > 0.0 {
        let est_open_left = (mean - item_size as f64).max(0.0);
        if est_open_left < nxt * 0.5 {
            score += 2.0 + 2.5 * (1.0 - est_open_left / (nxt * 0.5).max(1.0));
        } else if est_open_left >= nxt {
            score -= 1.5 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
