    }

    // Mutation X (gen 22): dead-space bimodality guard — leftovers just below
    // the mean residual are the classic "half-empty trap"; push selection
    // toward either near-closure or well-above-mean refillable space.
    if !is_new_bin && mean > 0.0 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let band_lo = 0.55 * mean;
        let band_hi = 0.85 * mean;
        if after > band_lo && after < band_hi {
            let depth = 1.0 - ((after - band_lo) / (band_hi - band_lo)).abs();
            score += 1.6 * depth * (0.6 + 0.4 * progress);
        }
    }

    // Mutation Y (gen 22): lookahead-conditional new-bin veto refinement —
    // block opening a new bin when an existing bin closes EXACTLY on the
    // next item, even under high pressure.
    if is_new_bin && nxt > 0.0 && fitting_bins_count > 0 {
        if mean - item_size as f64 >= nxt + 0.5 * (mean / cap) * nxt {
            score += 2.0 + 2.0 * (1.0 - progress);
        }
    }

    // Mutation Z (gen 22): residual-variance-aware snugness boost —
    // when observed residuals are tight (low variance proxy via mean),
    // small snug fits are rarer and more valuable.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        if snug == 0.0 {
            score -= 3.0 + 2.0 * (1.0 - progress);
        } else if snug <= 3.0 {
            score -= 1.2 * (1.0 - snug / 3.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Base: two-step waste — leftover after ideally seating the lookahead item too.
    let mut score = if nxt > 0.0 && post_residual >= next_item_size { post - nxt } else { post };

    // Perfect closure.
    if post_residual == 0 {
        score -= 28.0;
    } else if post_residual < 10 {
        score += 8.0 + 2.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Exact two-step chain match.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 10.0 + 5.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 5.0;
        } else if slack < 20 {
            score -= 2.0;
        }
        // Small closable leftover reward.
        if slack > 0 && slack <= 15 {
            score -= 2.0 * (1.0 - slack as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
        // Anti-fragmentation on very large leftovers.
        if slack > 25 {
            score += 0.05 * (slack as f64 - 25.0);
        }
    }

    // Dead-space risk: leftover cannot host the next item.
    if nxt > 0.0 && post > 0.0 && post < nxt {
        let waste_frac = (nxt - post) / nxt;
        score += 0.5 * (nxt - post).min(cap)
            + 4.0
            + 3.0 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.0 * waste_frac * (1.0 - progress);
        if post_residual > 0 && post_residual < 8 {
            score -= 4.0; // near-closure with tiny leftover is still good
        }
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Void fraction, graded harder for large voids.
    let void_frac = post / bin_residual.max(1) as f64;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.5 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 10.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 1.5;
    }

    // New-bin arbitration.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 6.0 + 3.0 * progress;
        } else if pressure < 0.45 {
            score += 1.0 + 3.0 * progress;
        } else {
            score += 8.0 + 5.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
        // Prefer fresh bin only when it forms a perfect chain with next item.
        if nxt > 0.0 {
            let new_post = cap - item_size as f64;
            if (new_post - nxt).abs() < 1.0 {
                score -= 4.0 * (1.0 - progress);
            } else if new_post < nxt && progress > 0.5 {
                score += 2.5 * (progress - 0.5) / 0.5;
            }
        }
        if progress > 0.85 {
            score += 6.0 * (progress - 0.85) / 0.15;
        }
        // Fragmentation hedge with many open bins.
        if open_bins_count > 8 {
            let frag = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
            score += 0.9 * frag * (0.4 + 0.6 * progress);
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.05;

    // Chain closure: residual exactly matches next item size.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.0;
    }

    // Snug fit, graded and progress-adaptive.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        let band = 20.0 - 10.0 * progress;
        if snug < band {
            score -= 1.6 * (1.0 - snug / band) * (0.5 + progress);
        }
    }

    // Dead-space ratio penalty vs fleet-average leftover fraction.
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let post_frac = post / cap;
        let mean_frac = (mean / cap).min(1.0);
        if post_frac > mean_frac {
            score += 3.5 * (post_frac - mean_frac) * (1.0 - 0.4 * progress);
        } else {
            score -= 1.2 * (mean_frac - post_frac);
        }
    }

    // Mid-band dead-space bump on the post-lookahead leftover fraction.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.32;
        let skew = if x < peak { 0.6 } else { 1.6 };
        let bump = (x - peak) * (x - peak);
        score += 5.0 * skew * bump * (1.0 + progress);
    }

    // Two-deep chain reward.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 == nxt || after as f64 == item_size as f64 {
            score -= 3.5 + 2.5 * (1.0 - progress);
        }
    }

    // Utilization tiebreak: prefer fullest fitting bins.
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    score
}

