        score += 5.0 * skew2 * bump2 * (1.0 + progress);
    }

    // Mutation R (gen 22): exact-closure ladder — reward post-lookahead
    // leftovers small enough to be closed by a typical small item (<= 15).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 15 {
