            score += 2.0 + 4.0 * progress;
        } else {
            score += 9.0 + 6.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
        if progress < 0.2 {
            score -= 3.0;
        }
        if progress > 0.85 {
            score += 6.0 * (progress - 0.85) / 0.15;
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.15;

    // Chain closure.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 2.5 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.5;
    }

    // Snug fit, progress-adaptive band.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        let band = 20.0 - 10.0 * progress;
        if snug < band {
            score -= 2.0 * (1.0 - snug / band) * (0.5 + progress);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
        // Two-deep chain reward.
        if second_left as f64 == nxt || second_left as f64 == item_size as f64 {
            score -= 3.0 + 2.0 * (1.0 - progress);
        } else if second_left > 0 && second_left <= 10 {
            score -= 2.0 * (1.0 - progress);
        }
        // Anti-fragmentation sweep on large usable leftovers.
        if second_left > 25 {
            score += 0.06 * (second_left as f64 - 25.0);
        }
        // Two-step closure ladder.
        let after = second_left as f64;
        if after > 0.0 {
            let closeness = 1.0 - (after / cap).min(1.0);
            score -= 3.0 * closeness * closeness * (0.6 + 0.8 * progress);
        }
        // Refillability-weighted leftover valuation.
        let mut refill = 0.0f64;
        if after > 0.0 {
            if after % 10.0 == 0.0 { refill = 2.2; }
            else if after % 5.0 == 0.0 { refill = 1.4; }
            else if after % 4.0 == 0.0 { refill = 1.0; }
            else if after % 3.0 == 0.0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Convex shortfall penalty for near-miss lookahead.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 15.0 {
            score += (2.5 - shortfall * 0.15) * (1.0 + 0.5 * progress);
        }
        if post_residual > 0 && post_residual < 8 && nxt > post {
            score -= 5.0;
        }
    }

    // Asymmetric quadratic dead-space bump on post-lookahead leftover
    // fraction, sharpened toward peak 0.32 of capacity.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.32;
        let skew = if x < peak { 0.6 } else { 1.6 };
        let bump = (x - peak) * (x - peak);
        score += 10.0 * skew * bump * (1.0 + progress);
    }

    // Exact-closure ladder: leftover closable by a typical small item.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 15 {
            score -= 2.0 * (1.0 - after as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
    }

    // Lookahead-aware new-bin arbitration.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let open_can_chain = fitting_bins_count > 0
            && mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        let new_can_chain = new_post >= nxt;
        if open_can_chain && !new_can_chain {
            score += 5.0 + 3.0 * (1.0 - progress);
        } else if !open_can_chain && new_can_chain {
            score -= 2.0 * (1.0 - progress);
        }
        if (new_post - nxt).abs() < 1.0 {
            score -= 4.0 * (1.0 - progress);
        } else if new_post < nxt && progress > 0.5 {
            score += 2.5 * (progress - 0.5) / 0.5;
        }
    }

    // Utilization-maximizing tiebreak.
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
        score += 0.08 * (bin_residual as f64 / cap);
    }

    // Fleet-aware dead-space cap.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // New-bin saturation hedge.
    if is_new_bin && open_bins_count > 8 {
        let frag = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
        score += 0.9 * frag * (0.4 + 0.6 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Base: two-step waste — leftover after ideally seating the lookahead item too.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Aggressive exact two-step match.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 30.0 + 10.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 12.0;
        } else if slack < 20 {
            score -= 4.0;
        }
    }

    // Perfect closure / small leftovers.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score += 14.0 + 2.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 5.0;
    } else {
        let post_class = (post_residual * 10 + bin_capacity / 2) / bin_capacity;
        if post_class >= 7 {
            score -= 4.0;
        }
    }

    // Dead-space risk: quadratic waste penalty scaled by wasted fraction.
    if nxt > 0.0 && post > 0.0 && post < nxt {
        let waste_frac = (nxt - post) / nxt;
        score += 0.5 * (nxt - post).min(cap)
            + 5.0
            + 3.0 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.0 * waste_frac * (1.0 - progress);
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Void fraction, graded harder for large voids.
    let void_frac = post / resid;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.5 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 20.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 2.0;
    }

    // New-bin opening cost with saturation pressure.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 8.0 + 3.0 * progress;
        } else if pressure < 0.45 {
            score += 2.0 + 4.0 * progress;
        } else {
            score += 10.0 + 5.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
        if progress > 0.85 {
            score += 6.0 * (progress - 0.85) / 0.15;
        }
        // Lookahead-aware new-bin arbitration.
        if nxt > 0.0 {
            let new_post = cap - item_size as f64;
            let open_can_chain = fitting_bins_count > 0
                && mean >= item_size as f64
                && (mean - item_size as f64) >= nxt;
            let new_can_chain = new_post >= nxt;
            if open_can_chain && !new_can_chain {
                score += 5.0 + 3.0 * (1.0 - progress);
            } else if !open_can_chain && new_can_chain {
                score -= 2.0 * (1.0 - progress);
            }
            if (new_post - nxt).abs() < 1.0 {
                score -= 4.0 * (1.0 - progress);
            } else if new_post < nxt && progress > 0.5 {
                score += 2.5 * (progress - 0.5) / 0.5;
            }
        }
        // Saturation hedge against fragmentation.
        if open_bins_count > 8 {
            let frag = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
            score += 0.9 * frag * (0.4 + 0.6 * progress);
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.15;

    // Chain closure: residual exactly matches next item size.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 2.5 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.0;
    }

    // Progress-adaptive snugness.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        let band = 20.0 - 10.0 * progress;
        if snug < band {
            score -= 1.6 * (1.0 - snug / band) * (0.5 + progress);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
        // Two-deep chain reward.
        if second_left as f64 == nxt || second_left as f64 == item_size as f64 {
            score -= 3.5 + 2.5 * (1.0 - progress);
        } else if (second_left as f64) >= nxt.min(item_size as f64) && second_left < 2 * next_item_size {
            score -= 1.0 * (1.0 - 0.5 * progress);
        }
        // Anti-fragmentation sweep on large usable leftovers.
        if second_left > 25 {
            score += 0.06 * (second_left as f64 - 25.0);
        }
        // Two-deep lookahead: small residual matching a future item class.
        if second_left > 0 && second_left <= 10 {
            score -= 2.0 * (1.0 - progress);
        }
        // Refillability-weighted leftover valuation.
        let mut refill = 0.0f64;
        if second_left > 0 {
            if second_left % 10 == 0 { refill = 2.2; }
            else if second_left % 5 == 0 { refill = 1.4; }
            else if second_left % 4 == 0 { refill = 1.0; }
            else if second_left % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
        // Two-step closure ladder.
        if second_left > 0 {
            let closeness = 1.0 - (second_left as f64 / cap).min(1.0);
            score -= 3.0 * closeness * closeness * (0.6 + 0.8 * progress);
        }
        // Exact-closure ladder: leftover closable by a typical small item.
        if second_left > 0 && second_left <= 15 {
            score -= 2.0 * (1.0 - second_left as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
        // Mid-band dead-space penalty.
        if second_left >= 30 && second_left <= 60 && progress > 0.3 {
            score += 1.8 * (progress - 0.3) / 0.7;
        }
        // Reusable-void check.
        if second_left >= 10 {
            score -= 0.5 * (second_left as f64 / cap);
        }
    }

    // Dead-space ratio penalty vs fleet average.
    if post > mean && cap > 0.0 {
        let excess_ratio = (post - mean) / cap;
        if excess_ratio > 0.15 {
            score += 2.0 * excess_ratio + 4.0 * (excess_ratio - 0.15);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin via residual tiebreak.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // Convex shortfall penalty for near-miss lookahead.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 15.0 {
            score += (2.5 - shortfall * 0.15) * (1.0 + 0.5 * progress);
        } else {
            score += 0.75 * shortfall * (1.0 - progress);
        }
    }

    // Residual homogeneity reward.
    if !is_new_bin && mean > 0.0 {
        let hom = ((post - mean).abs() / cap).min(1.0);
        score -= 0.8 * (1.0 - hom);
    }

    // Asymmetric quadratic dead-space bump on post-lookahead leftover
    // fraction (sharpened peak 0.32 of capacity), targeting dead-space weakness.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.32;
        let skew = if x < peak { 0.6 } else { 1.6 };
        let bump = (x - peak) * (x - peak);
        score += 12.0 * skew * bump * (1.0 + progress);
    }

    // Fleet-aware dead-space cap.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Exact-fit chain with small current item.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size && next_item_size <= item_size {
        score -= 3.0 * (1.0 - progress);
    }

    score
}

