    // by how far the next item overshoots them.
    if !is_new_bin && nxt > 0.0 && post_residual >= 16 && post_residual <= 29 {
        let gap = ((nxt - post).abs()) / nxt.max(1.0);
        score += 1.8 * gap * (0.5 + 0.5 * progress);
    }

    score
}

