        let band = 20.0 - 10.0 * progress;
        if snug < band {
            score -= 1.8 * (1.0 - snug / band) * (0.5 + progress);
        }
    }

    // Mutation AA (gen 23): new-bin saturation hedge — discourage opening
    // fresh bins when the fleet is already fragmented relative to stream size.
