        let frag = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
        score += 1.0 * frag * (0.4 + 0.6 * progress);
    }

    // Mutation AB (gen 23): new-bin exact-chain gate — prefer opening a
    // fresh bin only when its post-placement residual exactly chains the
    // next item; otherwise penalize harder mid/late stream.
