        let homogeneity = 1.0 - ((mean - cap * 0.5).abs() / (cap * 0.5)).min(1.0);
        let dev = (post - mean).abs() / cap;
        score += 1.1 * homogeneity * dev * (1.0 - 0.5 * progress);
