    }

    // Mutation T: sharpened dead-space bump toward 0.32 of capacity.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak2 = 0.32;
        let skew2 = if x < peak2 { 0.6 } else { 1.6 };
        let bump2 = (x - peak2) * (x - peak2);
        score += 5.0 * skew2 * bump2 * (1.0 + progress);
    }

    // Mutation U: exact-closure ladder — reward closable post-lookahead leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 15 {
            score -= 2.0 * (1.0 - after as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
    }

    // Mutation V: new-bin exact-chain gate.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if (new_post - nxt).abs() < 1.0 {
            score -= 4.0 * (1.0 - progress);
        } else if new_post < nxt && progress > 0.5 {
            score += 2.5 * (progress - 0.5) / 0.5;
        }
    }

    // Mutation W (gen 24): adaptive dead-space valley — the dead-space bump
    // peak tracks the fleet mean residual fraction so the "worst leftover"
    // target follows the actual stream regime instead of a fixed constant.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && cap > 0.0 && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let mean_frac = (mean / cap).min(1.0);
        let peak_w = (0.30 + 0.25 * mean_frac).clamp(0.28, 0.42);
        let skew_w = if x < peak_w { 0.55 } else { 1.7 };
        let bump_w = (x - peak_w) * (x - peak_w);
        score += 4.5 * skew_w * bump_w * (0.8 + 0.7 * progress);
    }

    // Mutation X (gen 24): unusable-fragment surcharge — when the leftover
    // after the lookahead cannot hold the mean small item, penalize the
    // stranded sliver proportionally to how close it is to being useful.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && (after as f64) < mean.min(nxt) {
            let near_miss = 1.0 - after as f64 / mean.min(nxt).max(1.0);
            score += 1.8 * near_miss * near_miss * (0.5 + 0.5 * progress);
        }
    }

    // Mutation Y (gen 24): new-bin dead-space floor check — opening a fresh
    // bin leaves cap - item; if that residual is a known dead zone (far from
    // the fleet mean and unable to chain), discourage it more strongly.
    if is_new_bin && nxt > 0.0 && mean > 0.0 {
        let new_post = cap - item_size as f64;
        let dev = ((new_post - mean) / cap).abs();
        if new_post < nxt && dev > 0.2 {
            score += 2.0 * dev * (0.6 + 0.6 * progress);
        } else if (new_post - mean).abs() / cap < 0.06 {
            score -= 1.5 * (1.0 - progress);
        }
    }

    // Mutation Z (gen 24): crisp exact-chain bonus at high fill — when the
    // leftover after lookahead exactly equals a plausible small item class
    // (5/10/20/25), reward extra late in the stream where closure matters.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after == 5 || after == 10 || after == 20 || after == 25 {
            score -= 2.2 * (0.4 + 0.6 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
