    // Progress-adaptive snugness.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        let band = 20.0 - 10.0 * progress;
        if snug < band {
            score -= 1.8 * (1.0 - snug / band) * (0.5 + progress);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
        // Two-deep chain reward.
        if second_left as f64 == nxt || second_left as f64 == item_size as f64 {
            score -= 3.5 + 2.5 * (1.0 - progress);
        } else if (second_left as f64) >= nxt.min(item_size as f64) && second_left < 2 * next_item_size {
            score -= 1.0 * (1.0 - 0.5 * progress);
        }
        // Exact-closure ladder: leftover closable by a typical small item.
        if second_left > 0 && second_left <= 15 {
            score -= 2.0 * (1.0 - second_left as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
        // Anti-fragmentation sweep on large usable leftovers.
        if second_left > 25 {
            score += 0.06 * (second_left as f64 - 25.0);
        }
    }

    // Dead-space ratio penalty vs fleet-average leftover fraction.
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let post_frac = post / cap;
        let mean_frac = (mean / cap).min(1.0);
        if post_frac > mean_frac {
            score += 3.5 * (post_frac - mean_frac) * (1.0 - 0.4 * progress);
        } else {
            score -= 1.2 * (mean_frac - post_frac);
        }
    }

    // Reusable-void valuation.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // Sharpened dead-space hedge for near-miss lookahead.
    if nxt > 0.0 && !is_new_bin && post_residual < next_item_size && progress > 0.1 {
        let unusable = (next_item_size - post_residual) as f64;
        if unusable <= 15.0 {
            score += (2.5 - unusable * 0.15) * (1.0 + 0.5 * progress);
        } else {
            score += 0.75 * unusable * (1.0 - progress);
        }
    }

    // Residual homogeneity bonus.
    if !is_new_bin && mean > 0.0 {
        let hom = ((post - mean).abs() / cap) as f64;
        score -= 0.8 * (1.0 - hom.min(1.0));
    }

    // Asymmetric dead-space bump on post-lookahead leftover fraction.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.32;
        let skew = if x < peak { 0.6 } else { 1.5 };
        let bump = (x - peak) * (x - peak);
        score += 10.0 * skew * bump * (1.0 + progress);
    }

    // Fleet-aware dead-space cap.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Refillability-weighted leftover valuation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // NEW (gen 25): mid-band leftover trap — penalize post-lookahead leftovers
    // in the awkward 20..=45 range that rarely refill, scaled by progress,
    // targeting the diagnosed suboptimal-residual weakness.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 20 && after <= 45 {
            let mid = 1.0 - ((after as f64 - 32.5).abs() / 12.5);
            score += 2.2 * mid * (0.4 + 0.6 * progress);
        }
    }

    // NEW (gen 25): dual-chain lookahead — reward bins whose post-lookahead
    // leftover can still chain the current item size (triple fit), a strong
    // compaction signal missed by the two-deep chain reward alone.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 >= item_size as f64 {
            score -= 2.0 * (1.0 - 0.4 * progress);
        }
    }

    // NEW (gen 25): new-bin threshold tightening — when the best open-bin fit
    // would leave a large dead gap relative to next item, discourage keeping
    // the item out of a fresh bin unless the fresh chain is perfect.
    if is_new_bin && nxt > 0.0 && fitting_bins_count > 0 {
        let new_post = cap - item_size as f64;
        if new_post < nxt && (mean - item_size as f64) < nxt {
            score += 3.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: squared post-residual (dead space penalized quadratically)
    let mut score = post * post / cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, prefer tight packing into existing bins; later, tolerate slack.
    let prog_weight = 1.0 + 2.0 * progress * progress;
    score *= prog_weight;

    // Interaction term: post_residual * normalized item fraction, smooth cubic in progress
    let item_frac = item_size as f64 / cap;
    score += post * item_frac * (0.5 + 1.5 * progress * progress * progress);

    // Reward bins whose residual is well-used relative to the mean residual (smooth tanh-like via logistic)
    let mean_gap = (mean_residual - post) / cap;
    let logistic = 1.0 / (1.0 + (-3.0 * mean_gap).exp());
    score -= 4.0 * logistic;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it (smooth)
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 10.0 * last_chance * (1.0 + progress);

    // Lookahead: reward if next item can fit into post_residual (smooth decay with mismatch)
    if next_item_size > 0 {
        let next_frac = next_item_size as f64 / cap;
        let fits_next = (post - next_item_size as f64) / cap;
        let smooth_fit = 1.0 / (1.0 + (10.0 * fits_next).exp());
        score -= 6.0 * next_frac * smooth_fit;
        // Penalize leaving just-barely-not-fitting space for the next item
        let near_miss = (-fits_next * 20.0).exp() * (1.0 - smooth_fit);
        score += 5.0 * near_miss * next_frac;
    }

    // Mild penalty for spreading across many open bins (encourage consolidation early)
    let open_frac = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score += 2.0 * open_frac * post / cap;

    // New-bin candidate: make empty bins less attractive unless post_residual would be large
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
