    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Mutation W (gen 25, ContinueDirection on dead-space weakness):
    // sharpened residual-targeting bonus — reward bins whose post-lookahead
    // leftover lands within a narrow "refillable window" that tracks the
    // fleet mean residual, tightening the diagnosed suboptimal-residual zone.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let target = mean.max(6.0).min(cap * 0.5);
        let dist = (after - target).abs();
        if dist <= 12.0 {
            score -= 2.2 * (1.0 - dist / 12.0) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation X (gen 25): cubic dead-space escalation — penalize leftovers
    // stranded in the 20–45 range (least refillable band) with a
    // progress-scaled cubic ramp, pushing selection away from bins that
    // leave mid-sized unusable voids.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 20.0 && after < 45.0 {
            let t = (after - 20.0) / 25.0;
            score += 3.0 * t * t * (2.0 - t) * (0.5 + progress);
        }
    }

    // Mutation Y (gen 25): tight new-bin arbitration refinement — when a
    // fresh bin would leave a large residual after the current item while
    // some open bin closes tighter, penalize the fresh bin proportionally.
    if is_new_bin && nxt > 0.0 && fitting_bins_count > 0 {
        let new_post = cap - item_size as f64;
        let new_waste = (new_post - nxt).max(0.0);
        if new_waste > 25.0 {
            score += 0.08 * (new_waste - 25.0) * (1.0 - 0.3 * progress);
        }
    }

    score
}

