    }

    // Mutation Y (gen 26): lookahead-fit calibration — when the next item
    // would exactly fill the post-residual, escalate the reward late in the
    // stream where closure value is highest.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation Z (gen 26): waste-shape guard — penalize leftover shapes that
    // are neither small-closable nor large-reusable (the awkward middle band
    // 16..=29), which the diagnosed weakness suggests we accumulate.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible into clean
    // capacity fractions are more reusable than awkward remainders.
    let cap_frac = bin_capacity / 4; // 25
    let post = post_residual;
    if post == 0 {
        score -= 60.0; // perfect fit, zero waste
    } else {
        // Penalize dead space in harmonic "bad" classes (residual 1..cap_frac-1
        // is nearly unusable for items >= 10).
        if post < cap_frac {
            score += (cap_frac - post) as f64 * 0.8;
        }
        // Reward residuals that are exact harmonic fractions of capacity.
        if post % cap_frac == 0 {
            score -= 12.0;
        } else if post % (cap_frac / 2) == 0 {
            score -= 6.0;
        }
        // Integer-division threshold: classify post_residual into coarse buckets,
        // prefer buckets that can host typical future items.
        let bucket = post / 10;
        score -= bucket as f64 * 1.5;
    }

    // Lookahead coupling: strongly reward leaving room for the next item.
    if next_item_size > 0 {
        if post >= next_item_size {
            score -= 18.0 + (next_item_size as f64 * 0.2);
            // exact chain fit is ideal
            if post == next_item_size {
                score -= 25.0;
            }
        } else {
            // dead space relative to the known next item
            score += (next_item_size - post) as f64 * 0.9;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit here
    // is poor. Give the empty bin a mild handicap so existing usable bins win.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin; scaled by how crowded open bins are.
        let crowd = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        score += 20.0 + crowd * 30.0;
        if post_residual > 0 && post_residual < 10 {
            score -= 15.0; // placing a tiny item in a fresh bin is fine
        }
    }

    // Mild stream-progression pressure: late in the stream, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer filling bins that are already relatively empty (balance residuals).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

