        score += 7.0 * skew2 * bump2 * (1.0 + 1.5 * progress);
    }

    // Mutation AB (gen 27): exact-closure ladder — reward small closable
    // leftovers after the lookahead item, strongest early/mid-stream.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 15 {
            score -= 2.2 * (1.0 - after as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
    }

    // Mutation AC (gen 27): waste-shape guard — penalize the awkward middle
    // band of leftovers (16..=29) that are neither closable nor reusable.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
