    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation Z (gen 28): waste-shape guard — penalize the awkward middle
    // band of leftovers (16..=29) that is neither closable nor reusable.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AA (new, gen 28): residual-conservation tiebreak — when several
    // bins fit, prefer the one whose post-lookahead leftover is closest to a
    // small multiple of the mean residual, keeping the fleet homogeneous and
    // reducing stranded dead space. Scaled by remaining stream length.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let k = (after / mean).round().max(1.0);
        let dev = (after - k * mean).abs() / cap;
        score += 2.2 * dev * (1.0 - 0.5 * progress);
    }

    score
}

