    }

    // Snug fit, graded.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        if snug < 5.0 {
            score -= 2.5;
        }
        if snug < 15.0 {
            score -= 1.0 * (1.0 - snug / 15.0);
        }
    }

    // Lookahead chain.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
    }

    // Dead-space ratio penalty.
    if post > mean && cap > 0.0 {
        let excess_ratio = (post - mean) / cap;
        if excess_ratio > 0.15 {
            score += 2.0 * excess_ratio + 4.0 * (excess_ratio - 0.15);
        }
    }

    // Reusable-void check.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Fullest-bin tiebreak.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // New-bin gate.
    if is_new_bin && nxt > 0.0 {
        let fits_poorly = fitting_bins_count > 0 && (bin_capacity as f64 - mean) > item_size as f64 * 1.5;
        if fits_poorly {
            score -= 3.0;
        }
    }

    // Depth-2 lookahead.
    if nxt > 0.0 && post_residual >= next_item_size {
        let two_left = post_residual - next_item_size;
        if two_left > 0 && two_left <= 10 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Exact-fit chain.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size && next_item_size <= item_size {
        score -= 3.0 * (1.0 - progress);
    }

    // Mutation F.
    if nxt > 0.0 && !is_new_bin && post_residual < next_item_size && progress > 0.1 {
        let unusable = (next_item_size - post_residual) as f64;
        score += 0.75 * unusable * (1.0 - progress);
    }

    // Mutation G.
    if !is_new_bin && mean > 0.0 {
        let hom = ((post - mean).abs() / cap) as f64;
        score -= 0.8 * (1.0 - hom.min(1.0));
    }

    // Mutation H.
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let post_frac = post / cap;
        let mean_frac = (mean / cap).min(1.0);
        if post_frac > mean_frac {
            score += 3.5 * (post_frac - mean_frac) * (1.0 - 0.4 * progress);
        } else {
            score -= 1.2 * (mean_frac - post_frac);
        }
    }

    // Mutation I.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let usable_left = post_residual - next_item_size;
        if usable_left > 25 {
            score += 0.06 * (usable_left as f64 - 25.0);
        }
    }

    // Mutation J.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Mutation K.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 15.0 {
            score += (2.5 - shortfall * 0.15) * (1.0 + 0.5 * progress);
        }
    }

    // Mutation L.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.38;
        let skew = if x < peak { 0.7 } else { 1.45 };
        let bump = (x - peak) * (x - peak);
        let ramp = if progress > 0.25 { 1.0 + 0.6 * (progress - 0.25) } else { 0.85 + 0.6 * progress };
        score += 15.0 * skew * bump * ramp;
    }

    // Mutation M.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let open_can_chain = fitting_bins_count > 0
            && mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        let new_can_chain = new_post >= nxt;
        if open_can_chain && !new_can_chain {
            score += 5.0 + 3.0 * (1.0 - progress);
        } else if !open_can_chain && new_can_chain {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Mutation N.
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Mutation O.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 {
            let closeness = 1.0 - (after / cap).min(1.0);
            score -= 3.0 * closeness * closeness * (0.6 + 0.8 * progress);
        }
    }

    // Mutation P.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Mutation Q (borrowed from best): two-deep chain reward + mid-band penalty.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 == nxt || after as f64 == item_size as f64 {
            score -= 3.5 + 2.5 * (1.0 - progress);
        } else if (after as f64) >= nxt.min(item_size as f64) && after < 2 * next_item_size {
            score -= 1.0 * (1.0 - 0.5 * progress);
        }
        if after >= 30 && after <= 60 && progress > 0.3 {
            score += 1.8 * (progress - 0.3) / 0.7;
        }
    }

    // Mutation R (borrowed from best): progress-adaptive snugness.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        let band = 20.0 - 10.0 * progress;
        if snug < band {
            score -= 1.6 * (1.0 - snug / band) * (0.5 + progress);
        }
    }

    // Mutation S (borrowed from best): new-bin saturation hedge.
    if is_new_bin && open_bins_count > 8 {
        let frag = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
        score += 0.9 * frag * (0.4 + 0.6 * progress);
    }

    // Mutation T.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak2 = 0.30;
        let skew2 = if x < peak2 { 0.6 } else { 1.7 };
        let bump2 = (x - peak2) * (x - peak2);
        score += 6.0 * skew2 * bump2 * (1.0 + 1.4 * progress);
    }

    // Mutation U.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 15 {
            score -= 2.0 * (1.0 - after as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
    }

    // Mutation V.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if (new_post - nxt).abs() < 1.0 {
            score -= 4.0 * (1.0 - progress);
        } else if new_post < nxt && progress > 0.5 {
            score += 2.5 * (progress - 0.5) / 0.5;
        }
    }

    // Mutation W.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.05 {
            score += 4.5 * (excess_frac - 0.05) * (excess_frac - 0.05) / (excess_frac + 0.05) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation X.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_sum = after + mean;
        let pair_frac = pair_sum / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation Y.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation Z.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AA.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak3 = 0.26;
        let skew3 = if x < peak3 { 0.55 } else { 1.9 };
        let bump3 = (x - peak3) * (x - peak3);
        score += 5.0 * skew3 * bump3 * (0.8 + 1.6 * progress);
    }

    // Mutation AB.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let dev = (after - mean) / cap;
        if dev < 0.0 {
            score -= 1.4 * (-dev) * (1.0 - 0.5 * progress);
        } else {
            score += 0.7 * dev * dev * cap.min(100.0) / 10.0;
        }
    }

    // Mutation AC.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let diff = (after as f64 - item_size as f64).abs();
        if diff <= 6.0 && after > 0 {
            score -= (2.2 - diff * 0.25) * (0.5 + 0.9 * progress);
        }
    }

    // Mutation AD.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let after_new = new_post - nxt;
        if after_new >= 16.0 && after_new <= 34.0 {
            score += 2.5 * (1.0 - (after_new - 16.0) / 18.0) * (0.4 + 0.8 * progress);
        } else if after_new > 0.0 && after_new < 8.0 {
            score -= 1.5 * (1.0 - progress);
        }
    }

    // Mutation AE.
    if !is_new_bin && mean > 0.0 {
        let spread = (mean / cap - 0.25).abs();
        if spread > 0.10 {
            let snug2 = (bin_residual - item_size) as f64;
            if snug2 >= 0.0 && snug2 < 10.0 {
                score -= 1.1 * spread * (1.0 - snug2 / 10.0) * (0.6 + 0.6 * progress);
            }
        }
    }

    // Mutation AF (gen 29): consolidated dead-space shaping — merge the three
    // overlapping bump terms into a single calibrated trough-avoidance term
    // that penalizes leftovers near the least-refillable zone (~0.28 of
    // capacity) with progress-adaptive weight, replacing redundant bumps.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let trough = 0.28;
        let d = (x - trough).abs();
        score -= 2.2 * d.max(0.0) * (1.0 - d.min(1.0)) * (0.5 + 1.0 * progress);
    }

    // Mutation AG (gen 29): three-item chain anticipation — when the leftover
    // after seating both the current and next item equals the mean residual
    // class, a third item likely closes the bin; reward it strongly late.
    if !is_new_bin && nxt > 0.0 && mean > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let gap = (after as f64 - mean).abs();
        if gap <= 4.0 {
            score -= (2.8 - gap * 0.5) * (0.4 + 1.2 * progress);
        }
    }

    // Mutation AH (gen 29): best-fit escalation — when multiple bins fit,
    // sharpen preference for the bin with the tightest post-lookahead fit
    // using a normalized rank proxy (residual proximity to item size).
    if !is_new_bin && nxt > 0.0 && fitting_bins_count > 1 {
        let overhang = (bin_residual as f64 - item_size as f64).max(0.0);
        score += 0.12 * (overhang / cap) * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Base: two-step waste — leftover after ideally seating the lookahead item too.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Aggressive exact two-step match.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 12.0 + 6.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 5.0;
        } else if slack < 20 {
            score -= 2.0;
        }
    }

    // Perfect closure / small leftovers.
    if post_residual == 0 {
        score -= 24.0;
    } else if post_residual < 10 {
        score += 9.0 + 2.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Dead-space risk: quadratic waste penalty scaled by wasted fraction.
    if nxt > 0.0 && post > 0.0 && post < nxt {
        let waste_frac = (nxt - post) / nxt;
        score += 0.5 * (nxt - post).min(cap)
            + 4.0
            + 3.0 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.0 * waste_frac * (1.0 - progress);
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Void fraction, graded harder for large voids.
    let void_frac = post / resid;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.5 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 8.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 1.5;
    }

    // Opening cost for a brand-new bin.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 6.0 + 3.0 * progress;
        } else if pressure < 0.45 {
            score += 1.0 + 3.0 * progress;
        } else {
            score += 8.0 + 5.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.05;

    // Chain closure: residual exactly matches next item size.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 2.5 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.0;
    }

    // Endgame tightening.
    if progress > 0.85 && is_new_bin {
        score += 6.0 * (progress - 0.85) / 0.15;
    }

    // Snug fit, graded.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        if snug < 5.0 {
            score -= 2.5;
        }
        if snug < 15.0 {
            score -= 1.0 * (1.0 - snug / 15.0);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
    }

    // Dead-space ratio penalty, graded.
    if post > mean && cap > 0.0 {
        let excess_ratio = (post - mean) / cap;
        if excess_ratio > 0.15 {
            score += 2.0 * excess_ratio + 4.0 * (excess_ratio - 0.15);
        }
    }

    // Reusable-void check.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin via residual tiebreak.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // New-bin gate: open a fresh bin only when fits elsewhere are poor.
    if is_new_bin && nxt > 0.0 {
        let fits_poorly = fitting_bins_count > 0 && (bin_capacity as f64 - mean) > item_size as f64 * 1.5;
        if fits_poorly {
            score -= 3.0;
        }
    }

    // Depth-2 lookahead: small residual matching a future item class.
    if nxt > 0.0 && post_residual >= next_item_size {
        let two_left = post_residual - next_item_size;
        if two_left > 0 && two_left <= 10 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Exact-fit chain: post residual equals next item size with a small item.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size && next_item_size <= item_size {
        score -= 3.0 * (1.0 - progress);
    }

    // Mutation F: lookahead-aware dead-space hedge (sharpened weight).
    if nxt > 0.0 && !is_new_bin && post_residual < next_item_size && progress > 0.1 {
        let unusable = (next_item_size - post_residual) as f64;
        score += 0.75 * unusable * (1.0 - progress);
    }

    // Mutation G: residual homogeneity.
    if !is_new_bin && mean > 0.0 {
        let hom = ((post - mean).abs() / cap) as f64;
        score -= 0.8 * (1.0 - hom.min(1.0));
    }

    // Mutation H: dead-space ratio refinement vs fleet-average leftover fraction.
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let post_frac = post / cap;
        let mean_frac = (mean / cap).min(1.0);
        if post_frac > mean_frac {
            score += 3.5 * (post_frac - mean_frac) * (1.0 - 0.4 * progress);
        } else {
            score -= 1.2 * (mean_frac - post_frac);
        }
    }

    // Mutation I: anti-fragmentation sweep on large usable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let usable_left = post_residual - next_item_size;
        if usable_left > 25 {
            score += 0.06 * (usable_left as f64 - 25.0);
        }
    }

    // Mutation J: refillability-weighted leftover valuation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Mutation K: convex shortfall penalty for near-miss lookahead.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 15.0 {
            score += (2.5 - shortfall * 0.15) * (1.0 + 0.5 * progress);
        }
    }

    // Mutation L: asymmetric quadratic dead-space bump (peak 0.38 of capacity).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.38;
        let skew = if x < peak { 0.7 } else { 1.45 };
        let bump = (x - peak) * (x - peak);
        let ramp = if progress > 0.25 { 1.0 + 0.6 * (progress - 0.25) } else { 0.85 + 0.6 * progress };
        score += 15.0 * skew * bump * ramp;
    }

    // Mutation M: lookahead-aware new-bin arbitration.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let open_can_chain = fitting_bins_count > 0
            && mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        let new_can_chain = new_post >= nxt;
        if open_can_chain && !new_can_chain {
            score += 5.0 + 3.0 * (1.0 - progress);
        } else if !open_can_chain && new_can_chain {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Mutation N: utilization-maximizing tiebreak.
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Mutation O: two-step closure ladder.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 {
            let closeness = 1.0 - (after / cap).min(1.0);
            score -= 3.0 * closeness * closeness * (0.6 + 0.8 * progress);
        }
    }

    // Mutation P: fleet-aware dead-space cap.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let excess = after as f64 - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Mutation Q (borrowed from best): two-deep chain reward + mid-band dead-space penalty.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 == nxt || after as f64 == item_size as f64 {
            score -= 3.5 + 2.5 * (1.0 - progress);
        } else if (after as f64) >= nxt.min(item_size as f64) && after < 2 * next_item_size {
            score -= 1.0 * (1.0 - 0.5 * progress);
        }
        if after >= 30 && after <= 60 && progress > 0.3 {
            score += 1.8 * (progress - 0.3) / 0.7;
        }
    }

    // Mutation R (borrowed from best): progress-adaptive snugness.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        let band = 20.0 - 10.0 * progress;
        if snug < band {
            score -= 1.6 * (1.0 - snug / band) * (0.5 + progress);
        }
    }

    // Mutation S (borrowed from best): new-bin saturation hedge.
    if is_new_bin && open_bins_count > 8 {
        let frag = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
        score += 0.9 * frag * (0.4 + 0.6 * progress);
    }

    // Mutation T (refined gen 26): dead-space bump sharpened toward 0.30 of
    // capacity with stronger late-stream scaling.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak2 = 0.30;
        let skew2 = if x < peak2 { 0.6 } else { 1.7 };
        let bump2 = (x - peak2) * (x - peak2);
        score += 6.0 * skew2 * bump2 * (1.0 + 1.4 * progress);
    }

    // Mutation U: exact-closure ladder — reward small closable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 15 {
            score -= 2.0 * (1.0 - after as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
    }

    // Mutation V: new-bin exact-chain gate.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if (new_post - nxt).abs() < 1.0 {
            score -= 4.0 * (1.0 - progress);
        } else if new_post < nxt && progress > 0.5 {
            score += 2.5 * (progress - 0.5) / 0.5;
        }
    }

    // Mutation W (gen 26): dead-space ratio diagnostic — convex penalty for
    // post-lookahead leftover fraction exceeding the fleet mean.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.05 {
            score += 4.5 * (excess_frac - 0.05) * (excess_frac - 0.05) / (excess_frac + 0.05) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation X (gen 26): complementarity bonus — reward leftovers whose sum
    // with the fleet mean is jointly fillable by mid-size items.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_sum = after + mean;
        let pair_frac = pair_sum / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation Y (gen 26): lookahead-fit calibration — escalate exact-fill
    // reward late in the stream where closure value is highest.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation Z (gen 26): waste-shape guard — penalize the awkward middle
    // band 16..=29 of leftovers that are neither closable nor reusable.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AA (gen 29): sharpen the dead-space bump peak toward 0.26 of
    // capacity with progress-adaptive skew.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak3 = 0.26;
        let skew3 = if x < peak3 { 0.55 } else { 1.9 };
        let bump3 = (x - peak3) * (x - peak3);
        score += 5.0 * skew3 * bump3 * (0.8 + 1.6 * progress);
    }

    // Mutation AB (gen 29): fleet-mean residual-shape alignment.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let dev = (after - mean) / cap;
        if dev < 0.0 {
            score -= 1.4 * (-dev) * (1.0 - 0.5 * progress);
        } else {
            score += 0.7 * dev * dev * cap.min(100.0) / 10.0;
        }
    }

    // Mutation AC (gen 29): lookahead-complement pairing — chain-three bonus.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let diff = (after as f64 - item_size as f64).abs();
        if diff <= 6.0 && after > 0 {
            score -= (2.2 - diff * 0.25) * (0.5 + 0.9 * progress);
        }
    }

    // Mutation AD (gen 29): new-bin dead-space preemption.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let after_new = new_post - nxt;
        if after_new >= 16.0 && after_new <= 34.0 {
            score += 2.5 * (1.0 - (after_new - 16.0) / 18.0) * (0.4 + 0.8 * progress);
        } else if after_new > 0.0 && after_new < 8.0 {
            score -= 1.5 * (1.0 - progress);
        }
    }

    // Mutation AE (gen 29): residual-variance dampener — tighten snugness
    // preference when fleet residuals deviate from the ideal quarter-capacity.
    if !is_new_bin && mean > 0.0 {
        let spread = (mean / cap - 0.25).abs();
        if spread > 0.10 {
            let snug2 = (bin_residual - item_size) as f64;
            if snug2 >= 0.0 && snug2 < 10.0 {
                score -= 1.1 * spread * (1.0 - snug2 / 10.0) * (0.6 + 0.6 * progress);
            }
        }
    }

    // Mutation AF (gen 29, Combine): fuse fine-grained residual fitting with
    // lookahead anticipation — a graded "dual-closure" bonus when BOTH the
    // current fit is snug AND the post-lookahead leftover is small/closable,
    // rewarding bins that stay productive across two consecutive steps.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let snug_now = (bin_residual - item_size) as f64;
        let after = (post_residual - next_item_size) as f64;
        let snug_term = (1.0 - (snug_now / 12.0).min(1.0)).max(0.0);
        let close_term = (1.0 - after / 20.0).max(0.0);
        score -= 2.6 * snug_term * close_term * (0.7 + 0.7 * progress);
    }

    // Mutation AG (gen 29, Combine): lookahead-anticipation fit — when the
    // next item would leave a leftover that exactly chains a third step
    // (post - next == next or == item), grant a strong progress-scaled
    // reward; otherwise penalize leftovers just under the next item size
    // more sharply mid-stream where they strand the most capacity.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 8.0 && progress > 0.15 {
            score += (3.2 - shortfall * 0.3) * (0.8 + 0.9 * progress);
        }
    }

    // Mutation AH (gen 29, Combine): fleet-homogeneous closure — prefer bins
    // whose post-lookahead leftover sits slightly BELOW the fleet mean (leaves
    // headroom for the fleet to absorb future items) but penalize extremes
    // in either direction with a convex term.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let target = mean * 0.85;
        let gap = after - target;
        if gap > 0.0 {
            score += 0.10 * gap * (0.6 + 0.6 * progress);
        } else {
            score -= 0.10 * (-gap).min(15.0) * (1.0 - 0.4 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Two-step waste base.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Aggressive exact two-step match.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 12.0 + 6.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 5.0;
        } else if slack < 20 {
            score -= 2.0;
        }
    }

    // Perfect closure / small leftovers.
    if post_residual == 0 {
        score -= 24.0;
    } else if post_residual < 10 {
        score += 9.0 + 2.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Dead-space risk: quadratic waste penalty scaled by wasted fraction.
    if nxt > 0.0 && post > 0.0 && post < nxt {
        let waste_frac = (nxt - post) / nxt;
        score += 0.5 * (nxt - post).min(cap)
            + 4.0
            + 3.0 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.0 * waste_frac * (1.0 - progress);
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Void fraction, graded harder for large voids.
    let void_frac = post / resid;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.5 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 8.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 1.5;
    }

    // Opening cost for a brand-new bin.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 6.0 + 3.0 * progress;
        } else if pressure < 0.45 {
            score += 1.0 + 3.0 * progress;
        } else {
            score += 8.0 + 5.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.05;

    // Chain closure: residual exactly matches next item size.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 2.5 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.0;
    }

    // Endgame tightening.
    if progress > 0.85 && is_new_bin {
        score += 6.0 * (progress - 0.85) / 0.15;
    }

    // Snug fit, graded.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        if snug < 5.0 {
            score -= 2.5;
        }
        if snug < 15.0 {
            score -= 1.0 * (1.0 - snug / 15.0);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
    }

    // Dead-space ratio penalty, graded.
    if post > mean && cap > 0.0 {
        let excess_ratio = (post - mean) / cap;
        if excess_ratio > 0.15 {
            score += 2.0 * excess_ratio + 4.0 * (excess_ratio - 0.15);
        }
    }

    // Reusable-void check.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin via residual tiebreak.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // New-bin gate: open a fresh bin only when fits elsewhere are poor.
    if is_new_bin && nxt > 0.0 {
        let fits_poorly = fitting_bins_count > 0 && (bin_capacity as f64 - mean) > item_size as f64 * 1.5;
        if fits_poorly {
            score -= 3.0;
        }
    }

    // Depth-2 lookahead: small residual matching a future item class.
    if nxt > 0.0 && post_residual >= next_item_size {
        let two_left = post_residual - next_item_size;
        if two_left > 0 && two_left <= 10 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Exact-fit chain: post residual equals next item size with a small item.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size && next_item_size <= item_size {
        score -= 3.0 * (1.0 - progress);
    }

    // Mutation F: lookahead-aware dead-space hedge (sharpened weight).
    if nxt > 0.0 && !is_new_bin && post_residual < next_item_size && progress > 0.1 {
        let unusable = (next_item_size - post_residual) as f64;
        score += 0.75 * unusable * (1.0 - progress);
    }

    // Mutation G: residual homogeneity.
    if !is_new_bin && mean > 0.0 {
        let hom = ((post - mean).abs() / cap) as f64;
        score -= 0.8 * (1.0 - hom.min(1.0));
    }

    // Mutation H: dead-space ratio refinement vs fleet-average leftover fraction.
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let post_frac = post / cap;
        let mean_frac = (mean / cap).min(1.0);
        if post_frac > mean_frac {
            score += 3.5 * (post_frac - mean_frac) * (1.0 - 0.4 * progress);
        } else {
            score -= 1.2 * (mean_frac - post_frac);
        }
    }

    // Mutation I: anti-fragmentation sweep on large usable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let usable_left = post_residual - next_item_size;
        if usable_left > 25 {
            score += 0.06 * (usable_left as f64 - 25.0);
        }
    }

    // Mutation J: refillability-weighted leftover valuation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Mutation K: convex shortfall penalty for near-miss lookahead.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 15.0 {
            score += (2.5 - shortfall * 0.15) * (1.0 + 0.5 * progress);
        }
    }

    // Mutation L: asymmetric quadratic dead-space bump.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.38;
        let skew = if x < peak { 0.7 } else { 1.45 };
        let bump = (x - peak) * (x - peak);
        let ramp = if progress > 0.25 { 1.0 + 0.6 * (progress - 0.25) } else { 0.85 + 0.6 * progress };
        score += 15.0 * skew * bump * ramp;
    }

    // Mutation M: lookahead-aware new-bin arbitration.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let open_can_chain = fitting_bins_count > 0
            && mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        let new_can_chain = new_post >= nxt;
        if open_can_chain && !new_can_chain {
            score += 5.0 + 3.0 * (1.0 - progress);
        } else if !open_can_chain && new_can_chain {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Mutation N: utilization-maximizing tiebreak.
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Mutation O: two-step closure ladder.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 {
            let closeness = 1.0 - (after / cap).min(1.0);
            score -= 3.0 * closeness * closeness * (0.6 + 0.8 * progress);
        }
    }

    // Mutation P: fleet-aware dead-space cap.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Mutation Q: two-deep chain reward + mid-band dead-space penalty.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 == nxt || after as f64 == item_size as f64 {
            score -= 3.5 + 2.5 * (1.0 - progress);
        } else if (after as f64) >= nxt.min(item_size as f64) && after < 2 * next_item_size {
            score -= 1.0 * (1.0 - 0.5 * progress);
        }
        if after >= 30 && after <= 60 && progress > 0.3 {
            score += 1.8 * (progress - 0.3) / 0.7;
        }
    }

    // Mutation R: progress-adaptive snugness.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        let band = 20.0 - 10.0 * progress;
        if snug < band {
            score -= 1.6 * (1.0 - snug / band) * (0.5 + progress);
        }
    }

    // Mutation S: new-bin saturation hedge.
    if is_new_bin && open_bins_count > 8 {
        let frag = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
        score += 0.9 * frag * (0.4 + 0.6 * progress);
    }

    // Mutation T: sharpened dead-space bump peak toward 0.30 of capacity.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak2 = 0.30;
        let skew2 = if x < peak2 { 0.6 } else { 1.7 };
        let bump2 = (x - peak2) * (x - peak2);
        score += 6.0 * skew2 * bump2 * (1.0 + 1.4 * progress);
    }

    // Mutation U: exact-closure ladder — reward small closable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 15 {
            score -= 2.0 * (1.0 - after as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
    }

    // Mutation V: new-bin exact-chain gate.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if (new_post - nxt).abs() < 1.0 {
            score -= 4.0 * (1.0 - progress);
        } else if new_post < nxt && progress > 0.5 {
            score += 2.5 * (progress - 0.5) / 0.5;
        }
    }

    // Mutation W: dead-space ratio diagnostic — convex excess penalty.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.05 {
            score += 4.5 * (excess_frac - 0.05) * (excess_frac - 0.05) / (excess_frac + 0.05) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation X: complementarity bonus — leftover pairs jointly fillable.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_sum = after + mean;
        let pair_frac = pair_sum / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation Y: lookahead-fit calibration for exact fill late in stream.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation Z: waste-shape guard for awkward middle band 16..=29.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AA (gen 29): post-fit density coupling — reward bins where the
    // item lands snugly against the *current* residual while the leftover
    // after the lookahead is small relative to the fleet mean, reinforcing
    // compaction in the diagnosed residual-dead-space direction.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let rel = after / mean;
        if rel < 0.5 {
            score -= 1.6 * (1.0 - rel) * (0.5 + 0.5 * progress);
        } else if rel > 1.6 {
            score += 0.8 * (rel - 1.6).min(2.0) * (0.4 + 0.6 * progress);
        }
    }

    // Mutation AB (gen 29): dual-peak dead-space bump — add a secondary,
    // narrower bump centered at 0.12 of capacity so very small leftovers
    // (nearly-closed bins) get an extra push toward exact closure, while
    // keeping the primary 0.30 peak intact.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let bump_small = (x - 0.12) * (x - 0.12);
        score -= 3.0 * bump_small * (1.0 - 0.5 * progress);
    }

    // Mutation AC (gen 29): lookahead-mismatch arbitration for new bins —
    // when the fresh bin's post-fit leftover cannot serve the next item but
    // open bins' average leftover can, penalize opening more strongly late.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if new_post < nxt && mean >= nxt && fitting_bins_count > 0 {
            score += 3.0 + 4.0 * progress;
        }
    }

    // Mutation AD (gen 29): residual-band sharpening — extra penalty for
    // leftovers in the 8..=15 band when the next item cannot use them,
    // tightening the diagnosed suboptimal-residual weakness.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 8 && after <= 15 {
            score += 0.9 * (1.0 - (after - 8) as f64 / 7.0) * (0.6 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Two-step waste base.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Aggressive exact two-step match.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 12.0 + 6.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 5.0;
        } else if slack < 20 {
            score -= 2.0;
        }
    }

    // Perfect closure / small leftovers.
    if post_residual == 0 {
        score -= 24.0;
    } else if post_residual < 10 {
        score += 9.0 + 2.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Dead-space risk: quadratic waste penalty scaled by wasted fraction.
    if nxt > 0.0 && post > 0.0 && post < nxt {
        let waste_frac = (nxt - post) / nxt;
        score += 0.5 * (nxt - post).min(cap)
            + 4.0
            + 3.0 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.0 * waste_frac * (1.0 - progress);
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Void fraction, graded harder for large voids.
    let void_frac = post / resid;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.5 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 8.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 1.5;
    }

    // Opening cost for a brand-new bin.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 6.0 + 3.0 * progress;
        } else if pressure < 0.45 {
            score += 1.0 + 3.0 * progress;
        } else {
            score += 8.0 + 5.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.05;

    // Chain closure: residual exactly matches next item size.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 2.5 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.0;
    }

    // Endgame tightening.
    if progress > 0.85 && is_new_bin {
        score += 6.0 * (progress - 0.85) / 0.15;
    }

    // Snug fit, graded.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        if snug < 5.0 {
            score -= 2.5;
        }
        if snug < 15.0 {
            score -= 1.0 * (1.0 - snug / 15.0);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
    }

    // Dead-space ratio penalty, graded.
    if post > mean && cap > 0.0 {
        let excess_ratio = (post - mean) / cap;
        if excess_ratio > 0.15 {
            score += 2.0 * excess_ratio + 4.0 * (excess_ratio - 0.15);
        }
    }

    // Reusable-void check.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin via residual tiebreak.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // New-bin gate: open a fresh bin only when fits elsewhere are poor.
    if is_new_bin && nxt > 0.0 {
        let fits_poorly = fitting_bins_count > 0 && (bin_capacity as f64 - mean) > item_size as f64 * 1.5;
        if fits_poorly {
            score -= 3.0;
        }
    }

    // Depth-2 lookahead: small residual matching a future item class.
    if nxt > 0.0 && post_residual >= next_item_size {
        let two_left = post_residual - next_item_size;
        if two_left > 0 && two_left <= 10 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Exact-fit chain: post residual equals next item size with a small item.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size && next_item_size <= item_size {
        score -= 3.0 * (1.0 - progress);
    }

    // Mutation F: lookahead-aware dead-space hedge (sharpened weight).
    if nxt > 0.0 && !is_new_bin && post_residual < next_item_size && progress > 0.1 {
        let unusable = (next_item_size - post_residual) as f64;
        score += 0.75 * unusable * (1.0 - progress);
    }

    // Mutation G: residual homogeneity.
    if !is_new_bin && mean > 0.0 {
        let hom = ((post - mean).abs() / cap) as f64;
        score -= 0.8 * (1.0 - hom.min(1.0));
    }

    // Mutation H: dead-space ratio refinement vs fleet-average leftover fraction.
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let post_frac = post / cap;
        let mean_frac = (mean / cap).min(1.0);
        if post_frac > mean_frac {
            score += 3.5 * (post_frac - mean_frac) * (1.0 - 0.4 * progress);
        } else {
            score -= 1.2 * (mean_frac - post_frac);
        }
    }

    // Mutation I: anti-fragmentation sweep on large usable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let usable_left = post_residual - next_item_size;
        if usable_left > 25 {
            score += 0.06 * (usable_left as f64 - 25.0);
        }
    }

    // Mutation J: refillability-weighted leftover valuation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Mutation K: convex shortfall penalty for near-miss lookahead.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 15.0 {
            score += (2.5 - shortfall * 0.15) * (1.0 + 0.5 * progress);
        }
    }

    // Mutation L: asymmetric quadratic dead-space bump (peak 0.38 of capacity).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.38;
        let skew = if x < peak { 0.7 } else { 1.45 };
        let bump = (x - peak) * (x - peak);
        let ramp = if progress > 0.25 { 1.0 + 0.6 * (progress - 0.25) } else { 0.85 + 0.6 * progress };
        score += 15.0 * skew * bump * ramp;
    }

    // Mutation M: lookahead-aware new-bin arbitration.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let open_can_chain = fitting_bins_count > 0
            && mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        let new_can_chain = new_post >= nxt;
        if open_can_chain && !new_can_chain {
            score += 5.0 + 3.0 * (1.0 - progress);
        } else if !open_can_chain && new_can_chain {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Mutation N: utilization-maximizing tiebreak.
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Mutation O: two-step closure ladder.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 {
            let closeness = 1.0 - (after / cap).min(1.0);
            score -= 3.0 * closeness * closeness * (0.6 + 0.8 * progress);
        }
    }

    // Mutation P: fleet-aware dead-space cap.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Mutation Q: two-deep chain reward + mid-band dead-space penalty.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 == nxt || after as f64 == item_size as f64 {
            score -= 3.5 + 2.5 * (1.0 - progress);
        } else if (after as f64) >= nxt.min(item_size as f64) && after < 2 * next_item_size {
            score -= 1.0 * (1.0 - 0.5 * progress);
        }
        if after >= 30 && after <= 60 && progress > 0.3 {
            score += 1.8 * (progress - 0.3) / 0.7;
        }
    }

    // Mutation R: progress-adaptive snugness.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        let band = 20.0 - 10.0 * progress;
        if snug < band {
            score -= 1.6 * (1.0 - snug / band) * (0.5 + progress);
        }
    }

    // Mutation S: new-bin saturation hedge.
    if is_new_bin && open_bins_count > 8 {
        let frag = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
        score += 0.9 * frag * (0.4 + 0.6 * progress);
    }

    // Mutation T (gen 29): progress-adaptive dead-space bump peak — the peak
    // drifts from 0.34 toward 0.26 of capacity as the stream advances, since
    // late-stream leftover targets should shrink for tighter compaction.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak2 = 0.34 - 0.08 * progress;
        let skew2 = if x < peak2 { 0.6 } else { 1.7 };
        let bump2 = (x - peak2) * (x - peak2);
        score += 6.0 * skew2 * bump2 * (1.0 + 1.4 * progress);
    }

    // Mutation U: exact-closure ladder — reward small closable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 15 {
            score -= 2.0 * (1.0 - after as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
    }

    // Mutation V: new-bin exact-chain gate.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if (new_post - nxt).abs() < 1.0 {
            score -= 4.0 * (1.0 - progress);
        } else if new_post < nxt && progress > 0.5 {
            score += 2.5 * (progress - 0.5) / 0.5;
        }
    }

    // Mutation W: dead-space ratio diagnostic — convex penalty for leftover
    // fraction exceeding the fleet mean, with early-stream grace period.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.05 {
            score += 4.5 * (excess_frac - 0.05) * (excess_frac - 0.05) / (excess_frac + 0.05) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation X: complementarity bonus — leftover pairs with fleet mean to
    // jointly form a fillable unit by mid-size items.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_sum = after + mean;
        let pair_frac = pair_sum / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation Y: lookahead-fit calibration — exact fill of post-residual
    // escalates in value late in the stream.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation Z: waste-shape guard — penalize the awkward middle band of
    // leftovers (16..=29) that accumulate dead space.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AA (gen 29): fleet-mean closure pressure — when the post-lookahead
    // leftover is small relative to the fleet mean, the bin is nearly "done";
    // reward keeping such bins compact so they can be closed out early.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let ratio = after / mean;
        if ratio < 0.35 {
            score -= 1.6 * (1.0 - ratio / 0.35) * (0.5 + 0.9 * progress);
        }
    }

    // Mutation AB (gen 29): item-size-aware dead-space pricing — dead space
    // below the current item is worse when the item itself is small (little
    // chance of a later small item matching), so scale the stranded-space
    // penalty by the inverse item fraction.
    if !is_new_bin && nxt > 0.0 && post > 0.0 && post < nxt {
        let item_frac = item_size as f64 / cap;
        score += 2.0 * (1.0 - item_frac.min(1.0)) * (nxt - post) / nxt * (0.4 + 0.6 * progress);
    }

    // Mutation AC (gen 29): tight-bin preservation — when only a couple of
    // bins can still chain the next item, avoid scattering the tightest
    // residual by an extra lookahead-consistency reward.
    if !is_new_bin && fitting_bins_count <= 2 && nxt > 0.0 && post_residual >= next_item_size {
        score -= 1.2 * (1.0 - progress);
    }

    score
}

