    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 {
            let closeness = 1.0 - (after / cap).min(1.0);
            score -= 3.0 * closeness * closeness * (0.6 + 0.8 * progress);
        }
    }

    // Mutation A (gen 30): convex excess-fraction penalty vs fleet mean —
    // targets bins whose post-lookahead leftover drifts far above the fleet
    // average, the diagnosed suboptimal-residual weakness.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.05 {
            score += 4.5 * (excess_frac - 0.05) * (excess_frac - 0.05) / (excess_frac + 0.05) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation B (gen 30): complementarity bonus — reward bins whose leftover
    // plus fleet mean residual sums to a jointly fillable quantity.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_frac = (after + mean) / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation C (gen 30): awkward-middle-band guard (16..=29 leftovers) —
    // neither small-closable nor large-reusable shapes accumulate dead space.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation D (gen 30): late-stream exact-fill escalation.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation E (gen 30): dual-threshold new-bin gate — open fresh bins only
    // when every open fit leaves a poor chain and the fleet is saturated.
    if is_new_bin && nxt > 0.0 && fitting_bins_count > 0 {
        let best_chain_possible = mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        if !best_chain_possible && open_bins_count as f64 * (mean / cap) > 2.5 {
            score -= 1.5 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = (step_index as f64 / (total_items.max(1) as f64)).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let post_norm = post / cap;
    let item_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;
    let mean_norm = mean_residual / cap;

    // Base: prefer minimal post residual, with non-linear shrink reward
    let mut score = post * (1.0 + 0.8 * post_norm * post_norm);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate leftover space; late, demand tight packing.
    let tightness = 0.5 + 1.5 * progress * progress;
    score += 12.0 * tightness * post_norm * post_norm * post_norm;

    // Reward filling a bin completely (quadratic bonus decaying with post)
    score -= 6.0 * item_norm * (1.0 - post_norm) * (1.0 - post_norm);

    // Lookahead: bonus if next item fits into post_residual (smooth kernel)
    if next_item_size > 0 {
        let fit_gap = (post - next_norm * cap).max(0.0) / cap;
        let kernel = (-fit_gap * fit_gap * 8.0).exp();
        score -= 8.0 * kernel * (0.4 + 0.6 * progress);
        // Penalize if next item would be stranded by this choice
        let strand = (next_norm * cap - post).max(0.0) / cap;
        score += 5.0 * strand * strand;
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - post_norm);
    }

    // Penalize scattering across many open bins when mean residual is high
    score += 0.05 * open_bins_count as f64 * (mean_norm - post_norm).abs();

    // New-bin candidate: keep it competitive only when nothing fits well
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let openness = 1.0 - progress;
        // Favor new bin early or when open bins have tiny residuals
        score = 20.0 + 25.0 * (1.0 - openness) - 18.0 * scarcity * (1.0 - mean_norm);
        score += 10.0 * item_norm * item_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
