        }
        if snug < 15.0 {
            score -= 1.0 * (1.0 - snug / 15.0);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
    }

    // Dead-space ratio penalty, graded.
    if post > mean && cap > 0.0 {
        let excess_ratio = (post - mean) / cap;
        if excess_ratio > 0.15 {
            score += 2.0 * excess_ratio + 4.0 * (excess_ratio - 0.15);
        }
    }

    // Reusable-void check.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin via residual tiebreak.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // New-bin gate.
    if is_new_bin && nxt > 0.0 {
        let fits_poorly = fitting_bins_count > 0 && (bin_capacity as f64 - mean) > item_size as f64 * 1.5;
        if fits_poorly {
            score -= 3.0;
        }
    }

    // Depth-2 lookahead.
    if nxt > 0.0 && post_residual >= next_item_size {
        let two_left = post_residual - next_item_size;
        if two_left > 0 && two_left <= 10 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Exact-fit chain.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size && next_item_size <= item_size {
        score -= 3.0 * (1.0 - progress);
    }

    // Mutation F: lookahead-aware dead-space hedge.
    if nxt > 0.0 && !is_new_bin && post_residual < next_item_size && progress > 0.1 {
        let unusable = (next_item_size - post_residual) as f64;
        score += 0.75 * unusable * (1.0 - progress);
    }

    // Mutation G: residual homogeneity.
    if !is_new_bin && mean > 0.0 {
        let hom = ((post - mean).abs() / cap) as f64;
        score -= 0.8 * (1.0 - hom.min(1.0));
    }

    // Mutation H: dead-space ratio refinement vs fleet mean.
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let post_frac = post / cap;
        let mean_frac = (mean / cap).min(1.0);
        if post_frac > mean_frac {
            score += 3.5 * (post_frac - mean_frac) * (1.0 - 0.4 * progress);
        } else {
            score -= 1.2 * (mean_frac - post_frac);
        }
    }

    // Mutation I: anti-fragmentation sweep.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let usable_left = post_residual - next_item_size;
        if usable_left > 25 {
            score += 0.06 * (usable_left as f64 - 25.0);
        }
    }

    // Mutation J: refillability-weighted leftover valuation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Mutation K: convex shortfall penalty.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 15.0 {
            score += (2.5 - shortfall * 0.15) * (1.0 + 0.5 * progress);
        }
    }

    // Mutation L: asymmetric quadratic dead-space bump.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.38;
        let skew = if x < peak { 0.7 } else { 1.45 };
        let bump = (x - peak) * (x - peak);
        let ramp = if progress > 0.25 { 1.0 + 0.6 * (progress - 0.25) } else { 0.85 + 0.6 * progress };
        score += 15.0 * skew * bump * ramp;
    }

    // Mutation M: lookahead-aware new-bin arbitration.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let open_can_chain = fitting_bins_count > 0
            && mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        let new_can_chain = new_post >= nxt;
        if open_can_chain && !new_can_chain {
            score += 5.0 + 3.0 * (1.0 - progress);
        } else if !open_can_chain && new_can_chain {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Mutation N: utilization-maximizing tiebreak.
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Mutation O: two-step closure ladder.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 {
            let closeness = 1.0 - (after / cap).min(1.0);
            score -= 3.0 * closeness * closeness * (0.6 + 0.8 * progress);
        }
    }

    // Mutation P: fleet-aware dead-space cap.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Mutation T: dead-space bump sharpened toward 0.30.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak2 = 0.30;
        let skew2 = if x < peak2 { 0.6 } else { 1.7 };
        let bump2 = (x - peak2) * (x - peak2);
        score += 6.0 * skew2 * bump2 * (1.0 + 1.4 * progress);
    }

    // Mutation U: exact-closure ladder.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 15 {
            score -= 2.0 * (1.0 - after as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
    }

    // Mutation V: new-bin exact-chain gate.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if (new_post - nxt).abs() < 1.0 {
            score -= 4.0 * (1.0 - progress);
        } else if new_post < nxt && progress > 0.5 {
            score += 2.5 * (progress - 0.5) / 0.5;
        }
    }

    // Mutation W: dead-space ratio diagnostic.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.05 {
            score += 4.5 * (excess_frac - 0.05) * (excess_frac - 0.05) / (excess_frac + 0.05) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation X: complementarity bonus.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_sum = after + mean;
        let pair_frac = pair_sum / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation Y: lookahead-fit calibration.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation Z: waste-shape guard on awkward mid-band.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AA: dead-space bump peak at 0.26 with progress-adaptive skew.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak3 = 0.26;
        let skew3 = if x < peak3 { 0.55 } else { 1.9 };
        let bump3 = (x - peak3) * (x - peak3);
        score += 5.0 * skew3 * bump3 * (0.8 + 1.6 * progress);
    }

    // Mutation AB: fleet-mean residual-shape alignment.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let dev = (after - mean) / cap;
        if dev < 0.0 {
            score -= 1.4 * (-dev) * (1.0 - 0.5 * progress);
        } else {
            score += 0.7 * dev * dev * cap.min(100.0) / 10.0;
        }
    }

    // Mutation AC: lookahead-complement pairing (three-item chain).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let diff = (after as f64 - item_size as f64).abs();
        if diff <= 6.0 && after > 0 {
            score -= (2.2 - diff * 0.25) * (0.5 + 0.9 * progress);
        }
    }

    // Mutation AD: new-bin dead-space preemption.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let after_new = new_post - nxt;
        if after_new >= 16.0 && after_new <= 34.0 {
            score += 2.5 * (1.0 - (after_new - 16.0) / 18.0) * (0.4 + 0.8 * progress);
        } else if after_new > 0.0 && after_new < 8.0 {
            score -= 1.5 * (1.0 - progress);
        }
    }

    // Mutation AE: residual-variance dampener.
    if !is_new_bin && mean > 0.0 {
        let spread = (mean / cap - 0.25).abs();
        if spread > 0.10 {
            let snug2 = (bin_residual - item_size) as f64;
            if snug2 >= 0.0 && snug2 < 10.0 {
                score -= 1.1 * spread * (1.0 - snug2 / 10.0) * (0.6 + 0.6 * progress);
            }
        }
    }

    // === Gen 30 mutations ===

    // Mutation AF: dual-item lookahead — reward bins that could seat BOTH the
    // current item and the next item within the residual (post >= item + next),
    // which directly targets the diagnosed dead-space weakness by chaining.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size + item_size {
        let after2 = post_residual - next_item_size - item_size;
        score -= 2.5 * (1.0 - (after2 as f64 / cap).min(1.0)) * (0.5 + 0.7 * progress);
    }

    // Mutation AG: consolidate the overlapping dead-space bumps (L + T + AA)
    // into a single sharper asymmetric bump peaking at 0.22 of capacity with
    // stronger late-stream weight — the previous three overlapping bumps
    // flattened the minimum and diluted the steering signal.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak4 = 0.22;
        let skew4 = if x < peak4 { 0.45 } else { 2.1 };
        let bump4 = (x - peak4) * (x - peak4);
        score += 9.0 * skew4 * bump4 * (0.7 + 1.5 * progress);
    }

    // Mutation AH: tight-fit escalation — when the post-lookahead leftover is
    // nearly zero (within 3 of the next item exactly filling it), escalate the
    // reward late in the stream to force perfect closures.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after <= 3 {
            score -= (3.0 - after as f64) * (1.5 + 2.0 * progress);
        }
    }

    // Mutation AI: new-bin arbitration refinement — when the fleet has many
    // open bins with small mean residual (fragmented fleet), make opening a
    // new bin cheaper so we don't strand capacity in nearly-full bins.
    if is_new_bin && open_bins_count > 4 && mean > 0.0 && mean < 0.35 * cap {
        score -= 2.0 * (1.0 - mean / (0.35 * cap)) * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which "capacity fraction" band does it fall in?
    let item_class = item_size / 25; // 0: tiny(1-24), 1: small(25-49), 2: medium(50-74), 3: large(75-100)
    let next_class = (next_item_size as u32) / 25;

    // Reward tight fits: post_residual near 0 is ideal.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 25 {
        score -= 12.0;
    }

    // Penalize dead space that is too small for typical future items:
    // post_residual below the smallest item class wastes the bin.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Modulo-10 harmonic: residuals that are multiples of 10 pack well with
    // common item sizes; reward them, penalize awkward odd remainders.
    let pr_mod = post_residual % 10;
    if pr_mod == 0 {
        score -= 8.0;
    } else {
        score += pr_mod as f64 * 1.5;
    }

    // Lookahead coupling: if the next item fits the post residual exactly
    // (harmonic pairing), strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair_gap = post_residual - next_item_size;
        if pair_gap == 0 {
            score -= 70.0;
        } else if pair_gap <= 15 {
            score -= 25.0;
        } else {
            score += pair_gap as f64 * 0.6;
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize proportionally to how
        // stranded the leftover space is.
        score += (post_residual as f64) * 0.8;
    }

    // Integer-division threshold on bin fill fraction (harmonic quarters).
    let fill_quarter = (bin_capacity - bin_residual) / (bin_capacity / 4);
    score -= fill_quarter as f64 * 5.0; // prefer filling fuller bins first

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless the item is
    // large or no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let base_penalty = 90.0;
        let size_bonus = if item_class >= 3 { 40.0 } else { 0.0 };
        let scarcity_bonus = if fitting_bins_count == 0 { 200.0 } else { 0.0 };
        score += base_penalty + size_bonus - scarcity_bonus;
    }

    // Progression-aware: later in the stream, be slightly more eager to close
    // bins tightly rather than spreading across many open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0;
    if open_bins_count > 8 {
        score += (open_bins_count as f64 - 8.0) * 1.2;
    }

    // Mean-residual pull: prefer bins whose residual is below average
    // (i.e., fuller than average) to consolidate space.
    score -= (mean_residual - bin_residual as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Base: two-step waste — leftover after ideally seating the lookahead item too.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Aggressive exact two-step match.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 12.0 + 6.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 5.0;
        } else if slack < 20 {
            score -= 2.0;
        }
    }

    // Perfect closure / small leftovers.
    if post_residual == 0 {
        score -= 24.0;
    } else if post_residual < 10 {
        score += 9.0 + 2.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Dead-space risk: quadratic waste penalty scaled by wasted fraction.
    if nxt > 0.0 && post > 0.0 && post < nxt {
        let waste_frac = (nxt - post) / nxt;
        score += 0.5 * (nxt - post).min(cap)
            + 4.0
            + 3.0 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.0 * waste_frac * (1.0 - progress);
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Void fraction, graded harder for large voids.
    let void_frac = post / resid;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.5 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 8.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 1.5;
    }

    // Opening cost for a brand-new bin.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 6.0 + 3.0 * progress;
        } else if pressure < 0.45 {
            score += 1.0 + 3.0 * progress;
        } else {
            score += 8.0 + 5.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.05;

    // Chain closure: residual exactly matches next item size.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 2.5 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.0;
    }

    // Endgame tightening.
    if progress > 0.85 && is_new_bin {
        score += 6.0 * (progress - 0.85) / 0.15;
    }

    // Snug fit, graded.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        if snug < 5.0 {
            score -= 2.5;
        }
        if snug < 15.0 {
            score -= 1.0 * (1.0 - snug / 15.0);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
    }

    // Dead-space ratio penalty, graded.
    if post > mean && cap > 0.0 {
        let excess_ratio = (post - mean) / cap;
        if excess_ratio > 0.15 {
            score += 2.0 * excess_ratio + 4.0 * (excess_ratio - 0.15);
        }
    }

    // Reusable-void check.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin via residual tiebreak.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // New-bin gate: open a fresh bin only when fits elsewhere are poor.
    if is_new_bin && nxt > 0.0 {
        let fits_poorly = fitting_bins_count > 0 && (bin_capacity as f64 - mean) > item_size as f64 * 1.5;
        if fits_poorly {
            score -= 3.0;
        }
    }

    // Depth-2 lookahead: small residual matching a future item class.
    if nxt > 0.0 && post_residual >= next_item_size {
        let two_left = post_residual - next_item_size;
        if two_left > 0 && two_left <= 10 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Exact-fit chain: post residual equals next item size with a small item.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size && next_item_size <= item_size {
        score -= 3.0 * (1.0 - progress);
    }

    // Mutation F: lookahead-aware dead-space hedge (sharpened weight).
    if nxt > 0.0 && !is_new_bin && post_residual < next_item_size && progress > 0.1 {
        let unusable = (next_item_size - post_residual) as f64;
        score += 0.75 * unusable * (1.0 - progress);
    }

    // Mutation G: residual homogeneity.
    if !is_new_bin && mean > 0.0 {
        let hom = ((post - mean).abs() / cap) as f64;
        score -= 0.8 * (1.0 - hom.min(1.0));
    }

    // Mutation H: dead-space ratio refinement vs fleet-average leftover fraction.
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let post_frac = post / cap;
        let mean_frac = (mean / cap).min(1.0);
        if post_frac > mean_frac {
            score += 3.5 * (post_frac - mean_frac) * (1.0 - 0.4 * progress);
        } else {
            score -= 1.2 * (mean_frac - post_frac);
        }
    }

    // Mutation I: anti-fragmentation sweep on large usable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let usable_left = post_residual - next_item_size;
        if usable_left > 25 {
            score += 0.06 * (usable_left as f64 - 25.0);
        }
    }

    // Mutation J: refillability-weighted leftover valuation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Mutation K: convex shortfall penalty for near-miss lookahead.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 15.0 {
            score += (2.5 - shortfall * 0.15) * (1.0 + 0.5 * progress);
        }
    }

    // Mutation L: asymmetric quadratic dead-space bump (peak 0.38 of capacity).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.38;
        let skew = if x < peak { 0.7 } else { 1.45 };
        let bump = (x - peak) * (x - peak);
        let ramp = if progress > 0.25 { 1.0 + 0.6 * (progress - 0.25) } else { 0.85 + 0.6 * progress };
        score += 15.0 * skew * bump * ramp;
    }

    // Mutation M: lookahead-aware new-bin arbitration.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let open_can_chain = fitting_bins_count > 0
            && mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        let new_can_chain = new_post >= nxt;
        if open_can_chain && !new_can_chain {
            score += 5.0 + 3.0 * (1.0 - progress);
        } else if !open_can_chain && new_can_chain {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Mutation N: utilization-maximizing tiebreak.
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Mutation O: two-step closure ladder.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 {
            let closeness = 1.0 - (after / cap).min(1.0);
            score -= 3.0 * closeness * closeness * (0.6 + 0.8 * progress);
        }
    }

    // Mutation P: fleet-aware dead-space cap.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Mutation T (refined gen 26): dead-space bump sharpened toward 0.30 of
    // capacity with stronger late-stream scaling.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak2 = 0.30;
        let skew2 = if x < peak2 { 0.6 } else { 1.7 };
        let bump2 = (x - peak2) * (x - peak2);
        score += 6.0 * skew2 * bump2 * (1.0 + 1.4 * progress);
    }

    // Mutation U: exact-closure ladder — reward small closable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 15 {
            score -= 2.0 * (1.0 - after as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
    }

    // Mutation V: new-bin exact-chain gate.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if (new_post - nxt).abs() < 1.0 {
            score -= 4.0 * (1.0 - progress);
        } else if new_post < nxt && progress > 0.5 {
            score += 2.5 * (progress - 0.5) / 0.5;
        }
    }

    // Mutation W (gen 26): dead-space ratio diagnostic — convex penalty for
    // post-lookahead leftover fraction exceeding the fleet mean.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.05 {
            score += 4.5 * (excess_frac - 0.05) * (excess_frac - 0.05) / (excess_frac + 0.05) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation X (gen 26): complementarity bonus — reward leftovers whose sum
    // with the fleet mean is jointly fillable by mid-size items.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_sum = after + mean;
        let pair_frac = pair_sum / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation Y (gen 26): lookahead-fit calibration — escalate exact-fill
    // reward late in the stream where closure value is highest.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation Z (gen 26): waste-shape guard — penalize the awkward middle
    // band 16..=29 of leftovers that are neither closable nor reusable.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AA (gen 29): sharpen the dead-space bump peak toward 0.26 of
    // capacity with progress-adaptive skew.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak3 = 0.26;
        let skew3 = if x < peak3 { 0.55 } else { 1.9 };
        let bump3 = (x - peak3) * (x - peak3);
        score += 5.0 * skew3 * bump3 * (0.8 + 1.6 * progress);
    }

    // Mutation AB (gen 29): fleet-mean residual-shape alignment.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let dev = (after - mean) / cap;
        if dev < 0.0 {
            score -= 1.4 * (-dev) * (1.0 - 0.5 * progress);
        } else {
            score += 0.7 * dev * dev * cap.min(100.0) / 10.0;
        }
    }

    // Mutation AC (gen 29): lookahead-complement pairing — three-item chain.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let diff = (after as f64 - item_size as f64).abs();
        if diff <= 6.0 && after > 0 {
            score -= (2.2 - diff * 0.25) * (0.5 + 0.9 * progress);
        }
    }

    // Mutation AD (gen 29): new-bin dead-space preemption.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let after_new = new_post - nxt;
        if after_new >= 16.0 && after_new <= 34.0 {
            score += 2.5 * (1.0 - (after_new - 16.0) / 18.0) * (0.4 + 0.8 * progress);
        } else if after_new > 0.0 && after_new < 8.0 {
            score -= 1.5 * (1.0 - progress);
        }
    }

    // Mutation AE (gen 29): residual-variance dampener.
    if !is_new_bin && mean > 0.0 {
        let spread = (mean / cap - 0.25).abs();
        if spread > 0.10 {
            let snug2 = (bin_residual - item_size) as f64;
            if snug2 >= 0.0 && snug2 < 10.0 {
                score -= 1.1 * spread * (1.0 - snug2 / 10.0) * (0.6 + 0.6 * progress);
            }
        }
    }

    // Mutation AF (gen 30, Combine): dual-channel dead-space compaction —
    // merge the fine-grained snugness preference with lookahead anticipation
    // by rewarding bins where the item lands snugly AND the leftover after
    // the next item stays either closable (<=12) or exactly refillable by
    // the current item class, targeting the diagnosed dead-space weakness.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let snug_here = (bin_residual - item_size) as f64;
        let after = post_residual - next_item_size;
        if snug_here < 8.0 {
            let snug_term = 1.6 * (1.0 - snug_here / 8.0);
            if after <= 12 {
                score -= snug_term * (0.8 + 0.8 * progress);
            } else if after as i64 == item_size as i64 {
                score -= snug_term * 0.9;
            }
        }
        // Penalize snug fits that strand a mid-band leftover (13..=24):
        // they look good locally but waste space at the two-step horizon.
        if snug_here < 8.0 && after >= 13 && after <= 24 {
            score += 1.4 * (1.0 - snug_here / 8.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AG (gen 30): horizon-dead-space integral — penalize the
    // average of the post-item leftover and the two-step leftover scaled by
    // the fleet mean, so bins are chosen by their expected residual mass
    // over the lookahead horizon rather than a single step.
    if !is_new_bin && nxt > 0.0 && mean > 0.0 {
        let after = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            post
        };
        let horizon = 0.5 * (post + after);
        let excess = horizon - mean;
        if excess > 0.0 {
            score += 1.6 * excess * (0.6 + 0.6 * progress) / cap.max(1.0) * cap.min(50.0);
        } else {
            score -= 0.5 * (-excess) / cap.max(1.0) * cap.min(50.0);
        }
    }

    // Mutation AH (gen 30): new-bin horizon gate — open a fresh bin only if
    // its two-step horizon residual beats the fleet mean horizon; otherwise
    // prefer consolidating into open bins.
    if is_new_bin && nxt > 0.0 && mean > 0.0 {
        let new_post = cap - item_size as f64;
        let new_after = if new_post >= nxt { new_post - nxt } else { new_post };
        let new_horizon = 0.5 * (new_post + new_after);
        if new_horizon > mean + 4.0 {
            score += 3.0 * (0.5 + 0.7 * progress);
        } else if new_horizon < mean - 4.0 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Base: two-step waste — leftover after ideally seating the lookahead item too.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Perfect closure / small leftovers.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score += 14.0 + 3.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 5.0;
    } else {
        let post_class = (post_residual * 10 + bin_capacity / 2) / bin_capacity;
        if post_class >= 7 {
            score -= 4.0;
        }
    }

    // Aggressive exact two-step match.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 25.0 + 8.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 10.0;
        } else if slack < 20 {
            score -= 4.0;
        }
    } else if nxt > 0.0 && post > 0.0 && post < nxt {
        // Dead-space risk, graded by wasted fraction.
        let waste_frac = (nxt - post) / nxt;
        score += 0.5 * (nxt - post).min(cap)
            + 6.0
            + 3.0 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.0 * waste_frac * (1.0 - progress);
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Void fraction, graded harder for large voids.
    let void_frac = post / resid;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.5 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 18.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 2.5;
    }

    // New-bin candidate arbitration.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 10.0 + 4.0 * progress;
        } else if pressure < 0.45 {
            score += 2.0 + 4.0 * progress;
        } else {
            score += 10.0 + 6.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
        if progress > 0.85 {
            score += 6.0 * (progress - 0.85) / 0.15;
        }
        // Lookahead-aware opening gate.
        if nxt > 0.0 {
            let new_post = cap - item_size as f64;
            let open_can_chain = fitting_bins_count > 0
                && mean >= item_size as f64
                && (mean - item_size as f64) >= nxt;
            let new_can_chain = new_post >= nxt;
            if open_can_chain && !new_can_chain {
                score += 5.0 + 3.0 * (1.0 - progress);
            } else if !open_can_chain && new_can_chain {
                score -= 2.0 * (1.0 - progress);
            }
            if (new_post - nxt).abs() < 1.0 {
                score -= 4.0 * (1.0 - progress);
            } else if new_post < nxt && progress > 0.5 {
                score += 2.5 * (progress - 0.5) / 0.5;
            }
        }
        // Fragmentation hedge with many open bins.
        if open_bins_count > 8 {
            let frag = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
            score += 0.9 * frag * (0.4 + 0.6 * progress);
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.15;

    // Chain closure.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 2.5 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.5;
    }

    // Progress-adaptive snugness.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        let band = 20.0 - 10.0 * progress;
        if snug < band {
            score -= 1.8 * (1.0 - snug / band) * (0.5 + progress);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
        // Two-deep chain reward.
        if second_left as f64 == nxt || second_left as f64 == item_size as f64 {
            score -= 3.5 + 2.5 * (1.0 - progress);
        } else if (second_left as f64) >= nxt.min(item_size as f64) && second_left < 2 * next_item_size {
            score -= 1.0 * (1.0 - 0.5 * progress);
        }
        // Exact-closure ladder: leftover closable by a typical small item.
        if second_left > 0 && second_left <= 15 {
            score -= 2.0 * (1.0 - second_left as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
        // Anti-fragmentation sweep on large usable leftovers.
        if second_left > 25 {
            score += 0.06 * (second_left as f64 - 25.0);
        }
    }

    // Dead-space ratio penalty vs fleet-average leftover fraction.
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let post_frac = post / cap;
        let mean_frac = (mean / cap).min(1.0);
        if post_frac > mean_frac {
            score += 3.5 * (post_frac - mean_frac) * (1.0 - 0.4 * progress);
        } else {
            score -= 1.2 * (mean_frac - post_frac);
        }
    }

    // Reusable-void valuation.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // Sharpened dead-space hedge for near-miss lookahead.
    if nxt > 0.0 && !is_new_bin && post_residual < next_item_size && progress > 0.1 {
        let unusable = (next_item_size - post_residual) as f64;
        if unusable <= 15.0 {
            score += (2.5 - unusable * 0.15) * (1.0 + 0.5 * progress);
        } else {
            score += 0.75 * unusable * (1.0 - progress);
        }
    }

    // Residual homogeneity bonus.
    if !is_new_bin && mean > 0.0 {
        let hom = ((post - mean).abs() / cap) as f64;
        score -= 0.8 * (1.0 - hom.min(1.0));
    }

    // Asymmetric dead-space bump on post-lookahead leftover fraction.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.32;
        let skew = if x < peak { 0.6 } else { 1.5 };
        let bump = (x - peak) * (x - peak);
        score += 10.0 * skew * bump * (1.0 + progress);
    }

    // Fleet-aware dead-space cap.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Refillability-weighted leftover valuation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // --- Gen-31 combined mutation A: snug-lookahead coupling ---
    // Combine fine-grained residual fitting with lookahead anticipation:
    // reward bins whose snug fit also leaves a residual that exactly
    // chains into the next item (joint two-condition bonus).
    if !is_new_bin && nxt > 0.0 && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        if snug <= 8.0 && post_residual == next_item_size {
            score -= 4.0 * (1.0 - snug / 8.0) * (0.7 + 0.6 * progress);
        } else if snug <= 4.0 && post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            if after <= 10.0 {
                score -= 2.0 * (1.0 - after / 10.0) * (0.5 + progress);
            }
        }
    }

    // --- Gen-31 mutation B: convex excess-fraction penalty vs fleet mean ---
    // Target the diagnosed dead-space-ratio weakness: bins whose
    // post-lookahead leftover exceeds the fleet mean by a convex margin.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.05 {
            score += 4.5 * (excess_frac - 0.05) * (excess_frac - 0.05) / (excess_frac + 0.05) * (0.7 + 0.6 * progress);
        }
    }

    // --- Gen-31 mutation C: complementarity bonus ---
    // Reward bins whose post-lookahead leftover pairs with the fleet mean
    // residual into a jointly fillable whole.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_frac = (after + mean) / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // --- Gen-31 mutation D: waste-shape guard on the awkward middle band ---
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // --- Gen-31 mutation E: late-stream exact-closure escalation ---
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps below the minimum item size are unusable "dead space": penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small-but-usable gaps are risky too: soft penalty scaled by tightness.
    if post_residual < 20 {
        score += 15.0 * (20.0 - post_residual as f64) / 20.0;
    }

    // Reward very tight fits (perfect packing) strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Penalize wasting a mostly-empty bin on a small item (large leftover after small item).
    if item_size < 30 && post_residual > 60 {
        score += 25.0;
    }

    // --- Open bins pressure ---
    // Encourage consolidating into existing bins as the number of open bins grows.
    let pressure = (open_bins_count as f64).ln().max(1.0) * 4.0;
    score -= pressure * (item_size as f64 / bin_capacity as f64);

    // --- Last-chance bonus ---
    // If this is the only bin that fits, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // --- Lookahead coupling ---
    // If the next item could fit in the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive for large items or when no good fit exists.
        if item_size >= 50 {
            score += 10.0; // mildly discourage: try existing bins first
        } else {
            score += 30.0 + 0.5 * mean_residual; // discourage strongly for small items
        }
        // Late in the stream, slightly prefer new bins to keep clean residual space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Two-step waste base.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Aggressive exact two-step match.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 12.0 + 6.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 5.0;
        } else if slack < 20 {
            score -= 2.0;
        }
    }

    // Perfect closure / small leftovers.
    if post_residual == 0 {
        score -= 24.0;
    } else if post_residual < 10 {
        score += 9.0 + 2.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Dead-space risk: quadratic waste penalty scaled by wasted fraction.
    if nxt > 0.0 && post > 0.0 && post < nxt {
        let waste_frac = (nxt - post) / nxt;
        score += 0.5 * (nxt - post).min(cap)
            + 4.0
            + 3.0 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.0 * waste_frac * (1.0 - progress);
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Void fraction, graded harder for large voids.
    let void_frac = post / resid;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.5 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 8.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 1.5;
    }

    // Opening cost for a brand-new bin.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 6.0 + 3.0 * progress;
        } else if pressure < 0.45 {
            score += 1.0 + 3.0 * progress;
        } else {
            score += 8.0 + 5.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.05;

    // Chain closure: residual exactly matches next item size.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 2.5 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.0;
    }

    // Endgame tightening.
    if progress > 0.85 && is_new_bin {
        score += 6.0 * (progress - 0.85) / 0.15;
    }

    // Snug fit, graded.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        if snug < 5.0 {
            score -= 2.5;
        }
        if snug < 15.0 {
            score -= 1.0 * (1.0 - snug / 15.0);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
    }

    // Dead-space ratio penalty, graded.
    if post > mean && cap > 0.0 {
        let excess_ratio = (post - mean) / cap;
        if excess_ratio > 0.15 {
            score += 2.0 * excess_ratio + 4.0 * (excess_ratio - 0.15);
        }
    }

    // Reusable-void check.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin via residual tiebreak.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // New-bin gate: open a fresh bin only when fits elsewhere are poor.
    if is_new_bin && nxt > 0.0 {
        let fits_poorly = fitting_bins_count > 0 && (bin_capacity as f64 - mean) > item_size as f64 * 1.5;
        if fits_poorly {
            score -= 3.0;
        }
    }

    // Depth-2 lookahead: small residual matching a future item class.
    if nxt > 0.0 && post_residual >= next_item_size {
        let two_left = post_residual - next_item_size;
        if two_left > 0 && two_left <= 10 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Exact-fit chain: post residual equals next item size with a small item.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size && next_item_size <= item_size {
        score -= 3.0 * (1.0 - progress);
    }

    // Mutation F: lookahead-aware dead-space hedge (sharpened weight).
    if nxt > 0.0 && !is_new_bin && post_residual < next_item_size && progress > 0.1 {
        let unusable = (next_item_size - post_residual) as f64;
        score += 0.75 * unusable * (1.0 - progress);
    }

    // Mutation G: residual homogeneity.
    if !is_new_bin && mean > 0.0 {
        let hom = ((post - mean).abs() / cap) as f64;
        score -= 0.8 * (1.0 - hom.min(1.0));
    }

    // Mutation H: dead-space ratio refinement vs fleet-average leftover fraction.
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let post_frac = post / cap;
        let mean_frac = (mean / cap).min(1.0);
        if post_frac > mean_frac {
            score += 3.5 * (post_frac - mean_frac) * (1.0 - 0.4 * progress);
        } else {
            score -= 1.2 * (mean_frac - post_frac);
        }
    }

    // Mutation I: anti-fragmentation sweep on large usable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let usable_left = post_residual - next_item_size;
        if usable_left > 25 {
            score += 0.06 * (usable_left as f64 - 25.0);
        }
    }

    // Mutation J: refillability-weighted leftover valuation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Mutation K: convex shortfall penalty for near-miss lookahead.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 15.0 {
            score += (2.5 - shortfall * 0.15) * (1.0 + 0.5 * progress);
        }
    }

    // Mutation L: asymmetric quadratic dead-space bump (peak 0.38 of capacity).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.38;
        let skew = if x < peak { 0.7 } else { 1.45 };
        let bump = (x - peak) * (x - peak);
        let ramp = if progress > 0.25 { 1.0 + 0.6 * (progress - 0.25) } else { 0.85 + 0.6 * progress };
        score += 15.0 * skew * bump * ramp;
    }

    // Mutation M: lookahead-aware new-bin arbitration.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let open_can_chain = fitting_bins_count > 0
            && mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        let new_can_chain = new_post >= nxt;
        if open_can_chain && !new_can_chain {
            score += 5.0 + 3.0 * (1.0 - progress);
        } else if !open_can_chain && new_can_chain {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Mutation N: utilization-maximizing tiebreak.
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Mutation O: two-step closure ladder.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 {
            let closeness = 1.0 - (after / cap).min(1.0);
            score -= 3.0 * closeness * closeness * (0.6 + 0.8 * progress);
        }
    }

    // Mutation P: fleet-aware dead-space cap.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Mutation Q: two-deep chain reward + mid-band dead-space penalty.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 == nxt || after as f64 == item_size as f64 {
            score -= 3.5 + 2.5 * (1.0 - progress);
        } else if (after as f64) >= nxt.min(item_size as f64) && after < 2 * next_item_size {
            score -= 1.0 * (1.0 - 0.5 * progress);
        }
        if after >= 30 && after <= 60 && progress > 0.3 {
            score += 1.8 * (progress - 0.3) / 0.7;
        }
    }

    // Mutation R: progress-adaptive snugness.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        let band = 20.0 - 10.0 * progress;
        if snug < band {
            score -= 1.6 * (1.0 - snug / band) * (0.5 + progress);
        }
    }

    // Mutation S: new-bin saturation hedge.
    if is_new_bin && open_bins_count > 8 {
        let frag = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
        score += 0.9 * frag * (0.4 + 0.6 * progress);
    }

    // Mutation T: sharpened dead-space bump peak at 0.30 of capacity,
    // with stronger late-stream scaling and fleet-mean coupling — the
    // diagnosed suboptimal-residual weakness is most visible when the
    // leftover after lookahead drifts well above the fleet mean.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak2 = 0.30;
        let skew2 = if x < peak2 { 0.6 } else { 1.7 };
        let bump2 = (x - peak2) * (x - peak2);
        let mean_pull = ((after - mean) / cap).max(0.0);
        score += 6.0 * skew2 * bump2 * (1.0 + 1.4 * progress)
            + 2.5 * mean_pull * mean_pull * (0.5 + progress);
    }

    // Mutation U: exact-closure ladder — reward small closable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 15 {
            score -= 2.0 * (1.0 - after as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
    }

    // Mutation V: new-bin exact-chain gate.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if (new_post - nxt).abs() < 1.0 {
            score -= 4.0 * (1.0 - progress);
        } else if new_post < nxt && progress > 0.5 {
            score += 2.5 * (progress - 0.5) / 0.5;
        }
    }

    // Mutation W: dead-space ratio diagnostic — convex penalty when the
    // post-lookahead leftover fraction exceeds the fleet mean.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.05 {
            score += 4.5 * (excess_frac - 0.05) * (excess_frac - 0.05) / (excess_frac + 0.05) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation X: complementarity bonus — reward leftovers that pair with
    // the fleet mean into a jointly fillable whole.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_sum = after + mean;
        let pair_frac = pair_sum / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation Y: lookahead-fit calibration — escalate exact-fill reward late.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation Z: waste-shape guard — penalize the awkward middle band 16..=29.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AA (gen 31): residual-band compaction — bins whose post-fit
    // leftover falls in the "closable" band (1..=next_item_size) get a
    // progressive reward, steering choices toward leftovers the stream can
    // still close out rather than strand.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && (after as f64) <= nxt {
            score -= 2.2 * (1.0 - after as f64 / nxt.max(1.0)) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation AB (gen 31): dual-lookahead exactness — when the next item
    // closes the bin AND the current item nearly closes the residual
    // (residual - item <= 5), stack an extra reward to force tight packing.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        let snug2 = (bin_residual - item_size) as f64;
        if snug2 >= 0.0 && snug2 <= 5.0 {
            score -= 3.0 * (1.0 - 0.5 * progress);
        }
    }

    // Mutation AC (gen 31): new-bin waste floor — a fresh bin's guaranteed
    // leftover (cap - item) is compared against the fleet mean; opening a
    // bin whose guaranteed leftover is much larger than what existing bins
    // would leave is penalized progressively.
    if is_new_bin && mean > 0.0 && nxt > 0.0 {
        let new_left = cap - item_size as f64;
        let excess = (new_left - mean).max(0.0) / cap;
        if excess > 0.1 {
            score += 3.0 * (excess - 0.1) * (1.0 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual is good).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0; // perfect chain: bin will be fully closed after next item
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Partial match: reward proportionally, penalize leftover dead space after next item.
        let after_next = post_residual - next_item_size;
        score -= 20.0 * (1.0 - (after_next as f64) / (bin_capacity as f64));
        score += 0.3 * after_next as f64;
    } else if next_item_size > post_residual {
        // Next item won't fit here: penalize leaving a gap sized just above tiny-item range.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0; // unusable dead space
        }
    }

    // Penalize post_residual that is large but too small for typical items (dead zone).
    if post_residual > 0 && post_residual < 20 {
        score += 12.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Compare against mean residual: prefer bins with below-average residual (tighter bins).
    score += 0.5 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else {
        // Mild penalty when many bins compete (encourage spreading across fullness levels).
        score += 0.15 * (fitting_bins_count as f64);
    }

    // Early in stream: be more willing to open new bins (keep flexibility),
    // late in stream: prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, reduced early, increased late.
        score = score.max(0.0) * 0.0 + 30.0 - 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // new bin can chain with next item
        }
    } else {
        score -= 8.0 * progress; // late stream: reward reusing open bins
    }

    // Penalize very full open bins count growth pressure mildly.
    score += 0.05 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Base: two-step waste — leftover after ideally seating the lookahead item too.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Perfect closure / small leftovers (sharpened early-stream).
    if post_residual == 0 {
        score -= 42.0;
    } else if post_residual < 10 {
        score += 15.0 + 3.5 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 5.5;
    } else {
        let post_class = (post_residual * 10 + bin_capacity / 2) / bin_capacity;
        if post_class >= 7 {
            score -= 4.0;
        }
    }

    // Aggressive exact two-step match.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 27.0 + 8.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 11.0;
        } else if slack < 20 {
            score -= 4.5;
        }
    } else if nxt > 0.0 && post > 0.0 && post < nxt {
        let waste_frac = (nxt - post) / nxt;
        score += 0.6 * (nxt - post).min(cap)
            + 7.0
            + 3.5 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.5 * waste_frac * (1.0 - progress);
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Void fraction, graded harder for large voids.
    let void_frac = post / resid;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.8 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 18.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 2.5;
    }

    // New-bin candidate arbitration.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 10.0 + 4.0 * progress;
        } else if pressure < 0.45 {
            score += 2.0 + 4.0 * progress;
        } else {
            score += 10.0 + 6.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
        if progress > 0.85 {
            score += 6.0 * (progress - 0.85) / 0.15;
        }
        // Lookahead-aware opening gate.
        if nxt > 0.0 {
            let new_post = cap - item_size as f64;
            let open_can_chain = fitting_bins_count > 0
                && mean >= item_size as f64
                && (mean - item_size as f64) >= nxt;
            let new_can_chain = new_post >= nxt;
            if open_can_chain && !new_can_chain {
                score += 5.0 + 3.0 * (1.0 - progress);
            } else if !open_can_chain && new_can_chain {
                score -= 2.5 * (1.0 - progress);
            }
            if (new_post - nxt).abs() < 1.0 {
                score -= 4.0 * (1.0 - progress);
            } else if new_post < nxt && progress > 0.5 {
                score += 2.5 * (progress - 0.5) / 0.5;
            }
        }
        if open_bins_count > 8 {
            let frag = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
            score += 0.9 * frag * (0.4 + 0.6 * progress);
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.15;

    // Chain closure.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 3.0 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.5;
    }

    // Progress-adaptive snugness.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        let band = 20.0 - 10.0 * progress;
        if snug < band {
            score -= 1.8 * (1.0 - snug / band) * (0.5 + progress);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
        if second_left as f64 == nxt || second_left as f64 == item_size as f64 {
            score -= 3.5 + 2.5 * (1.0 - progress);
        } else if (second_left as f64) >= nxt.min(item_size as f64) && second_left < 2 * next_item_size {
            score -= 1.0 * (1.0 - 0.5 * progress);
        }
        if second_left > 0 && second_left <= 15 {
            score -= 2.2 * (1.0 - second_left as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
        if second_left > 25 {
            score += 0.06 * (second_left as f64 - 25.0);
        }
    }

    // Dead-space ratio penalty vs fleet-average leftover fraction.
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let post_frac = post / cap;
        let mean_frac = (mean / cap).min(1.0);
        if post_frac > mean_frac {
            score += 4.0 * (post_frac - mean_frac) * (1.0 - 0.4 * progress);
        } else {
            score -= 1.2 * (mean_frac - post_frac);
        }
    }

    // Reusable-void valuation.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // Sharpened dead-space hedge for near-miss lookahead.
    if nxt > 0.0 && !is_new_bin && post_residual < next_item_size && progress > 0.1 {
        let unusable = (next_item_size - post_residual) as f64;
        if unusable <= 15.0 {
            score += (2.5 - unusable * 0.15) * (1.0 + 0.5 * progress);
        } else {
            score += 0.75 * unusable * (1.0 - progress);
        }
    }

    // Residual homogeneity bonus.
    if !is_new_bin && mean > 0.0 {
        let hom = ((post - mean).abs() / cap) as f64;
        score -= 0.8 * (1.0 - hom.min(1.0));
    }

    // Asymmetric dead-space bump on post-lookahead leftover fraction.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.30;
        let skew = if x < peak { 0.6 } else { 1.6 };
        let bump = (x - peak) * (x - peak);
        score += 9.0 * skew * bump * (1.0 + 1.2 * progress);
    }

    // Fleet-aware dead-space cap.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Refillability-weighted leftover valuation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Mid-band dead-space penalty on post-lookahead leftover (30-60 range).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 30 && after <= 60 && progress > 0.3 {
            score += 1.8 * (progress - 0.3) / 0.7;
        }
    }

    // Two-step closure ladder — reward small closable leftovers harder.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 {
            let closeness = 1.0 - (after / cap).min(1.0);
            score -= 3.0 * closeness * closeness * (0.6 + 0.8 * progress);
        }
    }

    // Mutation A (gen 30): convex excess-fraction penalty vs fleet mean.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.05 {
            score += 4.5 * (excess_frac - 0.05) * (excess_frac - 0.05) / (excess_frac + 0.05) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation B (gen 30): complementarity bonus.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_frac = (after + mean) / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation C (gen 30): awkward-middle-band guard (16..=29 leftovers).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation D (gen 30): late-stream exact-fill escalation.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation E (gen 30): dual-threshold new-bin gate.
    if is_new_bin && nxt > 0.0 && fitting_bins_count > 0 {
        let best_chain_possible = mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        if !best_chain_possible && open_bins_count as f64 * (mean / cap) > 2.5 {
            score -= 1.5 * (1.0 - progress);
        }
    }

    // Mutation F (gen 31): triple-fill anticipation — when the post-lookahead
    // leftover can still host the fleet-mean item class, reward compaction
    // that keeps a chain of three seats alive instead of just two.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let mean_item = (cap - mean).max(1.0);
        if after >= mean_item {
            let third_left = after - mean_item;
            if third_left <= 12.0 {
                score -= 2.4 * (1.0 - third_left / 12.0) * (0.5 + 0.9 * progress);
            } else if third_left as u32 % 5 == 0 {
                score -= 1.0 * (1.0 - 0.4 * progress);
            }
        }
    }

    // Mutation G (gen 31): wasted-capacity ratio guard — penalize bins whose
    // post-lookahead leftover exceeds a quarter of capacity unless it remains
    // jointly fillable with the fleet mean (dead-space reduction).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let frac = after / cap;
        if frac > 0.25 && (after + mean) < cap {
            score += 3.5 * (frac - 0.25) * (0.6 + 0.8 * progress);
        }
    }

    // Mutation H (gen 31): new-bin tightening — require a clearly better chain
    // than the best open bin before opening a fresh bin mid/late stream.
    if is_new_bin && nxt > 0.0 && fitting_bins_count > 0 && progress > 0.3 {
        let new_post = cap - item_size as f64;
        if new_post >= nxt {
            let new_left = new_post - nxt;
            let open_left = (mean - item_size as f64).max(0.0) - nxt;
            if new_left > open_left + 3.0 {
                score += 2.0 * (1.0 + progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: mild penalty so it's chosen only when open bins are bad.
    if bin_residual == bin_capacity {
        score += 0.35 * bin_capacity as f64
            + 0.15 * mean_residual
            - 3.0 * (fitting_bins_count as f64);
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 8.0 * progress;
        return score;
    }

    // Reward tight fits (small post_residual) non-linearly.
    score -= 12.0 / (1.0 + post_residual as f64);

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0) as f64;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer filling
    // bins below mean residual (reduce fragmentation).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    // Time horizon: early on, keep bins balanced; late, just pack tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * (1.0 - progress) * ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Base: two-step waste — leftover after ideally seating the lookahead item too.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Aggressive exact two-step match.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 12.0 + 6.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 5.0;
        } else if slack < 20 {
            score -= 2.0;
        }
    }

    // Perfect closure / small leftovers.
    if post_residual == 0 {
        score -= 24.0;
    } else if post_residual < 10 {
        score += 9.0 + 2.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Dead-space risk: quadratic waste penalty scaled by wasted fraction.
    if nxt > 0.0 && post > 0.0 && post < nxt {
        let waste_frac = (nxt - post) / nxt;
        score += 0.5 * (nxt - post).min(cap)
            + 4.0
            + 3.0 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.0 * waste_frac * (1.0 - progress);
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Void fraction, graded harder for large voids.
    let void_frac = post / resid;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.5 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 8.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 1.5;
    }

    // Opening cost for a brand-new bin.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 6.0 + 3.0 * progress;
        } else if pressure < 0.45 {
            score += 1.0 + 3.0 * progress;
        } else {
            score += 8.0 + 5.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.05;

    // Chain closure: residual exactly matches next item size.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 2.5 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.0;
    }

    // Endgame tightening.
    if progress > 0.85 && is_new_bin {
        score += 6.0 * (progress - 0.85) / 0.15;
    }

    // Snug fit, graded.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        if snug < 5.0 {
            score -= 2.5;
        }
        if snug < 15.0 {
            score -= 1.0 * (1.0 - snug / 15.0);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
    }

    // Dead-space ratio penalty, graded.
    if post > mean && cap > 0.0 {
        let excess_ratio = (post - mean) / cap;
        if excess_ratio > 0.15 {
            score += 2.0 * excess_ratio + 4.0 * (excess_ratio - 0.15);
        }
    }

    // Reusable-void check.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin via residual tiebreak.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // New-bin gate: open a fresh bin only when fits elsewhere are poor.
    if is_new_bin && nxt > 0.0 {
        let fits_poorly = fitting_bins_count > 0 && (bin_capacity as f64 - mean) > item_size as f64 * 1.5;
        if fits_poorly {
            score -= 3.0;
        }
    }

    // Depth-2 lookahead: small residual matching a future item class.
    if nxt > 0.0 && post_residual >= next_item_size {
        let two_left = post_residual - next_item_size;
        if two_left > 0 && two_left <= 10 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Exact-fit chain: post residual equals next item size with a small item.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size && next_item_size <= item_size {
        score -= 3.0 * (1.0 - progress);
    }

    // Mutation F: lookahead-aware dead-space hedge (sharpened weight).
    if nxt > 0.0 && !is_new_bin && post_residual < next_item_size && progress > 0.1 {
        let unusable = (next_item_size - post_residual) as f64;
        score += 0.75 * unusable * (1.0 - progress);
    }

    // Mutation G: residual homogeneity.
    if !is_new_bin && mean > 0.0 {
        let hom = ((post - mean).abs() / cap) as f64;
        score -= 0.8 * (1.0 - hom.min(1.0));
    }

    // Mutation H: dead-space ratio refinement vs fleet-average leftover fraction.
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let post_frac = post / cap;
        let mean_frac = (mean / cap).min(1.0);
        if post_frac > mean_frac {
            score += 3.5 * (post_frac - mean_frac) * (1.0 - 0.4 * progress);
        } else {
            score -= 1.2 * (mean_frac - post_frac);
        }
    }

    // Mutation I: anti-fragmentation sweep on large usable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let usable_left = post_residual - next_item_size;
        if usable_left > 25 {
            score += 0.06 * (usable_left as f64 - 25.0);
        }
    }

    // Mutation J: refillability-weighted leftover valuation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Mutation K: convex shortfall penalty for near-miss lookahead.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 15.0 {
            score += (2.5 - shortfall * 0.15) * (1.0 + 0.5 * progress);
        }
    }

    // Mutation L: asymmetric quadratic dead-space bump (peak 0.38 of capacity).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.38;
        let skew = if x < peak { 0.7 } else { 1.45 };
        let bump = (x - peak) * (x - peak);
        let ramp = if progress > 0.25 { 1.0 + 0.6 * (progress - 0.25) } else { 0.85 + 0.6 * progress };
        score += 15.0 * skew * bump * ramp;
    }

    // Mutation M: lookahead-aware new-bin arbitration.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let open_can_chain = fitting_bins_count > 0
            && mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        let new_can_chain = new_post >= nxt;
        if open_can_chain && !new_can_chain {
            score += 5.0 + 3.0 * (1.0 - progress);
        } else if !open_can_chain && new_can_chain {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Mutation N: utilization-maximizing tiebreak.
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Mutation O: two-step closure ladder.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 {
            let closeness = 1.0 - (after / cap).min(1.0);
            score -= 3.0 * closeness * closeness * (0.6 + 0.8 * progress);
        }
    }

    // Mutation P: fleet-aware dead-space cap.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Mutation T (refined gen 26): dead-space bump sharpened toward 0.30 of
    // capacity with stronger late-stream scaling.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak2 = 0.30;
        let skew2 = if x < peak2 { 0.6 } else { 1.7 };
        let bump2 = (x - peak2) * (x - peak2);
        score += 6.0 * skew2 * bump2 * (1.0 + 1.4 * progress);
    }

    // Mutation U: exact-closure ladder — reward small closable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 15 {
            score -= 2.0 * (1.0 - after as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
    }

    // Mutation V: new-bin exact-chain gate.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if (new_post - nxt).abs() < 1.0 {
            score -= 4.0 * (1.0 - progress);
        } else if new_post < nxt && progress > 0.5 {
            score += 2.5 * (progress - 0.5) / 0.5;
        }
    }

    // Mutation W (gen 26): dead-space ratio diagnostic — convex penalty for
    // post-lookahead leftover fraction exceeding the fleet mean.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.05 {
            score += 4.5 * (excess_frac - 0.05) * (excess_frac - 0.05) / (excess_frac + 0.05) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation X (gen 26): complementarity bonus — reward leftovers whose sum
    // with the fleet mean is jointly fillable by mid-size items.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_sum = after + mean;
        let pair_frac = pair_sum / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation Y (gen 26): lookahead-fit calibration — escalate exact-fill
    // reward late in the stream where closure value is highest.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation Z (gen 26): waste-shape guard — penalize the awkward middle
    // band 16..=29 of leftovers that are neither closable nor reusable.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AA (gen 29): sharpen the dead-space bump peak toward 0.26 of
    // capacity with progress-adaptive skew.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak3 = 0.26;
        let skew3 = if x < peak3 { 0.55 } else { 1.9 };
        let bump3 = (x - peak3) * (x - peak3);
        score += 5.0 * skew3 * bump3 * (0.8 + 1.6 * progress);
    }

    // Mutation AB (gen 29): fleet-mean residual-shape alignment.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let dev = (after - mean) / cap;
        if dev < 0.0 {
            score -= 1.4 * (-dev) * (1.0 - 0.5 * progress);
        } else {
            score += 0.7 * dev * dev * cap.min(100.0) / 10.0;
        }
    }

    // Mutation AC (gen 29): lookahead-complement pairing — chainable three-item bins.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let diff = (after as f64 - item_size as f64).abs();
        if diff <= 6.0 && after > 0 {
            score -= (2.2 - diff * 0.25) * (0.5 + 0.9 * progress);
        }
    }

    // Mutation AD (gen 29): new-bin dead-space preemption.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let after_new = new_post - nxt;
        if after_new >= 16.0 && after_new <= 34.0 {
            score += 2.5 * (1.0 - (after_new - 16.0) / 18.0) * (0.4 + 0.8 * progress);
        } else if after_new > 0.0 && after_new < 8.0 {
            score -= 1.5 * (1.0 - progress);
        }
    }

    // Mutation AE (gen 29): residual-variance dampener.
    if !is_new_bin && mean > 0.0 {
        let spread = (mean / cap - 0.25).abs();
        if spread > 0.10 {
            let snug2 = (bin_residual - item_size) as f64;
            if snug2 >= 0.0 && snug2 < 10.0 {
                score -= 1.1 * spread * (1.0 - snug2 / 10.0) * (0.6 + 0.6 * progress);
            }
        }
    }

    // Mutation AF (gen 31, Combine): fine-grained residual fitting fused with
    // lookahead anticipation — reward bins whose post-lookahead leftover is
    // exactly refilled by a plausible future item class (item_size or nxt),
    // with weight scaled by how tight the current fit already is. This fuses
    // the snugness signal with the two-step lookahead into one coupling.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let snug_now = (bin_residual - item_size) as f64;
        let tightness = (1.0 - (snug_now / cap).min(1.0)).max(0.0);
        if after as f64 == item_size as f64 {
            score -= (3.0 + 2.5 * progress) * (0.5 + tightness);
        } else if after as f64 == nxt {
            score -= (2.5 + 2.0 * progress) * (0.5 + tightness);
        } else if after > 0 && (after as f64 - item_size as f64).abs() <= 3.0 {
            score -= 1.8 * (0.4 + tightness) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation AG (gen 31): dead-space deadband refinement — the diagnosed
    // weakness is residual/dead-space ratio; replace the blunt base waste
    // penalty's flat region with a graded one that distinguishes near-miss
    // dead space (refillable by small items) from truly stranded space.
    if nxt > 0.0 && !is_new_bin && post > 0.0 && post < nxt {
        let gap = nxt - post;
        if gap <= 8.0 {
            // Small gap: likely fillable by a future small item — mild penalty.
            score -= 1.2 * (1.0 - gap / 8.0) * (1.0 - progress);
        } else if gap >= 30.0 {
            // Large stranded gap: strong penalty, escalating with progress.
            score += 1.5 * (gap - 30.0).min(cap) / 10.0 * (0.6 + 0.8 * progress);
        }
    }

    // Mutation AH (gen 31): lookahead-consolidation arbitration — when the
    // next item exactly closes this bin (post_residual == 0 is impossible
    // here since post >= nxt path), prefer bins where the two-step leftover
    // is minimal relative to the fleet: sharp reward for the tightest
    // two-step leftover among fitting bins, mild penalty otherwise.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && fitting_bins_count > 1 {
        let after = (post_residual - next_item_size) as f64;
        let fleet_two_step = (mean - nxt).max(0.0);
        if after < fleet_two_step {
            score -= 1.0 * (1.0 - after / fleet_two_step.max(1.0)) * (0.5 + 0.7 * progress);
        } else if after > fleet_two_step + 10.0 {
            score += 0.8 * ((after - fleet_two_step - 10.0) / cap) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AI (gen 31): new-bin compaction hedge — when the fleet mean
    // residual is already small (bins nearly full), opening a new bin is
    // cheap and preserves tight bins for small future items; when the mean
    // is large, penalize opening to force compaction into existing bins.
    if is_new_bin && mean > 0.0 {
        let mean_frac = mean / cap;
        if mean_frac < 0.12 {
            score -= 2.0 * (1.0 - mean_frac / 0.12) * (1.0 - 0.5 * progress);
        } else if mean_frac > 0.35 {
            score += 3.0 * (mean_frac - 0.35) * 4.0 * (0.5 + 0.5 * progress);
        }
    }

    // Mutation AJ (gen 31): two-step deadband guard — penalize leftovers
    // after the lookahead item that fall in the "just barely too big for
    // small items, too small for mid items" zone (31..=45), which the
    // dead-space diagnosis flags as the costliest stranded band late-stream.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 31 && after <= 45 {
            score += (0.9 + 1.3 * progress) * (1.0 - (after - 31) as f64 / 14.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Base: two-step waste — leftover after ideally seating the lookahead item too.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Perfect closure / small leftovers.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score += 14.0 + 3.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 5.0;
    } else {
        let post_class = (post_residual * 10 + bin_capacity / 2) / bin_capacity;
        if post_class >= 7 {
            score -= 4.0;
        }
    }

    // Aggressive exact two-step match.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 25.0 + 8.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 10.0;
        } else if slack < 20 {
            score -= 4.0;
        }
    } else if nxt > 0.0 && post > 0.0 && post < nxt {
        // Dead-space risk, graded by wasted fraction.
        let waste_frac = (nxt - post) / nxt;
        score += 0.5 * (nxt - post).min(cap)
            + 6.0
            + 3.0 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.0 * waste_frac * (1.0 - progress);
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Void fraction, graded harder for large voids.
    let void_frac = post / resid;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.5 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 18.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 2.5;
    }

    // New-bin candidate arbitration.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 10.0 + 4.0 * progress;
        } else if pressure < 0.45 {
            score += 2.0 + 4.0 * progress;
        } else {
            score += 10.0 + 6.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
        if progress > 0.85 {
            score += 6.0 * (progress - 0.85) / 0.15;
        }
        // Lookahead-aware opening gate.
        if nxt > 0.0 {
            let new_post = cap - item_size as f64;
            let open_can_chain = fitting_bins_count > 0
                && mean >= item_size as f64
                && (mean - item_size as f64) >= nxt;
            let new_can_chain = new_post >= nxt;
            if open_can_chain && !new_can_chain {
                score += 5.0 + 3.0 * (1.0 - progress);
            } else if !open_can_chain && new_can_chain {
                score -= 2.0 * (1.0 - progress);
            }
            if (new_post - nxt).abs() < 1.0 {
                score -= 4.0 * (1.0 - progress);
            } else if new_post < nxt && progress > 0.5 {
                score += 2.5 * (progress - 0.5) / 0.5;
            }
        }
        // Fragmentation hedge with many open bins.
        if open_bins_count > 8 {
            let frag = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
            score += 0.9 * frag * (0.4 + 0.6 * progress);
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.15;

    // Chain closure.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 2.5 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.5;
    }

    // Progress-adaptive snugness.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        let band = 20.0 - 10.0 * progress;
        if snug < band {
            score -= 1.8 * (1.0 - snug / band) * (0.5 + progress);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
        // Two-deep chain reward.
        if second_left as f64 == nxt || second_left as f64 == item_size as f64 {
            score -= 3.5 + 2.5 * (1.0 - progress);
        } else if (second_left as f64) >= nxt.min(item_size as f64) && second_left < 2 * next_item_size {
            score -= 1.0 * (1.0 - 0.5 * progress);
        }
        // Exact-closure ladder: leftover closable by a typical small item.
        if second_left > 0 && second_left <= 15 {
            score -= 2.0 * (1.0 - second_left as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
        // Anti-fragmentation sweep on large usable leftovers.
        if second_left > 25 {
            score += 0.06 * (second_left as f64 - 25.0);
        }
    }

    // Dead-space ratio penalty vs fleet-average leftover fraction.
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let post_frac = post / cap;
        let mean_frac = (mean / cap).min(1.0);
        if post_frac > mean_frac {
            score += 3.5 * (post_frac - mean_frac) * (1.0 - 0.4 * progress);
        } else {
            score -= 1.2 * (mean_frac - post_frac);
        }
    }

    // Reusable-void valuation.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // Sharpened dead-space hedge for near-miss lookahead.
    if nxt > 0.0 && !is_new_bin && post_residual < next_item_size && progress > 0.1 {
        let unusable = (next_item_size - post_residual) as f64;
        if unusable <= 15.0 {
            score += (2.5 - unusable * 0.15) * (1.0 + 0.5 * progress);
        } else {
            score += 0.75 * unusable * (1.0 - progress);
        }
    }

    // Residual homogeneity bonus.
    if !is_new_bin && mean > 0.0 {
        let hom = ((post - mean).abs() / cap) as f64;
        score -= 0.8 * (1.0 - hom.min(1.0));
    }

    // Asymmetric dead-space bump on post-lookahead leftover fraction.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.32;
        let skew = if x < peak { 0.6 } else { 1.5 };
        let bump = (x - peak) * (x - peak);
        score += 10.0 * skew * bump * (1.0 + progress);
    }

    // Fleet-aware dead-space cap.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Refillability-weighted leftover valuation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // NEW (gen 32): convex dead-space excess guard — penalize bins whose
    // post-lookahead leftover exceeds the fleet mean by a convex margin,
    // with an early-stream grace period (targets diagnosed dead-space weakness).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.05 {
            score += 4.5 * (excess_frac - 0.05) * (excess_frac - 0.05) / (excess_frac + 0.05) * (0.7 + 0.6 * progress);
        }
    }

    // NEW (gen 32): complementarity bonus — reward leftovers whose sum with
    // the fleet-average residual is jointly fillable by a mid-size item.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_frac = (after + mean) / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // NEW (gen 32): waste-shape guard — penalize the awkward middle band
    // 16..=29 of post-lookahead leftovers that are neither closable nor
    // large-reusable (fine-grained residual fitting).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // NEW (gen 32): late-stream exact-chain escalation — when the next item
    // exactly fills the post-residual, reward more strongly late where
    // closure value is highest (lookahead anticipation).
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // NEW (gen 32): two-step closure ladder — reward leftovers that are
    // nearly closed after the lookahead item is seated.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 {
            let closeness = 1.0 - (after / cap).min(1.0);
            score -= 3.0 * closeness * closeness * (0.6 + 0.8 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * (1.0 + 0.6 * progress * norm_post - 0.3 * (1.0 - progress) * norm_post * norm_post);

    // Penalize large dead space more as stream progresses
    let mut score = poly * (1.0 + 0.8 * progress);

    // Tight fits are rewarded, scaled smoothly by progress
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 3.0 * tightness * tightness * (1.0 + progress);

    // Last-chance bin: strong smooth bonus avoiding new bin opening
    if fitting_bins_count == 1 {
        score -= 2.5 + 2.0 * progress;
    }

    // Lookahead: reward leaving room for the next item (smooth quadratic)
    if next_item_size > 0 {
        let diff = pr - next_item_size as f64;
        if diff >= 0.0 {
            score -= 1.5 * (next_item_size as f64 / cap) * (1.0 - (diff / cap).powi(2));
        } else {
            score += 0.5 * (-diff / cap);
        }
    }

    // Mild preference for consolidating into fewer bins early
    score += 0.05 * (open_bins_count as f64 / (1.0 + progress * 10.0));

    // Slight pull toward mean residual state
    score += 0.1 * (norm_post - mean_residual / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Two-step waste base.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Aggressive exact two-step match.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 12.0 + 6.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 5.0;
        } else if slack < 20 {
            score -= 2.0;
        }
    }

    // Perfect closure / small leftovers.
    if post_residual == 0 {
        score -= 24.0;
    } else if post_residual < 10 {
        score += 9.0 + 2.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Dead-space risk: quadratic waste penalty scaled by wasted fraction.
    if nxt > 0.0 && post > 0.0 && post < nxt {
        let waste_frac = (nxt - post) / nxt;
        score += 0.5 * (nxt - post).min(cap)
            + 4.0
            + 3.0 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.0 * waste_frac * (1.0 - progress);
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Void fraction, graded harder for large voids.
    let void_frac = post / resid;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.5 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 8.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 1.5;
    }

    // Opening cost for a brand-new bin.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 6.0 + 3.0 * progress;
        } else if pressure < 0.45 {
            score += 1.0 + 3.0 * progress;
        } else {
            score += 8.0 + 5.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.05;

    // Chain closure: residual exactly matches next item size.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 2.5 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.0;
    }

    // Endgame tightening.
    if progress > 0.85 && is_new_bin {
        score += 6.0 * (progress - 0.85) / 0.15;
    }

    // Snug fit, graded.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        if snug < 5.0 {
            score -= 2.5;
        }
        if snug < 15.0 {
            score -= 1.0 * (1.0 - snug / 15.0);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
    }

    // Dead-space ratio penalty, graded.
    if post > mean && cap > 0.0 {
        let excess_ratio = (post - mean) / cap;
        if excess_ratio > 0.15 {
            score += 2.0 * excess_ratio + 4.0 * (excess_ratio - 0.15);
        }
    }

    // Reusable-void check.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin via residual tiebreak.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // New-bin gate: open a fresh bin only when fits elsewhere are poor.
    if is_new_bin && nxt > 0.0 {
        let fits_poorly = fitting_bins_count > 0 && (bin_capacity as f64 - mean) > item_size as f64 * 1.5;
        if fits_poorly {
            score -= 3.0;
        }
    }

    // Depth-2 lookahead: small residual matching a future item class.
    if nxt > 0.0 && post_residual >= next_item_size {
        let two_left = post_residual - next_item_size;
        if two_left > 0 && two_left <= 10 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Exact-fit chain: post residual equals next item size with a small item.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size && next_item_size <= item_size {
        score -= 3.0 * (1.0 - progress);
    }

    // Mutation F: lookahead-aware dead-space hedge (sharpened weight).
    if nxt > 0.0 && !is_new_bin && post_residual < next_item_size && progress > 0.1 {
        let unusable = (next_item_size - post_residual) as f64;
        score += 0.75 * unusable * (1.0 - progress);
    }

    // Mutation G: residual homogeneity.
    if !is_new_bin && mean > 0.0 {
        let hom = ((post - mean).abs() / cap) as f64;
        score -= 0.8 * (1.0 - hom.min(1.0));
    }

    // Mutation H: dead-space ratio refinement vs fleet-average leftover fraction.
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let post_frac = post / cap;
        let mean_frac = (mean / cap).min(1.0);
        if post_frac > mean_frac {
            score += 3.5 * (post_frac - mean_frac) * (1.0 - 0.4 * progress);
        } else {
            score -= 1.2 * (mean_frac - post_frac);
        }
    }

    // Mutation I: anti-fragmentation sweep on large usable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let usable_left = post_residual - next_item_size;
        if usable_left > 25 {
            score += 0.06 * (usable_left as f64 - 25.0);
        }
    }

    // Mutation J: refillability-weighted leftover valuation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Mutation K: convex shortfall penalty for near-miss lookahead.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 15.0 {
            score += (2.5 - shortfall * 0.15) * (1.0 + 0.5 * progress);
        }
    }

    // Mutation L: asymmetric quadratic dead-space bump (peak 0.38 of capacity).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.38;
        let skew = if x < peak { 0.7 } else { 1.45 };
        let bump = (x - peak) * (x - peak);
        let ramp = if progress > 0.25 { 1.0 + 0.6 * (progress - 0.25) } else { 0.85 + 0.6 * progress };
        score += 15.0 * skew * bump * ramp;
    }

    // Mutation M: lookahead-aware new-bin arbitration.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let open_can_chain = fitting_bins_count > 0
            && mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        let new_can_chain = new_post >= nxt;
        if open_can_chain && !new_can_chain {
            score += 5.0 + 3.0 * (1.0 - progress);
        } else if !open_can_chain && new_can_chain {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Mutation N: utilization-maximizing tiebreak.
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Mutation O: two-step closure ladder.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 {
            let closeness = 1.0 - (after / cap).min(1.0);
            score -= 3.0 * closeness * closeness * (0.6 + 0.8 * progress);
        }
    }

    // Mutation P: fleet-aware dead-space cap.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Mutation Q: two-deep chain reward + mid-band dead-space penalty.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 == nxt || after as f64 == item_size as f64 {
            score -= 3.5 + 2.5 * (1.0 - progress);
        } else if (after as f64) >= nxt.min(item_size as f64) && after < 2 * next_item_size {
            score -= 1.0 * (1.0 - 0.5 * progress);
        }
        if after >= 30 && after <= 60 && progress > 0.3 {
            score += 1.8 * (progress - 0.3) / 0.7;
        }
    }

    // Mutation R: progress-adaptive snugness.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        let band = 20.0 - 10.0 * progress;
        if snug < band {
            score -= 1.6 * (1.0 - snug / band) * (0.5 + progress);
        }
    }

    // Mutation S: new-bin saturation hedge.
    if is_new_bin && open_bins_count > 8 {
        let frag = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
        score += 0.9 * frag * (0.4 + 0.6 * progress);
    }

    // Mutation T (gen 26): sharpen the dead-space bump peak toward 0.30 of capacity.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak2 = 0.30;
        let skew2 = if x < peak2 { 0.6 } else { 1.7 };
        let bump2 = (x - peak2) * (x - peak2);
        score += 6.0 * skew2 * bump2 * (1.0 + 1.4 * progress);
    }

    // Mutation U: exact-closure ladder — reward small closable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 15 {
            score -= 2.0 * (1.0 - after as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
    }

    // Mutation V: new-bin exact-chain gate.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if (new_post - nxt).abs() < 1.0 {
            score -= 4.0 * (1.0 - progress);
        } else if new_post < nxt && progress > 0.5 {
            score += 2.5 * (progress - 0.5) / 0.5;
        }
    }

    // Mutation W: dead-space ratio diagnostic — convex penalty on excess leftover fraction.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.05 {
            score += 4.5 * (excess_frac - 0.05) * (excess_frac - 0.05) / (excess_frac + 0.05) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation X: complementarity bonus — leftover pairs jointly fillable.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_sum = after + mean;
        let pair_frac = pair_sum / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation Y: lookahead-fit calibration — escalate exact-fill reward late.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation Z: waste-shape guard — penalize awkward middle band 16..=29.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AA (gen 32): dead-space curvature refinement — sharpen the
    // combined bump peak toward 0.26 of capacity with a steeper late-stream
    // ramp, directly targeting the residual dead-space weakness.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak3 = 0.26;
        let skew3 = if x < peak3 { 0.55 } else { 1.9 };
        let bump3 = (x - peak3) * (x - peak3);
        score += 4.5 * skew3 * bump3 * (1.0 + 1.8 * progress);
    }

    // Mutation AB (gen 32): snug-lookahead synergy — when the current fit is
    // snug AND the leftover after next-item seating is small, amplify the
    // closure reward to consolidate residual space more aggressively.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let snug_now = (bin_residual - item_size) as f64;
        let after = (post_residual - next_item_size) as f64;
        if snug_now < 8.0 && after <= 20.0 {
            score -= 1.6 * (1.0 - snug_now / 8.0) * (1.0 - after / 20.0) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation AC (gen 32): residual-variance damping — when the fleet residual
    // spread is low, tighten the mean-relative coupling to preserve the
    // homogeneous packing state (keeps Sigma_res low).
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 {
        let dev = (post - mean) / cap;
        if dev.abs() < 0.06 {
            score -= 0.9 * (1.0 - dev.abs() / 0.06);
        } else if dev > 0.06 {
            score += 1.4 * (dev - 0.06) * (1.0 + 0.5 * progress);
        }
    }

    // Mutation AD (gen 32): new-bin anti-dead-space gate — block opening a new
    // bin when its projected leftover would land in the awkward mid-band,
    // pushing items into existing bins instead.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if new_post >= nxt {
            let after_new = new_post - nxt;
            if after_new >= 16.0 && after_new <= 34.0 {
                score += 2.2 * (1.0 - (after_new - 16.0) / 18.0) * (0.6 + 0.8 * progress);
            }
        }
    }

    // Mutation AE (gen 32): exact-closure escalation — deepen the reward for
    // post-residuals that exactly match the next item, scaled by stream depth,
    // reinforcing the strongest closure signal.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 3.0 * (0.5 + 0.7 * progress) * (nxt / cap).max(0.3);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions (1/4, 1/2, 3/4)
    let cap = bin_capacity as f64;
    let q = post_residual as f64 / cap;
    if q < 0.25 {
        // tiny dead space: excellent, strong reward
        score -= 30.0 * (0.25 - q);
    } else if q < 0.5 {
        // moderate: mild reward
        score -= 8.0 * (0.5 - q);
    } else if q < 0.75 {
        // awkward zone: penalize
        score += 6.0 * (q - 0.5);
    } else {
        // large residual left: wasteful placement
        score += 12.0 * (q - 0.75);
    }

    // Integer-division threshold classes on post_residual (mod arithmetic)
    let pr = post_residual;
    let cls = pr / 10; // decade class
    if cls <= 1 {
        score -= 5.0; // residual <= 19: near-perfect fill
    } else if cls >= 7 {
        score += 3.0; // residual >= 70: barely used the bin
    }
    // Exact harmonic residue classes: multiples of 5 are more reusable
    if pr % 10 == 0 {
        score -= 4.0;
    } else if pr % 5 == 0 {
        score -= 2.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this residual: penalize large leftovers mildly
            score += 0.02 * (next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize so it only wins when open bins are truly bad
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
        // but if mean residual across open bins is tiny, new bin is fine
        score -= 0.05 * mean_residual;
    }

    // Prefer tighter bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0 * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
