        }
    }

    // Mutation V: new-bin exact-chain gate.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if (new_post - nxt).abs() < 1.0 {
            score -= 4.0 * (1.0 - progress);
        } else if new_post < nxt && progress > 0.5 {
            score += 2.5 * (progress - 0.5) / 0.5;
        }
    }

    // Mutation W: dead-space ratio diagnostic with convex margin.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.05 {
            score += 4.5 * (excess_frac - 0.05) * (excess_frac - 0.05) / (excess_frac + 0.05) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation X: complementarity bonus — leftover pairs with fleet mean.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_sum = after + mean;
        let pair_frac = pair_sum / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation Y: lookahead-fit calibration — escalate exact-fill reward late.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation Z: waste-shape guard — awkward middle band 16..=29.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AA (gen 34): residual-compaction gradient — reward bins whose
    // post-lookahead leftover shrinks toward the fleet mean (tightening the
    // residual distribution), scaled by how close the bin already is to full.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let gap = after - mean;
        if gap < 0.0 {
            let fill_frac = 1.0 - (bin_residual as f64 / cap);
            score += 0.55 * gap * fill_frac * (0.6 + 0.8 * progress);
        }
    }

    // Mutation AB (gen 34): dual-fit hedge — when multiple bins fit, mildly
    // prefer the one whose post-residual can still host the next item AND
    // whose consumed fraction is highest, tightening overall compaction.
    if !is_new_bin && nxt > 0.0 && fitting_bins_count >= 2 && post_residual >= next_item_size {
        let consumed = (bin_residual - item_size) as f64;
        let tightness = consumed / cap;
        score -= 1.1 * tightness * (1.0 - 0.5 * progress);
    }

    // Mutation AC (gen 34): new-bin residual compaction gate — prefer opening
    // a new bin only when its post-residual lands in the closable small band
    // (<= 12) or exceeds the next item comfortably; otherwise lean on existing bins.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if new_post > 12.0 && new_post < nxt {
            score += 2.2 * (1.0 - 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
