    }

    // Mutation J: refillability-weighted leftover valuation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Mutation K: convex shortfall penalty for near-miss lookahead.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 15.0 {
            score += (2.5 - shortfall * 0.15) * (1.0 + 0.5 * progress);
        }
    }

    // Mutation L: asymmetric quadratic dead-space bump (peak 0.38 of capacity).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.38;
        let skew = if x < peak { 0.7 } else { 1.45 };
        let bump = (x - peak) * (x - peak);
        let ramp = if progress > 0.25 { 1.0 + 0.6 * (progress - 0.25) } else { 0.85 + 0.6 * progress };
        score += 15.0 * skew * bump * ramp;
    }

    // Mutation M: lookahead-aware new-bin arbitration.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let open_can_chain = fitting_bins_count > 0
            && mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        let new_can_chain = new_post >= nxt;
        if open_can_chain && !new_can_chain {
            score += 5.0 + 3.0 * (1.0 - progress);
        } else if !open_can_chain && new_can_chain {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Mutation N: utilization-maximizing tiebreak.
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Mutation O: two-step closure ladder.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 {
            let closeness = 1.0 - (after / cap).min(1.0);
            score -= 3.0 * closeness * closeness * (0.6 + 0.8 * progress);
        }
    }

    // Mutation P: fleet-aware dead-space cap.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Mutation Q: two-deep chain reward + mid-band dead-space penalty.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 == nxt || after as f64 == item_size as f64 {
            score -= 3.5 + 2.5 * (1.0 - progress);
        } else if (after as f64) >= nxt.min(item_size as f64) && after < 2 * next_item_size {
            score -= 1.0 * (1.0 - 0.5 * progress);
        }
        if after >= 30 && after <= 60 && progress > 0.3 {
            score += 1.8 * (progress - 0.3) / 0.7;
        }
    }

    // Mutation R: progress-adaptive snugness.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        let band = 20.0 - 10.0 * progress;
        if snug < band {
            score -= 1.6 * (1.0 - snug / band) * (0.5 + progress);
        }
    }

    // Mutation S: new-bin saturation hedge.
    if is_new_bin && open_bins_count > 8 {
        let frag = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
        score += 0.9 * frag * (0.4 + 0.6 * progress);
    }

    // Mutation T (refined gen 35): sharpen the dead-space bump peak toward
    // 0.28 of capacity with stronger late-stream scaling and a mild early
    // grace so exploration is preserved.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak2 = 0.28;
        let skew2 = if x < peak2 { 0.55 } else { 1.85 };
        let bump2 = (x - peak2) * (x - peak2);
        let grace = if progress < 0.08 { 0.7 } else { 1.0 };
        score += 7.0 * skew2 * bump2 * (1.0 + 1.6 * progress) * grace;
    }

    // Mutation U: exact-closure ladder — reward small closable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 15 {
            score -= 2.2 * (1.0 - after as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
    }

    // Mutation V: new-bin exact-chain gate.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if (new_post - nxt).abs() < 1.0 {
            score -= 4.0 * (1.0 - progress);
        } else if new_post < nxt && progress > 0.5 {
            score += 2.5 * (progress - 0.5) / 0.5;
        }
    }

    // Mutation W (refined gen 35): dead-space ratio diagnostic — convex
    // penalty on post-lookahead leftover fraction exceeding the fleet mean,
    // threshold tightened to 0.04 with late-stream escalation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.04 {
            score += 5.0 * (excess_frac - 0.04) * (excess_frac - 0.04) / (excess_frac + 0.04) * (0.6 + 0.8 * progress);
        }
    }

    // Mutation X: complementarity bonus — leftover pairs jointly fillable.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_sum = after + mean;
        let pair_frac = pair_sum / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation Y: lookahead-fit calibration — exact post-residual fill reward
    // escalates late in the stream.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.2 * progress * (nxt / cap);
    }

    // Mutation Z: waste-shape guard — penalize awkward middle band leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.4 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AA (gen 35): residual-compaction coupling — when the item is
    // large relative to capacity, reward bins whose remaining residual after
    // seating is a small multiple of the next item size, steering large items
    // into bins that will be exactly consumed by the next small item.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 2 * next_item_size && item_size >= bin_capacity / 2 {
            score -= 1.5 * (1.0 - after as f64 / (2.0 * nxt)) * (0.4 + 0.6 * progress);
        }
    }

    // Mutation BB (gen 35): fleet-pressure-aware new-bin trigger — allow
    // opening a new bin late in the stream when all fitting bins leave
    // sub-lookahead residuals (poor fits), preventing forced fragmentation.
    if is_new_bin && nxt > 0.0 && fitting_bins_count > 0 && progress > 0.4 {
        let all_bad = fitting_bins_count <= 2 && mean + item_size as f64 > cap - nxt * 0.5;
        if all_bad {
            score -= 2.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    if nxt > 0.0 && post_residual == next_item_size {
        score -= 12.0 + 6.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 5.0;
        } else if slack < 20 {
            score -= 2.0;
        }
    }

    if post_residual == 0 {
        score -= 24.0;
    } else if post_residual < 10 {
        score += 9.0 + 2.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 3.0;
    }

    if nxt > 0.0 && post > 0.0 && post < nxt {
        let waste_frac = (nxt - post) / nxt;
        score += 0.5 * (nxt - post).min(cap)
            + 4.0
            + 3.0 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.0 * waste_frac * (1.0 - progress);
    }

    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    let void_frac = post / resid;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.5 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    if !is_new_bin && fitting_bins_count == 1 {
        score -= 8.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 1.5;
    }

    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 6.0 + 3.0 * progress;
        } else if pressure < 0.45 {
            score += 1.0 + 3.0 * progress;
        } else {
            score += 8.0 + 5.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
    }

    score += open_bins_count as f64 * 0.05;

    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 2.5 * (1.0 - progress);
    }

    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.0;
    }

    if progress > 0.85 && is_new_bin {
        score += 6.0 * (progress - 0.85) / 0.15;
    }

    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        if snug < 5.0 {
            score -= 2.5;
        }
        if snug < 15.0 {
            score -= 1.0 * (1.0 - snug / 15.0);
        }
    }

    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
    }

    if post > mean && cap > 0.0 {
        let excess_ratio = (post - mean) / cap;
        if excess_ratio > 0.15 {
            score += 2.0 * excess_ratio + 4.0 * (excess_ratio - 0.15);
        }
    }

    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
    }

    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    if is_new_bin && nxt > 0.0 {
        let fits_poorly = fitting_bins_count > 0 && (bin_capacity as f64 - mean) > item_size as f64 * 1.5;
        if fits_poorly {
            score -= 3.0;
        }
    }

    if nxt > 0.0 && post_residual >= next_item_size {
        let two_left = post_residual - next_item_size;
        if two_left > 0 && two_left <= 10 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size && next_item_size <= item_size {
        score -= 3.0 * (1.0 - progress);
    }

    // Mutation F
    if nxt > 0.0 && !is_new_bin && post_residual < next_item_size && progress > 0.1 {
        let unusable = (next_item_size - post_residual) as f64;
        score += 0.75 * unusable * (1.0 - progress);
    }

    // Mutation G
    if !is_new_bin && mean > 0.0 {
        let hom = ((post - mean).abs() / cap) as f64;
        score -= 0.8 * (1.0 - hom.min(1.0));
    }

    // Mutation H
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let post_frac = post / cap;
        let mean_frac = (mean / cap).min(1.0);
        if post_frac > mean_frac {
            score += 3.5 * (post_frac - mean_frac) * (1.0 - 0.4 * progress);
        } else {
            score -= 1.2 * (mean_frac - post_frac);
        }
    }

    // Mutation I
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let usable_left = post_residual - next_item_size;
        if usable_left > 25 {
            score += 0.06 * (usable_left as f64 - 25.0);
        }
    }

    // Mutation J
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Mutation K
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 15.0 {
            score += (2.5 - shortfall * 0.15) * (1.0 + 0.5 * progress);
        }
    }

    // Mutation L
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.38;
        let skew = if x < peak { 0.7 } else { 1.45 };
        let bump = (x - peak) * (x - peak);
        let ramp = if progress > 0.25 { 1.0 + 0.6 * (progress - 0.25) } else { 0.85 + 0.6 * progress };
        score += 15.0 * skew * bump * ramp;
    }

    // Mutation M
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let open_can_chain = fitting_bins_count > 0
            && mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        let new_can_chain = new_post >= nxt;
        if open_can_chain && !new_can_chain {
            score += 5.0 + 3.0 * (1.0 - progress);
        } else if !open_can_chain && new_can_chain {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Mutation N
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Mutation O
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 {
            let closeness = 1.0 - (after / cap).min(1.0);
            score -= 3.0 * closeness * closeness * (0.6 + 0.8 * progress);
        }
    }

    // Mutation P
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Mutation T (refined gen 26)
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak2 = 0.30;
        let skew2 = if x < peak2 { 0.6 } else { 1.7 };
        let bump2 = (x - peak2) * (x - peak2);
        score += 6.0 * skew2 * bump2 * (1.0 + 1.4 * progress);
    }

    // Mutation U
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 15 {
            score -= 2.0 * (1.0 - after as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
    }

    // Mutation V
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if (new_post - nxt).abs() < 1.0 {
            score -= 4.0 * (1.0 - progress);
        } else if new_post < nxt && progress > 0.5 {
            score += 2.5 * (progress - 0.5) / 0.5;
        }
    }

    // Mutation W (gen 26)
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.05 {
            score += 4.5 * (excess_frac - 0.05) * (excess_frac - 0.05) / (excess_frac + 0.05) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation X (gen 26)
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_sum = after + mean;
        let pair_frac = pair_sum / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation Y (gen 26)
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation Z (gen 26)
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AA (gen 29)
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak3 = 0.26;
        let skew3 = if x < peak3 { 0.55 } else { 1.9 };
        let bump3 = (x - peak3) * (x - peak3);
        score += 5.0 * skew3 * bump3 * (0.8 + 1.6 * progress);
    }

    // Mutation AB (gen 29)
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let dev = (after - mean) / cap;
        if dev < 0.0 {
            score -= 1.4 * (-dev) * (1.0 - 0.5 * progress);
        } else {
            score += 0.7 * dev * dev * cap.min(100.0) / 10.0;
        }
    }

    // Mutation AC (gen 29)
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let diff = (after as f64 - item_size as f64).abs();
        if diff <= 6.0 && after > 0 {
            score -= (2.2 - diff * 0.25) * (0.5 + 0.9 * progress);
        }
    }

    // Mutation AD (gen 29)
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let after_new = new_post - nxt;
        if after_new >= 16.0 && after_new <= 34.0 {
            score += 2.5 * (1.0 - (after_new - 16.0) / 18.0) * (0.4 + 0.8 * progress);
        } else if after_new > 0.0 && after_new < 8.0 {
            score -= 1.5 * (1.0 - progress);
        }
    }

    // Mutation AE (gen 29)
    if !is_new_bin && mean > 0.0 {
        let spread = (mean / cap - 0.25).abs();
        if spread > 0.10 {
            let snug2 = (bin_residual - item_size) as f64;
            if snug2 >= 0.0 && snug2 < 10.0 {
                score -= 1.1 * spread * (1.0 - snug2 / 10.0) * (0.6 + 0.6 * progress);
            }
        }
    }

    // Mutation AF (gen 36, Combine): residual-fitting x lookahead anticipation —
    // when the current bin's residual exactly equals the next item size, the
    // two-step chain closes perfectly; escalate this reward with the fleet
    // residual variance to fight the diagnosed dead-space weakness.
    if !is_new_bin && nxt > 0.0 && bin_residual == next_item_size {
        score -= 3.0 * (1.0 - progress) * (1.0 + 0.5 * (mean / cap).min(1.0));
    }

    // Mutation AG (gen 36): dead-space ratio fine-fitting — grade the
    // post-lookahead leftover against item-size quanta; leftovers within one
    // small quantum of a reusable shape get a graded discount, tightening
    // compaction where the diagnosed weakness (suboptimal residual) occurs.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let quantum = (item_size as f64).min(10.0);
        let rem = after % quantum.max(1.0);
        if rem < 3.0 && after > 0.0 {
            score -= 1.3 * (1.0 - rem / 3.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AH (gen 36): new-bin pressure arbitration — open a fresh bin
    // only when the fleet is genuinely saturated; when many bins can fit the
    // item, penalize opening more strongly late in the stream.
    if is_new_bin && fitting_bins_count > 2 {
        score += 2.0 + 4.0 * progress;
    } else if is_new_bin && fitting_bins_count == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small for the smallest possible item (or the
    // lookahead item) are wasted forever. Punish them hard.
    let min_useful = next_item_size.max(1).min(10) as f64;
    let dead_threshold = if next_item_size > 0 { next_item_size as f64 } else { 10.0 };
    if (post_residual as f64) < dead_threshold {
        score += 25.0 + (dead_threshold - post_residual as f64) * 2.0;
    }
    if post_residual > 0 && (post_residual as f64) < min_useful {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: prefer reusing bins when many are open; when few bins
    // are open, tolerate opening a new one.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using the only bin that fits to avoid
    // opening a new bin for a large item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize slightly so we only open a new bin when the
    // fit in existing bins is genuinely bad; scale pressure with progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 8.0 + progress * 10.0;
        // Opening a new bin is more attractive if the item leaves a clean,
        // reusable residual and existing bins are fragmented.
        if item_size >= bin_capacity / 2 {
            score -= 6.0;
        }
        if (mean_residual - item_size as f64) < 0.0 {
            score -= 4.0;
        }
    }

    // Lookahead coupling: if the next item would fit exactly in the residual
    // left behind, this placement is doubly good.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // If next item cannot fit in the post residual but could fit elsewhere,
    // mildly penalize creating a stranded gap.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Mild alignment with mean residual: prefer bins close to the mean to keep
    // the bin portfolio balanced.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Base: two-step waste — leftover after ideally seating the lookahead item too.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Perfect closure / small leftovers.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score += 14.0 + 3.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 5.0;
    } else {
        let post_class = (post_residual * 10 + bin_capacity / 2) / bin_capacity;
        if post_class >= 7 {
            score -= 4.0;
        }
    }

    // Aggressive exact two-step match.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 25.0 + 8.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 10.0;
        } else if slack < 20 {
            score -= 4.0;
        }
    } else if nxt > 0.0 && post > 0.0 && post < nxt {
        let waste_frac = (nxt - post) / nxt;
        score += 0.6 * (nxt - post).min(cap)
            + 7.0
            + 3.5 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.5 * waste_frac * (1.0 - progress);
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Void fraction, graded harder for large voids.
    let void_frac = post / resid;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.8 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 18.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 2.5;
    }

    // New-bin candidate arbitration.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 10.0 + 4.0 * progress;
        } else if pressure < 0.45 {
            score += 2.0 + 4.0 * progress;
        } else {
            score += 10.0 + 6.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
        if progress > 0.85 {
            score += 6.0 * (progress - 0.85) / 0.15;
        }
        // Lookahead-aware opening gate.
        if nxt > 0.0 {
            let new_post = cap - item_size as f64;
            let open_can_chain = fitting_bins_count > 0
                && mean >= item_size as f64
                && (mean - item_size as f64) >= nxt;
            let new_can_chain = new_post >= nxt;
            if open_can_chain && !new_can_chain {
                score += 5.0 + 3.0 * (1.0 - progress);
            } else if !open_can_chain && new_can_chain {
                score -= 2.5 * (1.0 - progress);
            }
            if (new_post - nxt).abs() < 1.0 {
                score -= 4.0 * (1.0 - progress);
            } else if new_post < nxt && progress > 0.5 {
                score += 2.5 * (progress - 0.5) / 0.5;
            }
        }
        if open_bins_count > 8 {
            let frag = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
            score += 0.9 * frag * (0.4 + 0.6 * progress);
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.15;

    // Chain closure.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 3.0 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.5;
    }

    // Progress-adaptive snugness.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        let band = 20.0 - 10.0 * progress;
        if snug < band {
            score -= 1.8 * (1.0 - snug / band) * (0.5 + progress);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
        if second_left as f64 == nxt || second_left as f64 == item_size as f64 {
            score -= 3.5 + 2.5 * (1.0 - progress);
        } else if (second_left as f64) >= nxt.min(item_size as f64) && second_left < 2 * next_item_size {
            score -= 1.0 * (1.0 - 0.5 * progress);
        }
        if second_left > 0 && second_left <= 15 {
            score -= 2.2 * (1.0 - second_left as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
        if second_left > 25 {
            score += 0.06 * (second_left as f64 - 25.0);
        }
    }

    // Dead-space ratio penalty vs fleet-average leftover fraction.
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let post_frac = post / cap;
        let mean_frac = (mean / cap).min(1.0);
        if post_frac > mean_frac {
            score += 4.0 * (post_frac - mean_frac) * (1.0 - 0.4 * progress);
        } else {
            score -= 1.2 * (mean_frac - post_frac);
        }
    }

    // Reusable-void valuation.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // Sharpened dead-space hedge for near-miss lookahead.
    if nxt > 0.0 && !is_new_bin && post_residual < next_item_size && progress > 0.1 {
        let unusable = (next_item_size - post_residual) as f64;
        if unusable <= 15.0 {
            score += (2.5 - unusable * 0.15) * (1.0 + 0.5 * progress);
        } else {
            score += 0.75 * unusable * (1.0 - progress);
        }
    }

    // Residual homogeneity bonus.
    if !is_new_bin && mean > 0.0 {
        let hom = ((post - mean).abs() / cap) as f64;
        score -= 0.8 * (1.0 - hom.min(1.0));
    }

    // Asymmetric dead-space bump on post-lookahead leftover fraction.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.30;
        let skew = if x < peak { 0.6 } else { 1.6 };
        let bump = (x - peak) * (x - peak);
        score += 9.0 * skew * bump * (1.0 + 1.2 * progress);
    }

    // Fleet-aware dead-space cap.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Refillability-weighted leftover valuation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Mid-band dead-space penalty on post-lookahead leftover (30-60 range).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 30 && after <= 60 && progress > 0.3 {
            score += 1.8 * (progress - 0.3) / 0.7;
        }
    }

    // Two-step closure ladder — reward small closable leftovers harder.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 {
            let closeness = 1.0 - (after / cap).min(1.0);
            score -= 3.0 * closeness * closeness * (0.6 + 0.8 * progress);
        }
    }

    // Mutation A (gen 30): convex excess-fraction penalty vs fleet mean.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.05 {
            score += 4.5 * (excess_frac - 0.05) * (excess_frac - 0.05) / (excess_frac + 0.05) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation B (gen 30): complementarity bonus.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_frac = (after + mean) / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation C (gen 30): awkward-middle-band guard (16..=29 leftovers).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation D (gen 30): late-stream exact-fill escalation.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation E (gen 30): dual-threshold new-bin gate.
    if is_new_bin && nxt > 0.0 && fitting_bins_count > 0 {
        let best_chain_possible = mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        if !best_chain_possible && open_bins_count as f64 * (mean / cap) > 2.5 {
            score -= 1.5 * (1.0 - progress);
        }
    }

    // Mutation F (gen 34): three-item chain anticipation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let third = mean.max(1.0);
        if after >= third {
            let closeness = 1.0 - ((after - third) / cap).min(1.0);
            score -= 2.0 * closeness * closeness * (0.5 + 0.9 * progress);
        } else if after > 0.0 && third - after <= 8.0 {
            score += 1.0 * (1.0 - (third - after) / 8.0) * (0.4 + 0.8 * progress);
        }
    }

    // Mutation G (gen 34): bin-choice diversity hedge.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let target = mean * 0.5;
        let dev = (after - target).abs() / cap;
        score += 1.4 * dev * (0.6 + 0.8 * progress);
    }

    // Mutation H (gen 34): late-stream consolidation escalation.
    if is_new_bin && progress > 0.6 && fitting_bins_count > 0 {
        score += 4.0 * (progress - 0.6) / 0.4 * (1.0 + (fitting_bins_count as f64).min(5.0) * 0.2);
    }

    // Mutation I (gen 34): exact two-item closure with parity coupling.
    if !is_new_bin && nxt > 0.0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if item_size > 0 && after % item_size == 0 && after / item_size >= 2 {
            score -= 2.5 * (1.0 - 0.3 * progress);
        }
    }

    // Mutation J (gen 35): dead-space minimization core.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 && after < mean * 0.5 {
            score += 2.2 * (1.0 - after / (mean * 0.5)) * (0.6 + 0.9 * progress);
        } else if (after - mean).abs() < 1.0 {
            score -= 3.0 * (1.0 - 0.4 * progress);
        }
    }

    // Mutation K (gen 35): dual-item lookahead coupling.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let small_class = (item_size / 2).max(1);
        if after >= small_class && after - small_class < small_class {
            score -= 1.6 * (1.0 - 0.5 * progress);
        } else if after > 0 && after < small_class && after < 6 {
            score += 1.1 * (1.0 - after as f64 / 6.0);
        }
    }

    // Mutation L (gen 35): residual-space packing slope.
    if !is_new_bin && nxt > 0.0 {
        if post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            score += 0.11 * after * (0.3 + 0.7 * progress);
            if after == 0 {
                score -= 4.0 + 3.0 * progress;
            }
        } else {
            let stranded = post as f64;
            score += 0.14 * stranded * (0.2 + 0.8 * progress);
        }
    }

    // Mutation M (gen 35): new-bin dead-space floor.
    if is_new_bin && nxt > 0.0 && fitting_bins_count > 0 {
        let new_post = cap - item_size as f64;
        if new_post >= nxt {
            let new_after = new_post - nxt;
            if new_after > cap * 0.55 {
                score += 2.0 * (new_after / cap) * (0.5 + progress);
            } else if new_after < cap * 0.12 {
                score -= 1.6 * (1.0 - progress);
            }
        }
    }

    // Mutation N (gen 36): zero-dead-space escalation — when the post-lookahead
    // leftover is exactly zero the bin is perfectly closed for two steps; reward
    // this far more strongly, especially late in the stream where each closure
    // directly removes a bin from the total.
    if !is_new_bin && nxt > 0.0 && post_residual == 0 {
        score -= 14.0 + 10.0 * progress;
    }

    // Mutation O (gen 36): mean-chain exactness — when the post-lookahead leftover
    // is within a tight tolerance of the fleet-mean residual, the next-next item
    // (drawn from the same distribution) is likely to close it; reward bins whose
    // leftover matches mean_residual closely, penalize near-misses just above it.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 1.0 {
        let after = (post_residual - next_item_size) as f64;
        let d = after - mean;
        if d.abs() <= 2.0 {
            score -= 3.5 * (1.0 - d.abs() / 2.0) * (0.5 + 0.7 * progress);
        } else if d > 2.0 && d <= 8.0 {
            score += 0.5 * d * (0.4 + 0.6 * progress);
        }
    }

    // Mutation P (gen 36): fitting-competition scaling — when several bins fit,
    // amplify the discrimination between good and bad leftovers so the best
    // leftover wins decisively; when only one bin fits, soften penalties since
    // the choice is forced anyway.
    if !is_new_bin && nxt > 0.0 {
        if fitting_bins_count >= 3 {
            let after = post_residual as f64;
            score += 0.05 * after * (fitting_bins_count as f64 - 2.0).min(3.0) * (0.3 + 0.7 * progress);
        }
    }

    // Mutation Q (gen 36): new-bin threshold tightening — a fresh bin should only
    // win when its post-lookahead leftover is strictly smaller than the best
    // achievable open-bin leftover proxy (mean-driven); penalize opening when the
    // new bin's leftover exceeds mean_residual substantially.
    if is_new_bin && nxt > 0.0 && fitting_bins_count > 0 && mean > 0.0 {
        let new_post = cap - item_size as f64;
        let new_after = if new_post >= nxt { new_post - nxt } else { new_post };
        if new_after > mean * 1.4 && progress > 0.2 {
            score += 2.5 * (progress - 0.2) / 0.8 * (new_after - mean * 1.4).min(cap * 0.3) / cap.max(1.0) * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual == next_item_size is ideal.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Reward closeness of post-fit space to the next item (big bonus for exact match).
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).powi(3);
        // Exact match gets extra reward.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: prefer minimal waste directly.
        score += 5.0;
    }

    // Penalize dead space that is too small for any plausible future item (items >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Slight preference for tighter fits relative to the mean residual of open bins.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    // (post_residual near full capacity means nothing was really consumed).
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64;
        // If next item exactly fills a fresh bin after this one, opening is good.
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 20.0;
        }
    }

    // Mild late-stream consolidation: prefer reusing bins as the stream nears its end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Base: two-step waste — leftover after ideally seating the lookahead item too.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Aggressive exact two-step match.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 12.0 + 6.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 5.0;
        } else if slack < 20 {
            score -= 2.0;
        }
    }

    // Perfect closure / small leftovers.
    if post_residual == 0 {
        score -= 24.0;
    } else if post_residual < 10 {
        score += 9.0 + 2.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Dead-space risk: quadratic waste penalty scaled by wasted fraction.
    if nxt > 0.0 && post > 0.0 && post < nxt {
        let waste_frac = (nxt - post) / nxt;
        score += 0.5 * (nxt - post).min(cap)
            + 4.0
            + 3.0 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.0 * waste_frac * (1.0 - progress);
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Void fraction, graded harder for large voids.
    let void_frac = post / resid;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.5 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 8.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 1.5;
    }

    // Opening cost for a brand-new bin.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 6.0 + 3.0 * progress;
        } else if pressure < 0.45 {
            score += 1.0 + 3.0 * progress;
        } else {
            score += 8.0 + 5.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.05;

    // Chain closure: residual exactly matches next item size.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 2.5 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.0;
    }

    // Endgame tightening.
    if progress > 0.85 && is_new_bin {
        score += 6.0 * (progress - 0.85) / 0.15;
    }

    // Snug fit, graded.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        if snug < 5.0 {
            score -= 2.5;
        }
        if snug < 15.0 {
            score -= 1.0 * (1.0 - snug / 15.0);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
    }

    // Dead-space ratio penalty, graded.
    if post > mean && cap > 0.0 {
        let excess_ratio = (post - mean) / cap;
        if excess_ratio > 0.15 {
            score += 2.0 * excess_ratio + 4.0 * (excess_ratio - 0.15);
        }
    }

    // Reusable-void check.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin via residual tiebreak.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // New-bin gate: open a fresh bin only when fits elsewhere are poor.
    if is_new_bin && nxt > 0.0 {
        let fits_poorly = fitting_bins_count > 0 && (bin_capacity as f64 - mean) > item_size as f64 * 1.5;
        if fits_poorly {
            score -= 3.0;
        }
    }

    // Depth-2 lookahead: small residual matching a future item class.
    if nxt > 0.0 && post_residual >= next_item_size {
        let two_left = post_residual - next_item_size;
        if two_left > 0 && two_left <= 10 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Exact-fit chain: post residual equals next item size with a small item.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size && next_item_size <= item_size {
        score -= 3.0 * (1.0 - progress);
    }

    // Mutation F: lookahead-aware dead-space hedge (sharpened weight).
    if nxt > 0.0 && !is_new_bin && post_residual < next_item_size && progress > 0.1 {
        let unusable = (next_item_size - post_residual) as f64;
        score += 0.75 * unusable * (1.0 - progress);
    }

    // Mutation G: residual homogeneity.
    if !is_new_bin && mean > 0.0 {
        let hom = ((post - mean).abs() / cap) as f64;
        score -= 0.8 * (1.0 - hom.min(1.0));
    }

    // Mutation H: dead-space ratio refinement vs fleet-average leftover fraction.
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let post_frac = post / cap;
        let mean_frac = (mean / cap).min(1.0);
        if post_frac > mean_frac {
            score += 3.5 * (post_frac - mean_frac) * (1.0 - 0.4 * progress);
        } else {
            score -= 1.2 * (mean_frac - post_frac);
        }
    }

    // Mutation I: anti-fragmentation sweep on large usable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let usable_left = post_residual - next_item_size;
        if usable_left > 25 {
            score += 0.06 * (usable_left as f64 - 25.0);
        }
    }

    // Mutation J: refillability-weighted leftover valuation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Mutation K: convex shortfall penalty for near-miss lookahead.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 15.0 {
            score += (2.5 - shortfall * 0.15) * (1.0 + 0.5 * progress);
        }
    }

    // Mutation L: asymmetric quadratic dead-space bump (peak 0.38 of capacity).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.38;
        let skew = if x < peak { 0.7 } else { 1.45 };
        let bump = (x - peak) * (x - peak);
        let ramp = if progress > 0.25 { 1.0 + 0.6 * (progress - 0.25) } else { 0.85 + 0.6 * progress };
        score += 15.0 * skew * bump * ramp;
    }

    // Mutation M: lookahead-aware new-bin arbitration.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let open_can_chain = fitting_bins_count > 0
            && mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        let new_can_chain = new_post >= nxt;
        if open_can_chain && !new_can_chain {
            score += 5.0 + 3.0 * (1.0 - progress);
        } else if !open_can_chain && new_can_chain {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Mutation N: utilization-maximizing tiebreak.
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Mutation O: two-step closure ladder.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 {
            let closeness = 1.0 - (after / cap).min(1.0);
            score -= 3.0 * closeness * closeness * (0.6 + 0.8 * progress);
        }
    }

    // Mutation P: fleet-aware dead-space cap.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Mutation T (refined): dead-space bump sharpened toward 0.30 of capacity.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak2 = 0.30;
        let skew2 = if x < peak2 { 0.6 } else { 1.7 };
        let bump2 = (x - peak2) * (x - peak2);
        score += 6.0 * skew2 * bump2 * (1.0 + 1.4 * progress);
    }

    // Mutation U: exact-closure ladder — reward small closable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 15 {
            score -= 2.0 * (1.0 - after as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
    }

    // Mutation V: new-bin exact-chain gate.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if (new_post - nxt).abs() < 1.0 {
            score -= 4.0 * (1.0 - progress);
        } else if new_post < nxt && progress > 0.5 {
            score += 2.5 * (progress - 0.5) / 0.5;
        }
    }

    // Mutation W: dead-space ratio diagnostic — convex penalty for
    // post-lookahead leftover fraction exceeding the fleet mean.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.05 {
            score += 4.5 * (excess_frac - 0.05) * (excess_frac - 0.05) / (excess_frac + 0.05) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation X: complementarity bonus — reward leftovers whose sum
    // with the fleet mean is jointly fillable by mid-size items.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_sum = after + mean;
        let pair_frac = pair_sum / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation Y: lookahead-fit calibration — escalate exact-fill
    // reward late in the stream where closure value is highest.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation Z: waste-shape guard — penalize the awkward middle
    // band 16..=29 of leftovers that are neither closable nor reusable.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AA: sharpen the dead-space bump peak toward 0.26 of capacity
    // with progress-adaptive skew.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak3 = 0.26;
        let skew3 = if x < peak3 { 0.55 } else { 1.9 };
        let bump3 = (x - peak3) * (x - peak3);
        score += 5.0 * skew3 * bump3 * (0.8 + 1.6 * progress);
    }

    // Mutation AB: fleet-mean residual-shape alignment.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let dev = (after - mean) / cap;
        if dev < 0.0 {
            score -= 1.4 * (-dev) * (1.0 - 0.5 * progress);
        } else {
            score += 0.7 * dev * dev * cap.min(100.0) / 10.0;
        }
    }

    // Mutation AC: lookahead-complement pairing — when the leftover
    // after seating the next item is within a small window of the current
    // item's size class, the bin can chain three items.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let diff = (after as f64 - item_size as f64).abs();
        if diff <= 6.0 && after > 0 {
            score -= (2.2 - diff * 0.25) * (0.5 + 0.9 * progress);
        }
    }

    // Mutation AD: new-bin dead-space preemption.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let after_new = new_post - nxt;
        if after_new >= 16.0 && after_new <= 34.0 {
            score += 2.5 * (1.0 - (after_new - 16.0) / 18.0) * (0.4 + 0.8 * progress);
        } else if after_new > 0.0 && after_new < 8.0 {
            score -= 1.5 * (1.0 - progress);
        }
    }

    // Mutation AE: residual-variance dampener.
    if !is_new_bin && mean > 0.0 {
        let spread = (mean / cap - 0.25).abs();
        if spread > 0.10 {
            let snug2 = (bin_residual - item_size) as f64;
            if snug2 >= 0.0 && snug2 < 10.0 {
                score -= 1.1 * spread * (1.0 - snug2 / 10.0) * (0.6 + 0.6 * progress);
            }
        }
    }

    // Mutation AF (gen 36, Combine): dual-threshold exact-fit escalation —
    // combine fine-grained snug fitting with lookahead anticipation by
    // rewarding bins where BOTH the current fit is near-exact AND the
    // post-lookahead leftover is either zero or exactly the next item size.
    if !is_new_bin && nxt > 0.0 {
        let snug_now = (bin_residual - item_size) as f64;
        if snug_now <= 2.0 && post_residual == 0 {
            score -= 5.0 + 3.0 * progress;
        } else if snug_now <= 4.0 && post_residual == next_item_size {
            score -= 3.0 + 2.0 * progress;
        }
    }

    // Mutation AG (gen 36): dead-space valley targeting — instead of only
    // penalizing large dead space, actively steer post-lookahead leftovers
    // toward the highly refillable narrow valley (residual within [4, 12])
    // where future small items close bins exactly.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after >= 4.0 && after <= 12.0 {
            score -= 2.8 * (1.0 - (after - 4.0).abs() / 4.0).max(0.0) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation AH (gen 36): new-bin arbitration refinement — when the fleet
    // is nearly saturated (mean residual small relative to item), opening a
    // fresh bin is cheap; when open bins can still chain the lookahead item,
    // opening is penalized harder with progress.
    if is_new_bin && nxt > 0.0 {
        let fleet_can_chain = fitting_bins_count > 0 && mean >= nxt + item_size as f64;
        if fleet_can_chain && progress > 0.4 {
            score += 3.0 * (progress - 0.4) / 0.6;
        } else if !fleet_can_chain && mean < 0.35 * cap {
            score -= 2.0 * (1.0 - mean / (0.35 * cap));
        }
    }

    // Mutation AI (gen 36): residual-decay guard — penalize bins whose
    // post-lookahead leftover exceeds half the next item size by a wide
    // margin late in the stream (stranded capacity compounds at the end).
    if !is_new_bin && nxt > 0.0 && post > 0.0 && post < nxt {
        let stranded_frac = 1.0 - post / nxt;
        if stranded_frac > 0.5 && progress > 0.6 {
            score += 2.0 * (stranded_frac - 0.5) * (progress - 0.6) / 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on post-residual (dead space).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64).powi(2) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // Next item cannot use the leftover space -> penalize more strongly for small leftovers.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Prefer fuller bins relative to the fleet average residual.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Time horizon: early in the stream, be conservative about fragmenting bins;
    // late in the stream, pack greedily into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    // Penalize opening a new bin when open bins can fit, more so as bins accumulate.
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        score += 25.0 + open_bins_count as f64 * 2.0;
    }

    // Slight preference to spread load early (avoid many near-empty bins later).
    if open_bins_count > 0 {
        score += (open_bins_count as f64).ln() * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Two-step waste base.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Aggressive exact two-step match.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 12.0 + 6.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 5.0;
        } else if slack < 20 {
            score -= 2.0;
        }
    }

    // Perfect closure / small leftovers.
    if post_residual == 0 {
        score -= 24.0;
    } else if post_residual < 10 {
        score += 9.0 + 2.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Dead-space risk: quadratic waste penalty scaled by wasted fraction.
    if nxt > 0.0 && post > 0.0 && post < nxt {
        let waste_frac = (nxt - post) / nxt;
        score += 0.5 * (nxt - post).min(cap)
            + 4.0
            + 3.0 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.0 * waste_frac * (1.0 - progress);
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Void fraction, graded harder for large voids.
    let void_frac = post / resid;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.5 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 8.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 1.5;
    }

    // Opening cost for a brand-new bin.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 6.0 + 3.0 * progress;
        } else if pressure < 0.45 {
            score += 1.0 + 3.0 * progress;
        } else {
            score += 8.0 + 5.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.05;

    // Chain closure: residual exactly matches next item size.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 2.5 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.0;
    }

    // Endgame tightening.
    if progress > 0.85 && is_new_bin {
        score += 6.0 * (progress - 0.85) / 0.15;
    }

    // Snug fit, graded.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        if snug < 5.0 {
            score -= 2.5;
        }
        if snug < 15.0 {
            score -= 1.0 * (1.0 - snug / 15.0);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
    }

    // Dead-space ratio penalty, graded.
    if post > mean && cap > 0.0 {
        let excess_ratio = (post - mean) / cap;
        if excess_ratio > 0.15 {
            score += 2.0 * excess_ratio + 4.0 * (excess_ratio - 0.15);
        }
    }

    // Reusable-void check.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin via residual tiebreak.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // New-bin gate: open a fresh bin only when fits elsewhere are poor.
    if is_new_bin && nxt > 0.0 {
        let fits_poorly = fitting_bins_count > 0 && (bin_capacity as f64 - mean) > item_size as f64 * 1.5;
        if fits_poorly {
            score -= 3.0;
        }
    }

    // Depth-2 lookahead: small residual matching a future item class.
    if nxt > 0.0 && post_residual >= next_item_size {
        let two_left = post_residual - next_item_size;
        if two_left > 0 && two_left <= 10 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Exact-fit chain: post residual equals next item size with a small item.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size && next_item_size <= item_size {
        score -= 3.0 * (1.0 - progress);
    }

    // Mutation F: lookahead-aware dead-space hedge (sharpened weight).
    if nxt > 0.0 && !is_new_bin && post_residual < next_item_size && progress > 0.1 {
        let unusable = (next_item_size - post_residual) as f64;
        score += 0.75 * unusable * (1.0 - progress);
    }

    // Mutation G: residual homogeneity.
    if !is_new_bin && mean > 0.0 {
        let hom = ((post - mean).abs() / cap) as f64;
        score -= 0.8 * (1.0 - hom.min(1.0));
    }

    // Mutation H: dead-space ratio refinement vs fleet-average leftover fraction.
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let post_frac = post / cap;
        let mean_frac = (mean / cap).min(1.0);
        if post_frac > mean_frac {
            score += 3.5 * (post_frac - mean_frac) * (1.0 - 0.4 * progress);
        } else {
            score -= 1.2 * (mean_frac - post_frac);
        }
    }

    // Mutation I: anti-fragmentation sweep on large usable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let usable_left = post_residual - next_item_size;
        if usable_left > 25 {
            score += 0.06 * (usable_left as f64 - 25.0);
        }
    }

    // Mutation J: refillability-weighted leftover valuation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Mutation K: convex shortfall penalty for near-miss lookahead.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 15.0 {
            score += (2.5 - shortfall * 0.15) * (1.0 + 0.5 * progress);
        }
    }

    // Mutation L: asymmetric quadratic dead-space bump (peak 0.38 of capacity).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.38;
        let skew = if x < peak { 0.7 } else { 1.45 };
        let bump = (x - peak) * (x - peak);
        let ramp = if progress > 0.25 { 1.0 + 0.6 * (progress - 0.25) } else { 0.85 + 0.6 * progress };
        score += 15.0 * skew * bump * ramp;
    }

    // Mutation M: lookahead-aware new-bin arbitration.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let open_can_chain = fitting_bins_count > 0
            && mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        let new_can_chain = new_post >= nxt;
        if open_can_chain && !new_can_chain {
            score += 5.0 + 3.0 * (1.0 - progress);
        } else if !open_can_chain && new_can_chain {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Mutation N: utilization-maximizing tiebreak.
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Mutation O: two-step closure ladder.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 {
            let closeness = 1.0 - (after / cap).min(1.0);
            score -= 3.0 * closeness * closeness * (0.6 + 0.8 * progress);
        }
    }

    // Mutation P: fleet-aware dead-space cap.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Mutation T (refined gen 26): dead-space bump sharpened toward 0.30 of capacity.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak2 = 0.30;
        let skew2 = if x < peak2 { 0.6 } else { 1.7 };
        let bump2 = (x - peak2) * (x - peak2);
        score += 6.0 * skew2 * bump2 * (1.0 + 1.4 * progress);
    }

    // Mutation U: exact-closure ladder — reward small closable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 15 {
            score -= 2.0 * (1.0 - after as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
    }

    // Mutation V: new-bin exact-chain gate.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if (new_post - nxt).abs() < 1.0 {
            score -= 4.0 * (1.0 - progress);
        } else if new_post < nxt && progress > 0.5 {
            score += 2.5 * (progress - 0.5) / 0.5;
        }
    }

    // Mutation W (gen 26): dead-space ratio diagnostic — convex penalty for
    // post-lookahead leftover fraction exceeding the fleet mean.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.05 {
            score += 4.5 * (excess_frac - 0.05) * (excess_frac - 0.05) / (excess_frac + 0.05) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation X (gen 26): complementarity bonus.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_sum = after + mean;
        let pair_frac = pair_sum / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation Y (gen 26): lookahead-fit calibration.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation Z (gen 26): waste-shape guard — awkward middle band 16..=29.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AA (gen 29): dead-space bump peak at 0.26 with progress-adaptive skew.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak3 = 0.26;
        let skew3 = if x < peak3 { 0.55 } else { 1.9 };
        let bump3 = (x - peak3) * (x - peak3);
        score += 5.0 * skew3 * bump3 * (0.8 + 1.6 * progress);
    }

    // Mutation AB (gen 29): fleet-mean residual-shape alignment.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let dev = (after - mean) / cap;
        if dev < 0.0 {
            score -= 1.4 * (-dev) * (1.0 - 0.5 * progress);
        } else {
            score += 0.7 * dev * dev * cap.min(100.0) / 10.0;
        }
    }

    // Mutation AC (gen 29): lookahead-complement pairing.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let diff = (after as f64 - item_size as f64).abs();
        if diff <= 6.0 && after > 0 {
            score -= (2.2 - diff * 0.25) * (0.5 + 0.9 * progress);
        }
    }

    // Mutation AD (gen 29): new-bin dead-space preemption.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let after_new = new_post - nxt;
        if after_new >= 16.0 && after_new <= 34.0 {
            score += 2.5 * (1.0 - (after_new - 16.0) / 18.0) * (0.4 + 0.8 * progress);
        } else if after_new > 0.0 && after_new < 8.0 {
            score -= 1.5 * (1.0 - progress);
        }
    }

    // Mutation AE (gen 29): residual-variance dampener.
    if !is_new_bin && mean > 0.0 {
        let spread = (mean / cap - 0.25).abs();
        if spread > 0.10 {
            let snug2 = (bin_residual - item_size) as f64;
            if snug2 >= 0.0 && snug2 < 10.0 {
                score -= 1.1 * spread * (1.0 - snug2 / 10.0) * (0.6 + 0.6 * progress);
            }
        }
    }

    // Mutation AF (gen 36, Combine): dead-space minimization pivot — instead
    // of chasing a fixed bump peak, directly reward minimizing the post-
    // lookahead leftover fraction relative to the fleet mean, coupling
    // fine-grained residual fitting with lookahead anticipation. The
    // diagnosed weakness is suboptimal residual space, so steer toward
    // bins whose post-lookahead leftover is the smallest available.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let rel = after / mean.max(1.0);
        if rel < 1.0 {
            score -= 2.0 * (1.0 - rel) * (0.6 + 0.8 * progress);
        } else if rel > 1.6 {
            score += 1.5 * (rel - 1.6).min(2.0) * (0.5 + 0.5 * progress);
        }
    }

    // Mutation AG (gen 36): three-step chain anticipation — when the leftover
    // after the next item is itself a plausible future item (small), reward
    // the bin strongly since it can close completely in three placements.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 12 && progress > 0.4 {
            score -= 3.0 * (1.0 - after as f64 / 12.0) * progress;
        }
    }

    // Mutation AH (gen 36): new-bin restraint — when any open bin can fit the
    // item with a snug margin, make the fresh bin less attractive so we
    // consolidate rather than fragment.
    if is_new_bin && fitting_bins_count > 0 {
        let snugness = ((bin_capacity as f64 - mean) - item_size as f64).abs();
        if snugness <= 10.0 {
            score += 3.0 * (1.0 - snugness / 10.0) * (1.0 - 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Base: two-step waste — leftover after ideally seating the lookahead item too.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Perfect closure / small leftovers.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score += 14.0 + 3.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 5.0;
    } else {
        let post_class = (post_residual * 10 + bin_capacity / 2) / bin_capacity;
        if post_class >= 7 {
            score -= 4.0;
        }
    }

    // Aggressive exact two-step match.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 25.0 + 8.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 10.0;
        } else if slack < 20 {
            score -= 4.0;
        }
    } else if nxt > 0.0 && post > 0.0 && post < nxt {
        let waste_frac = (nxt - post) / nxt;
        score += 0.6 * (nxt - post).min(cap)
            + 7.0
            + 3.5 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.5 * waste_frac * (1.0 - progress);
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Void fraction, graded harder for large voids.
    let void_frac = post / resid;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.8 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 18.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 2.5;
    }

    // New-bin candidate arbitration.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 10.0 + 4.0 * progress;
        } else if pressure < 0.45 {
            score += 2.0 + 4.0 * progress;
        } else {
            score += 10.0 + 6.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
        if progress > 0.85 {
            score += 6.0 * (progress - 0.85) / 0.15;
        }
        // Lookahead-aware opening gate.
        if nxt > 0.0 {
            let new_post = cap - item_size as f64;
            let open_can_chain = fitting_bins_count > 0
                && mean >= item_size as f64
                && (mean - item_size as f64) >= nxt;
            let new_can_chain = new_post >= nxt;
            if open_can_chain && !new_can_chain {
                score += 5.0 + 3.0 * (1.0 - progress);
            } else if !open_can_chain && new_can_chain {
                score -= 2.5 * (1.0 - progress);
            }
            if (new_post - nxt).abs() < 1.0 {
                score -= 4.0 * (1.0 - progress);
            } else if new_post < nxt && progress > 0.5 {
                score += 2.5 * (progress - 0.5) / 0.5;
            }
        }
        if open_bins_count > 8 {
            let frag = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
            score += 0.9 * frag * (0.4 + 0.6 * progress);
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.15;

    // Chain closure.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 3.0 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.5;
    }

    // Progress-adaptive snugness.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        let band = 20.0 - 10.0 * progress;
        if snug < band {
            score -= 1.8 * (1.0 - snug / band) * (0.5 + progress);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
        if second_left as f64 == nxt || second_left as f64 == item_size as f64 {
            score -= 3.5 + 2.5 * (1.0 - progress);
        } else if (second_left as f64) >= nxt.min(item_size as f64) && second_left < 2 * next_item_size {
            score -= 1.0 * (1.0 - 0.5 * progress);
        }
        if second_left > 0 && second_left <= 15 {
            score -= 2.2 * (1.0 - second_left as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
        if second_left > 25 {
            score += 0.06 * (second_left as f64 - 25.0);
        }
    }

    // Dead-space ratio penalty vs fleet-average leftover fraction.
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let post_frac = post / cap;
        let mean_frac = (mean / cap).min(1.0);
        if post_frac > mean_frac {
            score += 4.0 * (post_frac - mean_frac) * (1.0 - 0.4 * progress);
        } else {
            score -= 1.2 * (mean_frac - post_frac);
        }
    }

    // Reusable-void valuation.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // Sharpened dead-space hedge for near-miss lookahead.
    if nxt > 0.0 && !is_new_bin && post_residual < next_item_size && progress > 0.1 {
        let unusable = (next_item_size - post_residual) as f64;
        if unusable <= 15.0 {
            score += (2.5 - unusable * 0.15) * (1.0 + 0.5 * progress);
        } else {
            score += 0.75 * unusable * (1.0 - progress);
        }
    }

    // Residual homogeneity bonus.
    if !is_new_bin && mean > 0.0 {
        let hom = ((post - mean).abs() / cap) as f64;
        score -= 0.8 * (1.0 - hom.min(1.0));
    }

    // Asymmetric dead-space bump on post-lookahead leftover fraction.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.30;
        let skew = if x < peak { 0.6 } else { 1.6 };
        let bump = (x - peak) * (x - peak);
        score += 9.0 * skew * bump * (1.0 + 1.2 * progress);
    }

    // Fleet-aware dead-space cap.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Refillability-weighted leftover valuation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Mid-band dead-space penalty on post-lookahead leftover (30-60 range).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 30 && after <= 60 && progress > 0.3 {
            score += 1.8 * (progress - 0.3) / 0.7;
        }
    }

    // Two-step closure ladder — reward small closable leftovers harder.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 {
            let closeness = 1.0 - (after / cap).min(1.0);
            score -= 3.0 * closeness * closeness * (0.6 + 0.8 * progress);
        }
    }

    // Mutation A (gen 30): convex excess-fraction penalty vs fleet mean.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.05 {
            score += 4.5 * (excess_frac - 0.05) * (excess_frac - 0.05) / (excess_frac + 0.05) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation B (gen 30): complementarity bonus.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_frac = (after + mean) / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation C (gen 30): awkward-middle-band guard (16..=29 leftovers).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation D (gen 30): late-stream exact-fill escalation.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation E (gen 30): dual-threshold new-bin gate.
    if is_new_bin && nxt > 0.0 && fitting_bins_count > 0 {
        let best_chain_possible = mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        if !best_chain_possible && open_bins_count as f64 * (mean / cap) > 2.5 {
            score -= 1.5 * (1.0 - progress);
        }
    }

    // Mutation F (gen 34): three-item chain anticipation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let third = mean.max(1.0);
        if after >= third {
            let closeness = 1.0 - ((after - third) / cap).min(1.0);
            score -= 2.0 * closeness * closeness * (0.5 + 0.9 * progress);
        } else if after > 0.0 && third - after <= 8.0 {
            score += 1.0 * (1.0 - (third - after) / 8.0) * (0.4 + 0.8 * progress);
        }
    }

    // Mutation G (gen 34): bin-choice diversity hedge.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let target = mean * 0.5;
        let dev = (after - target).abs() / cap;
        score += 1.4 * dev * (0.6 + 0.8 * progress);
    }

    // Mutation H (gen 34): late-stream consolidation escalation.
    if is_new_bin && progress > 0.6 && fitting_bins_count > 0 {
        score += 4.0 * (progress - 0.6) / 0.4 * (1.0 + (fitting_bins_count as f64).min(5.0) * 0.2);
    }

    // Mutation I (gen 34): exact two-item closure with parity coupling.
    if !is_new_bin && nxt > 0.0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if item_size > 0 && after % item_size == 0 && after / item_size >= 2 {
            score -= 2.5 * (1.0 - 0.3 * progress);
        }
    }

    // Mutation J (gen 35): dead-space minimization core.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 && after < mean * 0.5 {
            score += 2.2 * (1.0 - after / (mean * 0.5)) * (0.6 + 0.9 * progress);
        } else if (after - mean).abs() < 1.0 {
            score -= 3.0 * (1.0 - 0.4 * progress);
        }
    }

    // Mutation K (gen 35): dual-item lookahead coupling.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let small_class = (item_size / 2).max(1);
        if after >= small_class && after - small_class < small_class {
            score -= 1.6 * (1.0 - 0.5 * progress);
        } else if after > 0 && after < small_class && after < 6 {
            score += 1.1 * (1.0 - after as f64 / 6.0);
        }
    }

    // Mutation L (gen 35): residual-space packing slope.
    if !is_new_bin && nxt > 0.0 {
        if post_residual >= next_item_size {
            let after = (post_residual - next_item_size) as f64;
            score += 0.11 * after * (0.3 + 0.7 * progress);
            if after == 0 {
                score -= 4.0 + 3.0 * progress;
            }
        } else {
            let stranded = post as f64;
            score += 0.14 * stranded * (0.2 + 0.8 * progress);
        }
    }

    // Mutation M (gen 35): new-bin dead-space floor.
    if is_new_bin && nxt > 0.0 && fitting_bins_count > 0 {
        let new_post = cap - item_size as f64;
        if new_post >= nxt {
            let new_after = new_post - nxt;
            if new_after > cap * 0.55 {
                score += 2.0 * (new_after / cap) * (0.5 + progress);
            } else if new_after < cap * 0.12 {
                score -= 1.6 * (1.0 - progress);
            }
        }
    }

    // Mutation N (gen 37): graded dead-space tax — replace flat slope with a
    // convex tax on the post-lookahead leftover so mid-size stranded voids
    // (the diagnosed weakness) are penalized harder than tiny closable ones,
    // while exact-closure bins keep a strong rebate.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 {
            let frac = (after / cap).min(1.0);
            score += 5.5 * frac * frac * (0.4 + 0.9 * progress);
        }
    }

    // Mutation O (gen 37): chain-completion triple match — reward bins whose
    // residual exactly equals item+next sum (guaranteed two-step closure).
    if !is_new_bin && nxt > 0.0 && bin_residual as f64 == item_size as f64 + nxt {
        score -= 6.0 * (1.0 - 0.3 * progress);
    }

    // Mutation P (gen 37): fleet-relative snug arbitration — when several bins
    // fit, prefer the one whose post-lookahead leftover best matches the
    // fleet mean (statistically most refutable), penalizing outliers harder
    // late in the stream where recovery options vanish.
    if !is_new_bin && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let rel = (after - mean).abs() / mean.max(1.0);
        score += 1.6 * rel * rel * (0.3 + 0.9 * progress);
    }

    // Mutation Q (gen 37): new-bin anti-fragmentation escalation — open fresh
    // bins only when the fleet cannot absorb the item AND the new bin's own
    // leftover would be immediately reusable by the next item class.
    if is_new_bin && nxt > 0.0 && fitting_bins_count > 0 && progress > 0.4 {
        let new_post = cap - item_size as f64;
        if new_post < nxt {
            score += 3.5 * (progress - 0.4) / 0.6;
        } else if (new_post - nxt) > cap * 0.5 && mean > 0.0 && mean >= item_size as f64 {
            score += 2.0 * (progress - 0.4) / 0.6;
        }
    }

    // Mutation R (gen 37): endgame exactness — sharpen the reward for leaving
    // residuals that exactly match the mean item class in the final stretch,
    // where every stranded crumb is unrecoverable.
    if !is_new_bin && mean > 0.0 && progress > 0.75 {
        let diff = (post - mean.round()).abs();
        if diff < 1.0 {
            score -= 3.5 * (progress - 0.75) / 0.25;
        } else if post > 0.0 && post < mean * 0.4 {
            score += 2.5 * (progress - 0.75) / 0.25;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual

    // Base: prefer small post residual, with non-linear shaping.
    let mut score = x * x * cap + 0.5 * post;

    // Smooth polynomial coupling of post residual with stream progress:
    // early on, waste is cheap; later, tight fits matter more.
    let coupling = 30.0 * progress * (1.0 - x) * (1.0 - x);
    score -= coupling;

    // Penalize dead space that cannot fit the next item (smooth quadratic in gap).
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).max(0.0);
        score += 0.35 * gap * gap / cap;
        // Reward leaving exactly enough room for the next item.
        let fit_err = (post - next_item_size as f64).abs();
        score -= 12.0 * (1.0 - fit_err / cap).max(0.0);
    }

    // Last-chance bonus: strongly favor the only bin that fits, smoothly scaled by progress.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild preference for bins below mean residual (balance residuals), smooth.
    score += 0.08 * (post - mean_residual);

    // Slight pressure against accumulating many open bins late in the stream.
    score += 0.02 * open_bins_count as f64 * progress;

    // New-bin candidate: make it unattractive unless it beats a genuinely poor fit.
    if bin_residual == bin_capacity && bin_residual >= item_size {
        score += 18.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Two-step waste base.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Aggressive exact two-step match.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 12.0 + 6.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 5.0;
        } else if slack < 20 {
            score -= 2.0;
        }
    }

    // Perfect closure / small leftovers.
    if post_residual == 0 {
        score -= 24.0;
    } else if post_residual < 10 {
        score += 9.0 + 2.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Dead-space risk: quadratic waste penalty scaled by wasted fraction.
    if nxt > 0.0 && post > 0.0 && post < nxt {
        let waste_frac = (nxt - post) / nxt;
        score += 0.5 * (nxt - post).min(cap)
            + 4.0
            + 3.0 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.0 * waste_frac * (1.0 - progress);
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Void fraction, graded harder for large voids.
    let void_frac = post / resid;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.5 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 8.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 1.5;
    }

    // Opening cost for a brand-new bin.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 6.0 + 3.0 * progress;
        } else if pressure < 0.45 {
            score += 1.0 + 3.0 * progress;
        } else {
            score += 8.0 + 5.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.05;

    // Chain closure: residual exactly matches next item size.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 2.5 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.0;
    }

    // Endgame tightening.
    if progress > 0.85 && is_new_bin {
        score += 6.0 * (progress - 0.85) / 0.15;
    }

    // Snug fit, graded.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        if snug < 5.0 {
            score -= 2.5;
        }
        if snug < 15.0 {
            score -= 1.0 * (1.0 - snug / 15.0);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
    }

    // Dead-space ratio penalty, graded.
    if post > mean && cap > 0.0 {
        let excess_ratio = (post - mean) / cap;
        if excess_ratio > 0.15 {
            score += 2.0 * excess_ratio + 4.0 * (excess_ratio - 0.15);
        }
    }

    // Reusable-void check.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin via residual tiebreak.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // New-bin gate: open a fresh bin only when fits elsewhere are poor.
    if is_new_bin && nxt > 0.0 {
        let fits_poorly = fitting_bins_count > 0 && (bin_capacity as f64 - mean) > item_size as f64 * 1.5;
        if fits_poorly {
            score -= 3.0;
        }
    }

    // Depth-2 lookahead: small residual matching a future item class.
    if nxt > 0.0 && post_residual >= next_item_size {
        let two_left = post_residual - next_item_size;
        if two_left > 0 && two_left <= 10 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Exact-fit chain: post residual equals next item size with a small item.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size && next_item_size <= item_size {
        score -= 3.0 * (1.0 - progress);
    }

    // Mutation F: lookahead-aware dead-space hedge (sharpened weight).
    if nxt > 0.0 && !is_new_bin && post_residual < next_item_size && progress > 0.1 {
        let unusable = (next_item_size - post_residual) as f64;
        score += 0.75 * unusable * (1.0 - progress);
    }

    // Mutation G: residual homogeneity.
    if !is_new_bin && mean > 0.0 {
        let hom = ((post - mean).abs() / cap) as f64;
        score -= 0.8 * (1.0 - hom.min(1.0));
    }

    // Mutation H: dead-space ratio refinement vs fleet-average leftover fraction.
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let post_frac = post / cap;
        let mean_frac = (mean / cap).min(1.0);
        if post_frac > mean_frac {
            score += 3.5 * (post_frac - mean_frac) * (1.0 - 0.4 * progress);
        } else {
            score -= 1.2 * (mean_frac - post_frac);
        }
    }

    // Mutation I: anti-fragmentation sweep on large usable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let usable_left = post_residual - next_item_size;
        if usable_left > 25 {
            score += 0.06 * (usable_left as f64 - 25.0);
        }
    }

    // Mutation J: refillability-weighted leftover valuation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Mutation K: convex shortfall penalty for near-miss lookahead.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 15.0 {
            score += (2.5 - shortfall * 0.15) * (1.0 + 0.5 * progress);
        }
    }

    // Mutation L: asymmetric quadratic dead-space bump (peak 0.38 of capacity).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.38;
        let skew = if x < peak { 0.7 } else { 1.45 };
        let bump = (x - peak) * (x - peak);
        let ramp = if progress > 0.25 { 1.0 + 0.6 * (progress - 0.25) } else { 0.85 + 0.6 * progress };
        score += 15.0 * skew * bump * ramp;
    }

    // Mutation M: lookahead-aware new-bin arbitration.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let open_can_chain = fitting_bins_count > 0
            && mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        let new_can_chain = new_post >= nxt;
        if open_can_chain && !new_can_chain {
            score += 5.0 + 3.0 * (1.0 - progress);
        } else if !open_can_chain && new_can_chain {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Mutation N: utilization-maximizing tiebreak.
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Mutation O: two-step closure ladder.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 {
            let closeness = 1.0 - (after / cap).min(1.0);
            score -= 3.0 * closeness * closeness * (0.6 + 0.8 * progress);
        }
    }

    // Mutation P: fleet-aware dead-space cap.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Mutation Q: two-deep chain reward + mid-band dead-space penalty.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 == nxt || after as f64 == item_size as f64 {
            score -= 3.5 + 2.5 * (1.0 - progress);
        } else if (after as f64) >= nxt.min(item_size as f64) && after < 2 * next_item_size {
            score -= 1.0 * (1.0 - 0.5 * progress);
        }
        if after >= 30 && after <= 60 && progress > 0.3 {
            score += 1.8 * (progress - 0.3) / 0.7;
        }
    }

    // Mutation R: progress-adaptive snugness.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        let band = 20.0 - 10.0 * progress;
        if snug < band {
            score -= 1.6 * (1.0 - snug / band) * (0.5 + progress);
        }
    }

    // Mutation S: new-bin saturation hedge.
    if is_new_bin && open_bins_count > 8 {
        let frag = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
        score += 0.9 * frag * (0.4 + 0.6 * progress);
    }

    // Mutation T (gen 37 refinement): dead-space bump peak tuned to 0.28 of
    // capacity with stronger late-stream scaling and steeper right-side skew,
    // continuing the diagnosed dead-space-ratio improvement direction.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak2 = 0.28;
        let skew2 = if x < peak2 { 0.55 } else { 1.85 };
        let bump2 = (x - peak2) * (x - peak2);
        score += 7.5 * skew2 * bump2 * (1.0 + 1.6 * progress);
    }

    // Mutation U: exact-closure ladder — reward small closable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 15 {
            score -= 2.0 * (1.0 - after as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
    }

    // Mutation V: new-bin exact-chain gate.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if (new_post - nxt).abs() < 1.0 {
            score -= 4.0 * (1.0 - progress);
        } else if new_post < nxt && progress > 0.5 {
            score += 2.5 * (progress - 0.5) / 0.5;
        }
    }

    // Mutation W (gen 37): dead-space ratio diagnostic — sharpened threshold
    // from 0.05 to 0.035 and slightly stronger late-stream weight, continuing
    // the successful convex-excess penalty against fleet-mean drift.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.035 {
            score += 5.0 * (excess_frac - 0.035) * (excess_frac - 0.035) / (excess_frac + 0.035) * (0.7 + 0.7 * progress);
        }
    }

    // Mutation X: complementarity bonus — reward bins whose leftover
    // after seating the item complements the fleet-average residual so the
    // pair of leftovers is jointly more fillable by mid-size items.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_sum = after + mean;
        let pair_frac = pair_sum / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation Y: lookahead-fit calibration — when the next item
    // would exactly fill the post-residual, escalate the reward late in the
    // stream where closure value is highest.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation Z (gen 37 refinement): waste-shape guard — narrowed awkward
    // middle band (14..=27) with slightly stronger weight, targeting the
    // residual shapes the diagnosed weakness accumulates.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 14 && after <= 27 {
            score += 1.5 * (1.0 - (after - 14) as f64 / 13.0) * (0.5 + 0.8 * progress);
        }
    }

    // Mutation AA (new, gen 37): residual-bucket lookahead — reward bins whose
    // post-lookahead leftover matches a common small-item bucket (multiples of
    // 10 or 25/50/75/100 complements), improving future fill probability.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 {
            let bucket_bonus = if after % 25 == 0 {
                2.5
            } else if after % 10 == 0 {
                1.8
            } else if after % 5 == 0 {
                0.9
            } else {
                0.0
            };
            score -= bucket_bonus * (0.5 + 0.5 * (1.0 - progress));
        }
    }

    // Mutation AB (new, gen 37): late-stream consolidation gate — late in the
    // stream, penalize spreading across many open bins; prefer deepest fits.
    if !is_new_bin && progress > 0.7 && open_bins_count > 6 {
        let depth = 1.0 - (bin_residual as f64 / cap);
        score += 1.2 * depth * (progress - 0.7) / 0.3;
    }

    // Mutation AC (new, gen 37): new-bin residual target shaping — when opening
    // a fresh bin, favor item sizes whose resulting residual pairs well with
    // the fleet mean (residual + mean near capacity), else mild penalty.
    if is_new_bin && nxt > 0.0 && mean > 0.0 {
        let new_post = cap - item_size as f64;
        let pair = (new_post + mean) / cap;
        if (pair - 1.0).abs() < 0.1 {
            score -= 2.0 * (1.0 - (pair - 1.0).abs() / 0.1) * (1.0 - 0.3 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" residue classes (multiples of small harmonics) are preferred.
    let pr = post_residual;
    if pr > 0 {
        // Dead-space penalty grows when post_residual is awkwardly small
        // (cannot host even the smallest plausible item, ~10).
        if pr < 10 {
            score += 60.0;
        } else if pr <= 20 {
            score -= 8.0; // tight but likely reusable
        }

        // Harmonic divisibility rewards: leftover divisible by 10/20/25/50
        // pairs well with typical item granularities.
        if pr % 10 == 0 {
            score -= 12.0;
            if pr % 50 == 0 {
                score -= 6.0;
            } else if pr % 20 == 0 {
                score -= 3.0;
            }
        } else if pr % 25 == 0 {
            score -= 7.0;
        } else {
            // Non-harmonic leftover: penalize by how far from nearest multiple of 10.
            let r = (pr % 10) as f64;
            score += r * r * 0.15;
        }

        // Integer-division thresholds: leftover in mid-range bands is wasteful
        // if it can't hold two future items but holds one awkwardly.
        let band = pr / 25; // 0..=4 harmonic band
        match band {
            0 => score += 15.0, // 1..24: near-dead space
            1 => score += 2.0,  // 25..49
            2 => score -= 3.0,  // 50..74: versatile
            3 => score -= 5.0,  // 75..99: very reusable
            _ => {}
        }
    }

    // Lookahead coupling: does the next item fit in the resulting residual?
    if next_item_size > 0 && pr >= next_item_size {
        // Exact-fit lookahead is highly desirable.
        if pr == next_item_size {
            score -= 20.0;
        } else {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0;
            score -= slack * 0.1;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here after placement; mildly penalize unless
        // this placement leaves a harmonic multiple.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a new bin is only attractive when current
    // open bins are congested (few fitting bins) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = (fitting_bins_count as f64).max(1.0);
        score = 55.0 + 40.0 * (1.0 - progress) - 12.0 / congestion;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // big-next-item: fresh bin may help chain
        }
    }

    // Mild preference to fill bins deeper than the mean residual
    // (balance load, close out bins).
    score -= (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Two-step waste base.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Aggressive exact two-step match.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 12.0 + 6.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 5.0;
        } else if slack < 20 {
            score -= 2.0;
        }
    }

    // Perfect closure / small leftovers.
    if post_residual == 0 {
        score -= 24.0;
    } else if post_residual < 10 {
        score += 9.0 + 2.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Dead-space risk: quadratic waste penalty scaled by wasted fraction.
    if nxt > 0.0 && post > 0.0 && post < nxt {
        let waste_frac = (nxt - post) / nxt;
        score += 0.5 * (nxt - post).min(cap)
            + 4.0
            + 3.0 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.0 * waste_frac * (1.0 - progress);
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Void fraction, graded harder for large voids.
    let void_frac = post / resid;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.5 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 8.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 1.5;
    }

    // Opening cost for a brand-new bin.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 6.0 + 3.0 * progress;
        } else if pressure < 0.45 {
            score += 1.0 + 3.0 * progress;
        } else {
            score += 8.0 + 5.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.05;

    // Chain closure: residual exactly matches next item size.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 2.5 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.0;
    }

    // Endgame tightening.
    if progress > 0.85 && is_new_bin {
        score += 6.0 * (progress - 0.85) / 0.15;
    }

    // Snug fit, graded.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        if snug < 5.0 {
            score -= 2.5;
        }
        if snug < 15.0 {
            score -= 1.0 * (1.0 - snug / 15.0);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
    }

    // Dead-space ratio penalty, graded.
    if post > mean && cap > 0.0 {
        let excess_ratio = (post - mean) / cap;
        if excess_ratio > 0.15 {
            score += 2.0 * excess_ratio + 4.0 * (excess_ratio - 0.15);
        }
    }

    // Reusable-void check.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin via residual tiebreak.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // New-bin gate: open a fresh bin only when fits elsewhere are poor.
    if is_new_bin && nxt > 0.0 {
        let fits_poorly = fitting_bins_count > 0 && (bin_capacity as f64 - mean) > item_size as f64 * 1.5;
        if fits_poorly {
            score -= 3.0;
        }
    }

    // Depth-2 lookahead: small residual matching a future item class.
    if nxt > 0.0 && post_residual >= next_item_size {
        let two_left = post_residual - next_item_size;
        if two_left > 0 && two_left <= 10 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Exact-fit chain: post residual equals next item size with a small item.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size && next_item_size <= item_size {
        score -= 3.0 * (1.0 - progress);
    }

    // Mutation F: lookahead-aware dead-space hedge (sharpened weight).
    if nxt > 0.0 && !is_new_bin && post_residual < next_item_size && progress > 0.1 {
        let unusable = (next_item_size - post_residual) as f64;
        score += 0.75 * unusable * (1.0 - progress);
    }

    // Mutation G: residual homogeneity.
    if !is_new_bin && mean > 0.0 {
        let hom = ((post - mean).abs() / cap) as f64;
        score -= 0.8 * (1.0 - hom.min(1.0));
    }

    // Mutation H: dead-space ratio refinement vs fleet-average leftover fraction.
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let post_frac = post / cap;
        let mean_frac = (mean / cap).min(1.0);
        if post_frac > mean_frac {
            score += 3.5 * (post_frac - mean_frac) * (1.0 - 0.4 * progress);
        } else {
            score -= 1.2 * (mean_frac - post_frac);
        }
    }

    // Mutation I: anti-fragmentation sweep on large usable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let usable_left = post_residual - next_item_size;
        if usable_left > 25 {
            score += 0.06 * (usable_left as f64 - 25.0);
        }
    }

    // Mutation J: refillability-weighted leftover valuation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Mutation K: convex shortfall penalty for near-miss lookahead.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 15.0 {
            score += (2.5 - shortfall * 0.15) * (1.0 + 0.5 * progress);
        }
    }

    // Mutation L: asymmetric quadratic dead-space bump (peak 0.38 of capacity).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.38;
        let skew = if x < peak { 0.7 } else { 1.45 };
        let bump = (x - peak) * (x - peak);
        let ramp = if progress > 0.25 { 1.0 + 0.6 * (progress - 0.25) } else { 0.85 + 0.6 * progress };
        score += 15.0 * skew * bump * ramp;
    }

    // Mutation M: lookahead-aware new-bin arbitration.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let open_can_chain = fitting_bins_count > 0
            && mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        let new_can_chain = new_post >= nxt;
        if open_can_chain && !new_can_chain {
            score += 5.0 + 3.0 * (1.0 - progress);
        } else if !open_can_chain && new_can_chain {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Mutation N: utilization-maximizing tiebreak.
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Mutation O: two-step closure ladder.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 {
            let closeness = 1.0 - (after / cap).min(1.0);
            score -= 3.0 * closeness * closeness * (0.6 + 0.8 * progress);
        }
    }

    // Mutation P: fleet-aware dead-space cap.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Mutation Q: two-deep chain reward + mid-band dead-space penalty.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 == nxt || after as f64 == item_size as f64 {
            score -= 3.5 + 2.5 * (1.0 - progress);
        } else if (after as f64) >= nxt.min(item_size as f64) && after < 2 * next_item_size {
            score -= 1.0 * (1.0 - 0.5 * progress);
        }
        if after >= 30 && after <= 60 && progress > 0.3 {
            score += 1.8 * (progress - 0.3) / 0.7;
        }
    }

    // Mutation R: progress-adaptive snugness.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        let band = 20.0 - 10.0 * progress;
        if snug < band {
            score -= 1.6 * (1.0 - snug / band) * (0.5 + progress);
        }
    }

    // Mutation S: new-bin saturation hedge.
    if is_new_bin && open_bins_count > 8 {
        let frag = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
        score += 0.9 * frag * (0.4 + 0.6 * progress);
    }

    // Mutation T (gen 37 refinement): sharpen the dead-space bump peak toward
    // 0.28 of capacity with a tighter skew and stronger late-stream scaling.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak2 = 0.28;
        let skew2 = if x < peak2 { 0.55 } else { 1.85 };
        let bump2 = (x - peak2) * (x - peak2);
        score += 6.5 * skew2 * bump2 * (1.0 + 1.5 * progress);
    }

    // Mutation U: exact-closure ladder — reward small closable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 15 {
            score -= 2.0 * (1.0 - after as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
    }

    // Mutation V: new-bin exact-chain gate.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if (new_post - nxt).abs() < 1.0 {
            score -= 4.0 * (1.0 - progress);
        } else if new_post < nxt && progress > 0.5 {
            score += 2.5 * (progress - 0.5) / 0.5;
        }
    }

    // Mutation W: dead-space ratio diagnostic — convex penalty on excess
    // leftover fraction beyond the fleet mean.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.05 {
            score += 4.5 * (excess_frac - 0.05) * (excess_frac - 0.05) / (excess_frac + 0.05) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation X: complementarity bonus — reward leftovers that pair with the
    // fleet mean to jointly fill a bin.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_sum = after + mean;
        let pair_frac = pair_sum / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation Y: lookahead-fit calibration — escalate exact-fill reward late.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation Z: waste-shape guard — penalize the awkward middle band 16..=29.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AA (gen 37): dual-residual synergy — when the bin's leftover
    // after seating the item plus the next item's own leftover would sum near
    // a full capacity, strongly reward the chain (three-item closure probe).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let chain_frac = (after as f64 + nxt) / cap;
        if chain_frac >= 0.95 && chain_frac <= 1.05 {
            score -= 3.0 * (1.0 - 0.5 * progress);
        }
    }

    // Mutation AB (gen 37): dead-space entropy guard — penalize fitting into a
    // bin whose post-residual lands in the low-utility band just below the
    // next item size by a margin that scales with stream progress, while
    // granting a small bonus when the post-residual is an exact divisor match
    // for common item sizes (5/10 granularity) that future streams refill.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        if gap > 3.0 && gap <= 12.0 {
            score += 0.35 * gap * progress;
        }
    }

    // Mutation AC (gen 37): late-stream consolidation — when few items remain,
    // weight bins with the smallest absolute post-residual more heavily so the
    // final items seal bins instead of scattering.
    if progress > 0.8 && !is_new_bin && post_residual > 0 {
        score += 0.04 * post * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the minimum
    // item size (1) are not penalized as hard as "awkward" gaps, but any
    // gap below the typical item floor creates unusable slack.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        // Dead space penalty: the smaller the unusable gap, the worse.
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: discourage spreading across too many bins,
    // but only mildly, so tight fits still win.
    score += (open_bins_count as f64) * 0.35;

    // If this bin is the last chance to fit, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // More attractive when existing residuals are large/fragmented.
        score += mean_residual * 0.2;
        // Less attractive when few bins are open (reuse them instead).
        score -= (open_bins_count as f64) * 1.5;
        // If the next item fits better in a fresh bin, encourage opening.
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 20.0;
        }
    }

    // Lookahead coupling: reward leaving post_residual that can host the
    // next item exactly; penalize leaving a gap that just barely misses it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_leftover = post_residual - next_item_size;
            if next_leftover == 0 {
                score -= 20.0;
            } else if (next_leftover as f64) < dead_threshold {
                score -= 8.0;
            }
        } else if post_residual > 0 {
            // Gap too small for the next item: awkward residual.
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Two-step lookahead base: value the leftover after seating the next item too.
    let mut score = if nxt > 0.0 && post_residual >= next_item_size {
        (post_residual - next_item_size) as f64
    } else {
        post
    };

    // Exact two-step closure.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 18.0 + 8.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 10.0;
        } else if slack < 10 {
            score -= 6.0;
        } else if slack < 20 {
            score -= 2.0;
        }
        // Deep chain: leftover after next item still matches item class.
        if slack >= 1 && slack as u32 <= item_size {
            score -= 2.0 * (1.0 - progress);
        }
        // Penalize awkward middle-band leftovers (16..=29) that resist reuse.
        if slack >= 16 && slack <= 29 {
            score += 1.5 * (1.0 - (slack - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
        // Convex bump around 0.30 of capacity for post-chain leftover.
        let x = (slack as f64 / cap).min(1.0);
        let peak = 0.30;
        let skew = if x < peak { 0.6 } else { 1.7 };
        score += 6.0 * skew * (x - peak) * (x - peak) * (1.0 + 1.4 * progress);
    }

    // Perfect closure / small leftovers are hard to reuse.
    if post_residual == 0 {
        score -= 26.0;
    } else if post_residual < 10 {
        score += 10.0 + 3.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 3.5;
    }

    // Dead-space risk: leftover cannot host the next item.
    if nxt > 0.0 && post_residual > 0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        let waste_frac = shortfall / nxt.max(1.0);
        score += 0.5 * shortfall.min(cap)
            + 4.0
            + 3.0 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.0 * waste_frac * (1.0 - progress);
        // Near-miss convex hedge.
        if shortfall <= 15.0 {
            score += (2.5 - shortfall * 0.15) * (1.0 + 0.5 * progress);
        }
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Void fraction, graded harder for large voids.
    let void_frac = post / (bin_residual.max(1) as f64);
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.5 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 9.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 1.5;
    }

    // New-bin arbitration: open only under pressure or when open fits chain poorly.
    if is_new_bin {
        let pressure = mean / cap;
        let new_post = cap - item_size as f64;
        if pressure < 0.22 {
            score -= 7.0 + 3.0 * progress;
        } else if pressure < 0.45 {
            score += 1.0 + 3.0 * progress;
        } else {
            score += 8.0 + 5.0 * progress;
        }
        if nxt > 0.0 {
            let open_can_chain = fitting_bins_count > 0 && mean >= item_size as f64 && (mean - item_size as f64) >= nxt;
            let new_can_chain = new_post >= nxt;
            if open_can_chain && !new_can_chain {
                score += 5.0 + 3.0 * (1.0 - progress);
            } else if !open_can_chain && new_can_chain {
                score -= 2.5 * (1.0 - progress);
            }
        }
        // Endgame tightening.
        if progress > 0.85 {
            score += 6.0 * (progress - 0.85) / 0.15;
        }
        // Fragmentation hedge with many open bins.
        if open_bins_count > 8 {
            let frag = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
            score += 0.9 * frag * (0.4 + 0.6 * progress);
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.05;

    // Chain closure: residual exactly matches next item size.
    if !is_new_bin && nxt > 0.0 && bin_residual == next_item_size {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if !is_new_bin && nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 2.5 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.5;
    }

    // Progress-adaptive snugness.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        let band = 20.0 - 10.0 * progress;
        if snug < band {
            score -= 1.6 * (1.0 - snug / band) * (0.5 + progress);
        }
    }

    // Fragmentation guard: deviation from fleet mean.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // Refillability-weighted leftover valuation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Fleet-aware dead-space cap.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Utilization tiebreak.
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Base: two-step waste — leftover after ideally seating the lookahead item too.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Perfect closure / small leftovers.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score += 14.0 + 3.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 5.0;
    } else {
        let post_class = (post_residual * 10 + bin_capacity / 2) / bin_capacity;
        if post_class >= 7 {
            score -= 4.0;
        }
    }

    // Aggressive exact two-step match.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 25.0 + 8.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 10.0;
        } else if slack < 20 {
            score -= 4.0;
        }
    } else if nxt > 0.0 && post > 0.0 && post < nxt {
        let waste_frac = (nxt - post) / nxt;
        score += 0.6 * (nxt - post).min(cap)
            + 7.0
            + 3.5 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.5 * waste_frac * (1.0 - progress);
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Void fraction, graded harder for large voids.
    let void_frac = post / resid;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.8 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 18.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 2.5;
    }

    // New-bin candidate arbitration.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 10.0 + 4.0 * progress;
        } else if pressure < 0.45 {
            score += 2.0 + 4.0 * progress;
        } else {
            score += 10.0 + 6.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
        if progress > 0.85 {
            score += 6.0 * (progress - 0.85) / 0.15;
        }
        // Lookahead-aware opening gate.
        if nxt > 0.0 {
            let new_post = cap - item_size as f64;
            let open_can_chain = fitting_bins_count > 0
                && mean >= item_size as f64
                && (mean - item_size as f64) >= nxt;
            let new_can_chain = new_post >= nxt;
            if open_can_chain && !new_can_chain {
                score += 5.0 + 3.0 * (1.0 - progress);
            } else if !open_can_chain && new_can_chain {
                score -= 2.5 * (1.0 - progress);
            }
            if (new_post - nxt).abs() < 1.0 {
                score -= 4.0 * (1.0 - progress);
            } else if new_post < nxt && progress > 0.5 {
                score += 2.5 * (progress - 0.5) / 0.5;
            }
        }
        if open_bins_count > 8 {
            let frag = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
            score += 0.9 * frag * (0.4 + 0.6 * progress);
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.15;

    // Chain closure.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 3.0 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.5;
    }

    // Progress-adaptive snugness.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        let band = 20.0 - 10.0 * progress;
        if snug < band {
            score -= 1.8 * (1.0 - snug / band) * (0.5 + progress);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
        if second_left as f64 == nxt || second_left as f64 == item_size as f64 {
            score -= 3.5 + 2.5 * (1.0 - progress);
        } else if (second_left as f64) >= nxt.min(item_size as f64) && second_left < 2 * next_item_size {
            score -= 1.0 * (1.0 - 0.5 * progress);
        }
        if second_left > 0 && second_left <= 15 {
            score -= 2.2 * (1.0 - second_left as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
        if second_left > 25 {
            score += 0.06 * (second_left as f64 - 25.0);
        }
    }

    // Dead-space ratio penalty vs fleet-average leftover fraction.
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let post_frac = post / cap;
        let mean_frac = (mean / cap).min(1.0);
        if post_frac > mean_frac {
            score += 4.0 * (post_frac - mean_frac) * (1.0 - 0.4 * progress);
        } else {
            score -= 1.2 * (mean_frac - post_frac);
        }
    }

    // Reusable-void valuation.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // Sharpened dead-space hedge for near-miss lookahead.
    if nxt > 0.0 && !is_new_bin && post_residual < next_item_size && progress > 0.1 {
        let unusable = (next_item_size - post_residual) as f64;
        if unusable <= 15.0 {
            score += (2.5 - unusable * 0.15) * (1.0 + 0.5 * progress);
        } else {
            score += 0.75 * unusable * (1.0 - progress);
        }
    }

    // Residual homogeneity bonus.
    if !is_new_bin && mean > 0.0 {
        let hom = ((post - mean).abs() / cap) as f64;
        score -= 0.8 * (1.0 - hom.min(1.0));
    }

    // Asymmetric dead-space bump on post-lookahead leftover fraction.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.30;
        let skew = if x < peak { 0.6 } else { 1.6 };
        let bump = (x - peak) * (x - peak);
        score += 9.0 * skew * bump * (1.0 + 1.2 * progress);
    }

    // Fleet-aware dead-space cap.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Refillability-weighted leftover valuation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Mid-band dead-space penalty on post-lookahead leftover (30-60 range).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 30 && after <= 60 && progress > 0.3 {
            score += 1.8 * (progress - 0.3) / 0.7;
        }
    }

    // Two-step closure ladder — reward small closable leftovers harder.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 {
            let closeness = 1.0 - (after / cap).min(1.0);
            score -= 3.0 * closeness * closeness * (0.6 + 0.8 * progress);
        }
    }

    // Mutation A (gen 30): convex excess-fraction penalty vs fleet mean.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.05 {
            score += 4.5 * (excess_frac - 0.05) * (excess_frac - 0.05) / (excess_frac + 0.05) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation B (gen 30): complementarity bonus.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_frac = (after + mean) / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation C (gen 30): awkward-middle-band guard (16..=29 leftovers).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation D (gen 30): late-stream exact-fill escalation.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation E (gen 30): dual-threshold new-bin gate.
    if is_new_bin && nxt > 0.0 && fitting_bins_count > 0 {
        let best_chain_possible = mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        if !best_chain_possible && open_bins_count as f64 * (mean / cap) > 2.5 {
            score -= 1.5 * (1.0 - progress);
        }
    }

    // Mutation F (gen 38): exact-fit chain bonus — when the next item would
    // exactly close the bin after seating the current item, and it is small
    // relative to the current item, escalate the closure reward.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size && next_item_size <= item_size {
        score -= 3.0 * (1.0 - progress);
    }

    // Mutation G (gen 38): graded dead-space ratio refinement — convex penalty
    // when the post-residual fraction exceeds the fleet mean by >0.15 of cap,
    // sharpening the diagnosed suboptimal-residual weakness.
    if !is_new_bin && nxt > 0.0 && post > mean && cap > 0.0 {
        let excess_ratio = (post - mean) / cap;
        if excess_ratio > 0.15 {
            score += 2.0 * excess_ratio + 4.0 * (excess_ratio - 0.15);
        }
    }

    // Mutation H (gen 38): combine fine-grained snugness with lookahead —
    // reward bins whose snug fit leaves a residual that the next item can
    // nearly close (within 3 units), tightening compaction late in stream.
    if !is_new_bin && nxt > 0.0 && post_residual > next_item_size {
        let near_miss = (post_residual - next_item_size) as f64;
        if near_miss <= 3.0 {
            score -= 2.5 * (1.0 - near_miss / 3.0) * (0.5 + 0.8 * progress);
        }
    }

    // Mutation I (gen 38): lookahead-aware new-bin poor-fit gate — open a
    // fresh bin only when the fleet mean cannot seat the item comfortably.
    if is_new_bin && nxt > 0.0 && fitting_bins_count > 0 {
        let fits_poorly = (cap - mean) > item_size as f64 * 1.5;
        if fits_poorly {
            score -= 3.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        // Perfect 2-step fit: strong reward.
        if diff < 0.5 {
            score -= 40.0;
        } else {
            // Proximity reward, scaled down as diff grows.
            score -= 20.0 * (-diff / 25.0).exp();
        }
        // Penalize leaving dead space that the next item cannot use.
        if post_residual < next_item_size {
            score += (next - post_residual as f64) * 0.8;
        }
    } else {
        // Last item: just minimize waste, slight bonus for tight fit.
        score -= 5.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight";
    // prefer using them (their residual is hard to use later).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.3;
    } else {
        score += (pr - mean_residual) * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize large leftover fragments that are likely unusable (< 10).
    if post_residual < 10 {
        score -= 8.0; // tiny dead space is fine (almost full bin)
    } else if post_residual < 25 {
        score += (25 - post_residual) as f64 * 0.2; // awkward mid-range gap
    }

    // Early in stream: be more conservative, favor keeping bins flexible.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * pr * 0.1;

    // Many open bins: discourage spreading; prefer filling existing ones.
    if open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Two-step waste base.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Aggressive exact two-step match.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 12.0 + 6.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 5.0;
        } else if slack < 20 {
            score -= 2.0;
        }
    }

    // Perfect closure / small leftovers.
    if post_residual == 0 {
        score -= 24.0;
    } else if post_residual < 10 {
        score += 9.0 + 2.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Dead-space risk: quadratic waste penalty scaled by wasted fraction.
    if nxt > 0.0 && post > 0.0 && post < nxt {
        let waste_frac = (nxt - post) / nxt;
        score += 0.5 * (nxt - post).min(cap)
            + 4.0
            + 3.0 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.0 * waste_frac * (1.0 - progress);
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Void fraction, graded harder for large voids.
    let void_frac = post / resid;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.5 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 8.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 1.5;
    }

    // Opening cost for a brand-new bin.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 6.0 + 3.0 * progress;
        } else if pressure < 0.45 {
            score += 1.0 + 3.0 * progress;
        } else {
            score += 8.0 + 5.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.05;

    // Chain closure: residual exactly matches next item size.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 2.5 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.0;
    }

    // Endgame tightening.
    if progress > 0.85 && is_new_bin {
        score += 6.0 * (progress - 0.85) / 0.15;
    }

    // Snug fit, graded.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        if snug < 5.0 {
            score -= 2.5;
        }
        if snug < 15.0 {
            score -= 1.0 * (1.0 - snug / 15.0);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
    }

    // Dead-space ratio penalty, graded.
    if post > mean && cap > 0.0 {
        let excess_ratio = (post - mean) / cap;
        if excess_ratio > 0.15 {
            score += 2.0 * excess_ratio + 4.0 * (excess_ratio - 0.15);
        }
    }

    // Reusable-void check.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin via residual tiebreak.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
