    // Void fraction, graded harder for large voids.
    let void_frac = post / resid;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.5 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 8.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 1.5;
    }

    // Opening cost for a brand-new bin.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 6.0 + 3.0 * progress;
        } else if pressure < 0.45 {
            score += 1.0 + 3.0 * progress;
        } else {
            score += 8.0 + 5.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.05;

    // Chain closure: residual exactly matches next item size.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 2.5 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
