        if (new_post - nxt).abs() < 1.0 {
            score -= 4.0 * (1.0 - progress);
        } else if new_post < nxt && progress > 0.5 {
            score += 2.5 * (progress - 0.5) / 0.5;
        }
    }

    // Mutation W: dead-space ratio diagnostic — convex penalty on
    // fleet-mean excess leftover, mild early-stream grace.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.05 {
            score += 4.5 * (excess_frac - 0.05) * (excess_frac - 0.05) / (excess_frac + 0.05) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation X: complementarity bonus — reward leftovers that pair with
    // the fleet-average residual into a jointly fillable whole.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_sum = after + mean;
        let pair_frac = pair_sum / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation Y: lookahead-fit calibration — escalate the exact-fill
    // reward late in the stream.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation Z: waste-shape guard — penalize awkward middle-band
    // leftovers (16..=29).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AA (gen 40): residual-band anticipation — when the post
    // leftover falls just short of holding the next item, but the bin's
    // own remaining residual (before this item) could have held it, the
    // placement wastes the next-item slot; penalize proportionally to how
    // close the miss is, weighted by how few fitting alternatives exist.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 8.0 {
            let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
            score += (3.0 - miss * 0.3) * (1.0 + scarcity) * (0.4 + 0.8 * progress);
        }
    }

    // Mutation AB (gen 40): dual-lookahead exact-pair reward — if the
    // leftover after the next item equals the current item size, the bin
    // becomes perfectly refillable by the same item class two steps out;
    // reward this closure cycle, stronger early when cycles repeat more.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 == item_size as f64 && item_size > 0 {
            score -= 4.5 * (1.2 - progress);
        }
    }

    // Mutation AC (gen 40): fleet-residual matching — prefer bins whose
    // post leftover lands close to the fleet mean residual, so future
    // mid-size items fit uniformly across bins; graded by deviation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let dev = (after - mean).abs() / cap;
        if dev < 0.08 {
            score -= 2.2 * (1.0 - dev / 0.08) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AD (gen 40): new-bin final-fill hedge — late in the stream,
    // opening a new bin is only justified if the item is large relative to
    // what the fleet can still absorb; tighten the gate with progress.
    if is_new_bin && progress > 0.6 {
        let fleet_absorb = mean * open_bins_count as f64;
        if fleet_absorb > item_size as f64 * (1.0 + 2.0 * (progress - 0.6)) {
            score += 4.0 * (progress - 0.6) / 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post-residual relative to capacity is better.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Penalize dead space: post_residual that is too small to ever be useful.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit, penalize wasted pairing.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            score += 0.35 * next_item_size as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            score -= 4.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Global pressure: many open bins -> prefer consolidating into existing bins.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    if bin_residual < bin_capacity {
        score -= 3.0 * pressure;
    } else {
        // New-bin candidate: penalize opening new bins unless existing bins are crowded.
        score += 8.0 + 4.0 * pressure;
        // Allow new bin when mean residual is small (existing bins nearly full).
        score -= 0.4 * mean_residual;
    }

    // Time horizon: early in stream, slightly prefer new bins to keep flexibility;
    // late in stream, strongly prefer filling existing bins.
    let t = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - t);
    } else {
        score -= 10.0 * t;
    }

    // Mild preference for bins with residual close to the mean (balance load).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Two-step waste base.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Aggressive exact two-step match.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 12.0 + 6.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 5.0;
        } else if slack < 20 {
            score -= 2.0;
        }
    }

    // Perfect closure / small leftovers.
    if post_residual == 0 {
        score -= 24.0;
    } else if post_residual < 10 {
        score += 9.0 + 2.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Dead-space risk: quadratic waste penalty scaled by wasted fraction.
    if nxt > 0.0 && post > 0.0 && post < nxt {
        let waste_frac = (nxt - post) / nxt;
        score += 0.5 * (nxt - post).min(cap)
            + 4.0
            + 3.0 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.0 * waste_frac * (1.0 - progress);
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Void fraction, graded harder for large voids.
    let void_frac = post / resid;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.5 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 8.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 1.5;
    }

    // Opening cost for a brand-new bin.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 6.0 + 3.0 * progress;
        } else if pressure < 0.45 {
            score += 1.0 + 3.0 * progress;
        } else {
            score += 8.0 + 5.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.05;

    // Chain closure: residual exactly matches next item size.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 2.5 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.0;
    }

    // Endgame tightening.
    if progress > 0.85 && is_new_bin {
        score += 6.0 * (progress - 0.85) / 0.15;
    }

    // Snug fit, graded.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        if snug < 5.0 {
            score -= 2.5;
        }
        if snug < 15.0 {
            score -= 1.0 * (1.0 - snug / 15.0);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
    }

    // Dead-space ratio penalty, graded.
    if post > mean && cap > 0.0 {
        let excess_ratio = (post - mean) / cap;
        if excess_ratio > 0.15 {
            score += 2.0 * excess_ratio + 4.0 * (excess_ratio - 0.15);
        }
    }

    // Reusable-void check.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin via residual tiebreak.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // New-bin gate: open a fresh bin only when fits elsewhere are poor.
    if is_new_bin && nxt > 0.0 {
        let fits_poorly = fitting_bins_count > 0 && (bin_capacity as f64 - mean) > item_size as f64 * 1.5;
        if fits_poorly {
            score -= 3.0;
        }
    }

    // Depth-2 lookahead: small residual matching a future item class.
    if nxt > 0.0 && post_residual >= next_item_size {
        let two_left = post_residual - next_item_size;
        if two_left > 0 && two_left <= 10 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Exact-fit chain: post residual equals next item size with a small item.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size && next_item_size <= item_size {
        score -= 3.0 * (1.0 - progress);
    }

    // Mutation F: lookahead-aware dead-space hedge (sharpened weight).
    if nxt > 0.0 && !is_new_bin && post_residual < next_item_size && progress > 0.1 {
        let unusable = (next_item_size - post_residual) as f64;
        score += 0.75 * unusable * (1.0 - progress);
    }

    // Mutation G: residual homogeneity.
    if !is_new_bin && mean > 0.0 {
        let hom = ((post - mean).abs() / cap) as f64;
        score -= 0.8 * (1.0 - hom.min(1.0));
    }

    // Mutation H: dead-space ratio refinement vs fleet-average leftover fraction.
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let post_frac = post / cap;
        let mean_frac = (mean / cap).min(1.0);
        if post_frac > mean_frac {
            score += 3.5 * (post_frac - mean_frac) * (1.0 - 0.4 * progress);
        } else {
            score -= 1.2 * (mean_frac - post_frac);
        }
    }

    // Mutation I: anti-fragmentation sweep on large usable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let usable_left = post_residual - next_item_size;
        if usable_left > 25 {
            score += 0.06 * (usable_left as f64 - 25.0);
        }
    }

    // Mutation J: refillability-weighted leftover valuation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Mutation K: convex shortfall penalty for near-miss lookahead.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 15.0 {
            score += (2.5 - shortfall * 0.15) * (1.0 + 0.5 * progress);
        }
    }

    // Mutation L: asymmetric quadratic dead-space bump (peak 0.38 of capacity).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.38;
        let skew = if x < peak { 0.7 } else { 1.45 };
        let bump = (x - peak) * (x - peak);
        let ramp = if progress > 0.25 { 1.0 + 0.6 * (progress - 0.25) } else { 0.85 + 0.6 * progress };
        score += 15.0 * skew * bump * ramp;
    }

    // Mutation M: lookahead-aware new-bin arbitration.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let open_can_chain = fitting_bins_count > 0
            && mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        let new_can_chain = new_post >= nxt;
        if open_can_chain && !new_can_chain {
            score += 5.0 + 3.0 * (1.0 - progress);
        } else if !open_can_chain && new_can_chain {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Mutation N: utilization-maximizing tiebreak.
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Mutation O: two-step closure ladder.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 {
            let closeness = 1.0 - (after / cap).min(1.0);
            score -= 3.0 * closeness * closeness * (0.6 + 0.8 * progress);
        }
    }

    // Mutation P: fleet-aware dead-space cap.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Mutation Q: two-deep chain reward + mid-band dead-space penalty.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 == nxt || after as f64 == item_size as f64 {
            score -= 3.5 + 2.5 * (1.0 - progress);
        } else if (after as f64) >= nxt.min(item_size as f64) && after < 2 * next_item_size {
            score -= 1.0 * (1.0 - 0.5 * progress);
        }
        if after >= 30 && after <= 60 && progress > 0.3 {
            score += 1.8 * (progress - 0.3) / 0.7;
        }
    }

    // Mutation R: progress-adaptive snugness.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        let band = 20.0 - 10.0 * progress;
        if snug < band {
            score -= 1.6 * (1.0 - snug / band) * (0.5 + progress);
        }
    }

    // Mutation S: new-bin saturation hedge.
    if is_new_bin && open_bins_count > 8 {
        let frag = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
        score += 0.9 * frag * (0.4 + 0.6 * progress);
    }

    // Mutation T (refined gen 40): dead-space bump peak sharpened to 0.27 of
    // capacity with steeper late-stream scaling — the diagnosed weakness is
    // residual space just above the fillable band, so push the peak lower
    // and make the penalty bite harder as the stream matures.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak2 = 0.27;
        let skew2 = if x < peak2 { 0.55 } else { 1.9 };
        let bump2 = (x - peak2) * (x - peak2);
        score += 6.5 * skew2 * bump2 * (1.0 + 1.6 * progress);
    }

    // Mutation U: exact-closure ladder — reward small closable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 15 {
            score -= 2.0 * (1.0 - after as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
    }

    // Mutation V: new-bin exact-chain gate.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if (new_post - nxt).abs() < 1.0 {
            score -= 4.0 * (1.0 - progress);
        } else if new_post < nxt && progress > 0.5 {
            score += 2.5 * (progress - 0.5) / 0.5;
        }
    }

    // Mutation W (gen 40): dead-space ratio diagnostic — penalize bins whose
    // post-lookahead leftover fraction exceeds the fleet mean by a convex
    // margin; grace period shortened and weight raised so the correction
    // engages earlier in the stream.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.03 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.04 {
            score += 5.5 * (excess_frac - 0.04) * (excess_frac - 0.04) / (excess_frac + 0.04) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation X: complementarity bonus — reward bins whose leftover
    // after seating the item complements the fleet-average residual.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_sum = after + mean;
        let pair_frac = pair_sum / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation Y: lookahead-fit calibration — when the next item
    // would exactly fill the post-residual, escalate the reward late.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation Z (gen 40): waste-shape guard — narrow the awkward middle
    // band to 14..=27 and sharpen its decay so mid-shape leftovers are
    // rejected more decisively while near-closable shapes stay attractive.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 14 && after <= 27 {
            score += 1.6 * (1.0 - (after - 14) as f64 / 13.0) * (0.5 + 0.8 * progress);
        }
    }

    // Mutation AA (new, gen 40): residual-decay arbitration — when several
    // bins fit, prefer the one whose post-lookahead leftover is closest to
    // being fully consumed by the next item, with a smooth quadratic
    // reward on the shortfall to closure, scaled by fleet pressure.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && fitting_bins_count > 1 {
        let after = (post_residual - next_item_size) as f64;
        let closeness2 = 1.0 - (after / cap).min(1.0);
        score -= 1.4 * closeness2 * closeness2 * (mean / cap).max(0.2);
    }

    // Mutation AB (new, gen 40): late-stream new-bin suppression — once the
    // stream is mature, opening a fresh bin should require a strong
    // justification; scale the opening penalty with remaining volume.
    if is_new_bin && progress > 0.6 {
        let remaining = 1.0 - progress;
        score += 4.0 * (1.0 - remaining / 0.4) * (0.5 + 0.5 * (mean / cap));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: penalize wasted space, with non-linear (quadratic) growth
    let mut score = pr + 12.0 * norm_pr * norm_pr * cap;

    // Smooth coupling of post_residual with stream progress:
    // early in stream, prefer leaving flexible residuals; later, prefer tight fits.
    let flex = (1.0 - progress) * (1.0 - progress);
    let tight = progress * progress;
    score += flex * 8.0 * norm_pr - tight * 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Non-linear interaction between item fill ratio and progress
    let fill = item_size as f64 / cap;
    score -= tight * 10.0 * fill * fill;

    // Lookahead: reward residual that can fit the next item (smoothly)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let fit_quality = 1.0 - (pr - nx) / cap; // tight fit for next item is best
            score -= 7.0 * fit_quality * fit_quality;
        } else {
            // residual too small for next item: dead-space penalty, smooth in gap
            let gap = (nx - pr) / cap;
            score += 9.0 * gap * gap * cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 5.0 * (1.0 - norm_pr);
    }

    // Mild penalty when many bins are open and residual is large (fragmentation pressure)
    let ob = open_bins_count as f64;
    score += 0.4 * (ob / (ob + 4.0)) * norm_pr * cap;

    // Deviation from mean residual: prefer bins near the mean (keeps residuals balanced)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: neutral-ish score so it is chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score = pr + 6.0 * (1.0 - tight) + 4.0 * (ob / (ob + 3.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Two-step waste base.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Aggressive exact two-step match.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 12.0 + 6.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 5.0;
        } else if slack < 20 {
            score -= 2.0;
        }
    }

    // Perfect closure / small leftovers.
    if post_residual == 0 {
        score -= 24.0;
    } else if post_residual < 10 {
        score += 9.0 + 2.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Dead-space risk: quadratic waste penalty scaled by wasted fraction.
    if nxt > 0.0 && post > 0.0 && post < nxt {
        let waste_frac = (nxt - post) / nxt;
        score += 0.5 * (nxt - post).min(cap)
            + 4.0
            + 3.0 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.0 * waste_frac * (1.0 - progress);
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Void fraction, graded harder for large voids.
    let void_frac = post / resid;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.5 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 8.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 1.5;
    }

    // Opening cost for a brand-new bin.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 6.0 + 3.0 * progress;
        } else if pressure < 0.45 {
            score += 1.0 + 3.0 * progress;
        } else {
            score += 8.0 + 5.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.05;

    // Chain closure: residual exactly matches next item size.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 2.5 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.0;
    }

    // Endgame tightening.
    if progress > 0.85 && is_new_bin {
        score += 6.0 * (progress - 0.85) / 0.15;
    }

    // Snug fit, graded.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        if snug < 5.0 {
            score -= 2.5;
        }
        if snug < 15.0 {
            score -= 1.0 * (1.0 - snug / 15.0);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
    }

    // Dead-space ratio penalty, graded.
    if post > mean && cap > 0.0 {
        let excess_ratio = (post - mean) / cap;
        if excess_ratio > 0.15 {
            score += 2.0 * excess_ratio + 4.0 * (excess_ratio - 0.15);
        }
    }

    // Reusable-void check.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin via residual tiebreak.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // New-bin gate: open a fresh bin only when fits elsewhere are poor.
    if is_new_bin && nxt > 0.0 {
        let fits_poorly = fitting_bins_count > 0 && (bin_capacity as f64 - mean) > item_size as f64 * 1.5;
        if fits_poorly {
            score -= 3.0;
        }
    }

    // Depth-2 lookahead: small residual matching a future item class.
    if nxt > 0.0 && post_residual >= next_item_size {
        let two_left = post_residual - next_item_size;
        if two_left > 0 && two_left <= 10 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Exact-fit chain: post residual equals next item size with a small item.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size && next_item_size <= item_size {
        score -= 3.0 * (1.0 - progress);
    }

    // Mutation F: lookahead-aware dead-space hedge (sharpened weight).
    if nxt > 0.0 && !is_new_bin && post_residual < next_item_size && progress > 0.1 {
        let unusable = (next_item_size - post_residual) as f64;
        score += 0.75 * unusable * (1.0 - progress);
    }

    // Mutation G: residual homogeneity.
    if !is_new_bin && mean > 0.0 {
        let hom = ((post - mean).abs() / cap) as f64;
        score -= 0.8 * (1.0 - hom.min(1.0));
    }

    // Mutation H: dead-space ratio refinement vs fleet-average leftover fraction.
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let post_frac = post / cap;
        let mean_frac = (mean / cap).min(1.0);
        if post_frac > mean_frac {
            score += 3.5 * (post_frac - mean_frac) * (1.0 - 0.4 * progress);
        } else {
            score -= 1.2 * (mean_frac - post_frac);
        }
    }

    // Mutation I: anti-fragmentation sweep on large usable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let usable_left = post_residual - next_item_size;
        if usable_left > 25 {
            score += 0.06 * (usable_left as f64 - 25.0);
        }
    }

    // Mutation J: refillability-weighted leftover valuation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Mutation K: convex shortfall penalty for near-miss lookahead.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 15.0 {
            score += (2.5 - shortfall * 0.15) * (1.0 + 0.5 * progress);
        }
    }

    // Mutation L: asymmetric quadratic dead-space bump (peak 0.38 of capacity).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.38;
        let skew = if x < peak { 0.7 } else { 1.45 };
        let bump = (x - peak) * (x - peak);
        let ramp = if progress > 0.25 { 1.0 + 0.6 * (progress - 0.25) } else { 0.85 + 0.6 * progress };
        score += 15.0 * skew * bump * ramp;
    }

    // Mutation M: lookahead-aware new-bin arbitration.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let open_can_chain = fitting_bins_count > 0
            && mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        let new_can_chain = new_post >= nxt;
        if open_can_chain && !new_can_chain {
            score += 5.0 + 3.0 * (1.0 - progress);
        } else if !open_can_chain && new_can_chain {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Mutation N: utilization-maximizing tiebreak.
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Mutation O: two-step closure ladder.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 {
            let closeness = 1.0 - (after / cap).min(1.0);
            score -= 3.0 * closeness * closeness * (0.6 + 0.8 * progress);
        }
    }

    // Mutation P: fleet-aware dead-space cap.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Mutation Q: two-deep chain reward + mid-band dead-space penalty.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 == nxt || after as f64 == item_size as f64 {
            score -= 3.5 + 2.5 * (1.0 - progress);
        } else if (after as f64) >= nxt.min(item_size as f64) && after < 2 * next_item_size {
            score -= 1.0 * (1.0 - 0.5 * progress);
        }
        if after >= 30 && after <= 60 && progress > 0.3 {
            score += 1.8 * (progress - 0.3) / 0.7;
        }
    }

    // Mutation R: progress-adaptive snugness.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        let band = 20.0 - 10.0 * progress;
        if snug < band {
            score -= 1.6 * (1.0 - snug / band) * (0.5 + progress);
        }
    }

    // Mutation S: new-bin saturation hedge.
    if is_new_bin && open_bins_count > 8 {
        let frag = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
        score += 0.9 * frag * (0.4 + 0.6 * progress);
    }

    // Mutation T (gen 40): sharpen the dead-space bump peak toward 0.28 of
    // capacity with steeper post-peak skew and stronger late scaling —
    // targets the diagnosed suboptimal-residual weakness.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak2 = 0.28;
        let skew2 = if x < peak2 { 0.55 } else { 1.9 };
        let bump2 = (x - peak2) * (x - peak2);
        score += 7.5 * skew2 * bump2 * (1.0 + 1.6 * progress);
    }

    // Mutation U: exact-closure ladder — reward small closable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 15 {
            score -= 2.0 * (1.0 - after as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
    }

    // Mutation V: new-bin exact-chain gate.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if (new_post - nxt).abs() < 1.0 {
            score -= 4.0 * (1.0 - progress);
        } else if new_post < nxt && progress > 0.5 {
            score += 2.5 * (progress - 0.5) / 0.5;
        }
    }

    // Mutation W: dead-space ratio diagnostic — convex penalty on
    // fleet-mean excess leftover, mild early-stream grace.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.05 {
            score += 4.5 * (excess_frac - 0.05) * (excess_frac - 0.05) / (excess_frac + 0.05) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation X: complementarity bonus — reward leftovers that pair with
    // the fleet-average residual into a jointly fillable whole.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_sum = after + mean;
        let pair_frac = pair_sum / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation Y: lookahead-fit calibration — escalate the exact-fill
    // reward late in the stream.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation Z: waste-shape guard — penalize awkward middle-band
    // leftovers (16..=29).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AA (gen 40): residual-band anticipation — when the post
    // leftover falls just short of holding the next item, penalize
    // proportionally to how close the miss is, weighted by scarcity of
    // fitting alternatives.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 8.0 {
            let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
            score += (3.0 - miss * 0.3) * (1.0 + scarcity) * (0.4 + 0.8 * progress);
        }
    }

    // Mutation AB (gen 40): dual-lookahead exact-pair reward — if the
    // leftover after the next item equals the current item size, the bin
    // becomes perfectly refillable two steps out; reward this cycle.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 == item_size as f64 && item_size > 0 {
            score -= 4.5 * (1.2 - progress);
        }
    }

    // Mutation AC (gen 40): fleet-residual matching — prefer bins whose
    // post leftover lands close to the fleet mean residual, graded by
    // deviation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let dev = (after - mean).abs() / cap;
        if dev < 0.08 {
            score -= 2.2 * (1.0 - dev / 0.08) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AD (gen 40): new-bin final-fill hedge — late in the stream,
    // opening a new bin is only justified if the item is large relative to
    // what the fleet can still absorb; tighten the gate with progress.
    if is_new_bin && progress > 0.6 {
        let fleet_absorb = mean * open_bins_count as f64;
        if fleet_absorb > item_size as f64 * (1.0 + 2.0 * (progress - 0.6)) {
            score += 4.0 * (progress - 0.6) / 0.4;
        }
    }

    // Mutation AE (gen 40): scarcity-aware snug consolidation — when only
    // one or two bins fit, amplify the snugness reward so the item lands
    // in the tightest available slot rather than a loose one.
    if !is_new_bin && fitting_bins_count <= 2 && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        if snug <= 10.0 {
            score -= (2.0 - snug * 0.15) * (1.0 + 0.5 * progress);
        }
    }

    // Mutation AF (gen 40): exact-fill scarcity bonus — an exact two-step
    // closure when few bins fit is doubly valuable; escalate the reward
    // with the inverse of fitting bins.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size && fitting_bins_count <= 3 {
        score -= 2.5 * (1.0 / fitting_bins_count.max(1) as f64) * (0.5 + 0.5 * (1.0 - progress));
    }

    // Mutation AG (gen 40): new-bin waste guard — opening a fresh bin whose
    // post residual cannot hold the next item while some open bin leaves a
    // reusable leftover is a double waste; penalize with progress weight.
    if is_new_bin && nxt > 0.0 && fitting_bins_count > 0 {
        let new_post = cap - item_size as f64;
        if new_post < nxt {
            score += 3.0 * (0.5 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well the leftover space decomposes
    // into typical small-item sizes via integer division thresholds.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Reward residuals that belong to "usable" harmonic classes:
    // leftovers that can host common small items (1..=25) with little waste.
    let usable = if post_residual == 0 {
        3.0
    } else if post_residual <= 10 {
        2.5
    } else if post_residual <= 25 {
        1.5
    } else if post_residual <= 50 {
        0.5
    } else if post_residual <= 75 {
        0.0
    } else {
        -0.5 // large leftovers: bin was barely used, mild penalty
    };
    score -= usable * 4.0;

    // Modulo coupling: residuals divisible by 10 align with the capacity grid
    // and tend to admit grid-friendly future items cleanly.
    if post_residual % 10 == 0 {
        score -= 2.0;
    }
    // Penalize awkward odd leftovers in the mid-range.
    if post_residual % 2 == 1 && post_residual > 25 && post_residual < 60 {
        score += 3.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // Next item cannot follow here; penalize proportional to overflow.
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large relative to capacity or open bins are all poorly fitting.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / cap;
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Prefer new bin for big items early in the stream; penalize otherwise.
        score += 8.0 - 10.0 * pressure - 5.0 * scarcity
            - 2.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild load-balancing: pull toward mean residual to spread slack evenly.
    score += 0.10 * ((post - mean_residual) / cap);

    // Slight preference for tighter bins as the stream nears its end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Two-step waste base.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Aggressive exact two-step match.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 12.0 + 6.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 5.0;
        } else if slack < 20 {
            score -= 2.0;
        }
    }

    // Perfect closure / small leftovers.
    if post_residual == 0 {
        score -= 24.0;
    } else if post_residual < 10 {
        score += 9.0 + 2.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Dead-space risk: quadratic waste penalty scaled by wasted fraction.
    if nxt > 0.0 && post > 0.0 && post < nxt {
        let waste_frac = (nxt - post) / nxt;
        score += 0.5 * (nxt - post).min(cap)
            + 4.0
            + 3.0 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.0 * waste_frac * (1.0 - progress);
    }

    // Mean-relative coupling.
    if post > mean {
        score += 0.15 * (post - mean);
    } else {
        score -= 0.05 * (mean - post).min(cap);
    }

    // Void fraction, graded harder for large voids.
    let void_frac = post / resid;
    score += if void_frac > 0.5 {
        0.3 * void_frac + 1.5 * (void_frac - 0.5)
    } else {
        0.3 * void_frac
    };

    // Last-chance fitting bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 8.0;
    } else if !is_new_bin && fitting_bins_count == 2 {
        score -= 1.5;
    }

    // Opening cost for a brand-new bin.
    if is_new_bin {
        let pressure = mean / cap;
        let saturation = open_bins_count as f64 * pressure;
        if pressure < 0.22 {
            score -= 6.0 + 3.0 * progress;
        } else if pressure < 0.45 {
            score += 1.0 + 3.0 * progress;
        } else {
            score += 8.0 + 5.0 * progress;
        }
        if saturation < 2.0 && open_bins_count > 3 {
            score += 1.5;
        }
    }

    // Consolidation pressure.
    score += open_bins_count as f64 * 0.05;

    // Chain closure: residual exactly matches next item size.
    if nxt > 0.0 && bin_residual == next_item_size && !is_new_bin {
        score -= 4.0 + 4.0 * (1.0 - progress);
    }

    // Stranded dead space.
    if nxt > 0.0 && post > 0.0 && post < 0.5 * nxt {
        score += 2.5 * (1.0 - progress);
    }

    // Tight absolute fit.
    if post_residual > 0 && post_residual <= item_size / 4 {
        score -= 1.5;
    }

    // Harmonic pairing.
    let item_frac_class = (item_size * 10 + bin_capacity / 2) / bin_capacity;
    if post_residual >= 10 && post_residual < 30 && item_frac_class % 2 == 0 {
        score -= 2.0;
    }

    // Endgame tightening.
    if progress > 0.85 && is_new_bin {
        score += 6.0 * (progress - 0.85) / 0.15;
    }

    // Snug fit, graded.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        if snug < 5.0 {
            score -= 2.5;
        }
        if snug < 15.0 {
            score -= 1.0 * (1.0 - snug / 15.0);
        }
    }

    // Lookahead chain: reusable leftover within current item size.
    if nxt > 0.0 && post_residual >= next_item_size {
        let second_left = post_residual - next_item_size;
        if second_left >= 1 && second_left <= item_size {
            score -= 1.5;
        }
    }

    // Dead-space ratio penalty, graded.
    if post > mean && cap > 0.0 {
        let excess_ratio = (post - mean) / cap;
        if excess_ratio > 0.15 {
            score += 2.0 * excess_ratio + 4.0 * (excess_ratio - 0.15);
        }
    }

    // Reusable-void check.
    if nxt > 0.0 && post >= nxt {
        let usable = post - nxt;
        if usable >= 10.0 {
            score -= 0.5 * (usable / cap);
        }
    }

    // Fragmentation guard.
    if !is_new_bin && fitting_bins_count > 2 && mean > 0.0 {
        let dev = ((post - mean).abs()) / cap;
        score += 0.8 * dev;
    }

    // Prefer fullest fitting bin via residual tiebreak.
    if !is_new_bin {
        score += 0.08 * (bin_residual as f64 / cap);
    }

    // Near-closure with unusable leftover.
    if post_residual > 0 && post_residual < 8 && nxt > post {
        score -= 6.0;
    }

    // New-bin gate: open a fresh bin only when fits elsewhere are poor.
    if is_new_bin && nxt > 0.0 {
        let fits_poorly = fitting_bins_count > 0 && (bin_capacity as f64 - mean) > item_size as f64 * 1.5;
        if fits_poorly {
            score -= 3.0;
        }
    }

    // Depth-2 lookahead: small residual matching a future item class.
    if nxt > 0.0 && post_residual >= next_item_size {
        let two_left = post_residual - next_item_size;
        if two_left > 0 && two_left <= 10 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Exact-fit chain: post residual equals next item size with a small item.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size && next_item_size <= item_size {
        score -= 3.0 * (1.0 - progress);
    }

    // Mutation F: lookahead-aware dead-space hedge (sharpened weight).
    if nxt > 0.0 && !is_new_bin && post_residual < next_item_size && progress > 0.1 {
        let unusable = (next_item_size - post_residual) as f64;
        score += 0.75 * unusable * (1.0 - progress);
    }

    // Mutation G: residual homogeneity.
    if !is_new_bin && mean > 0.0 {
        let hom = ((post - mean).abs() / cap) as f64;
        score -= 0.8 * (1.0 - hom.min(1.0));
    }

    // Mutation H: dead-space ratio refinement vs fleet-average leftover fraction.
    if !is_new_bin && cap > 0.0 && mean > 0.0 {
        let post_frac = post / cap;
        let mean_frac = (mean / cap).min(1.0);
        if post_frac > mean_frac {
            score += 3.5 * (post_frac - mean_frac) * (1.0 - 0.4 * progress);
        } else {
            score -= 1.2 * (mean_frac - post_frac);
        }
    }

    // Mutation I: anti-fragmentation sweep on large usable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let usable_left = post_residual - next_item_size;
        if usable_left > 25 {
            score += 0.06 * (usable_left as f64 - 25.0);
        }
    }

    // Mutation J: refillability-weighted leftover valuation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let mut refill = 0.0f64;
        if after > 0 {
            if after % 10 == 0 { refill = 2.2; }
            else if after % 5 == 0 { refill = 1.4; }
            else if after % 4 == 0 { refill = 1.0; }
            else if after % 3 == 0 { refill = 0.7; }
        }
        score -= refill * (1.0 - 0.4 * progress);
    }

    // Mutation K: convex shortfall penalty for near-miss lookahead.
    if !is_new_bin && nxt > 0.0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall <= 15.0 {
            score += (2.5 - shortfall * 0.15) * (1.0 + 0.5 * progress);
        }
    }

    // Mutation L: asymmetric quadratic dead-space bump (peak 0.38 of capacity).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak = 0.38;
        let skew = if x < peak { 0.7 } else { 1.45 };
        let bump = (x - peak) * (x - peak);
        let ramp = if progress > 0.25 { 1.0 + 0.6 * (progress - 0.25) } else { 0.85 + 0.6 * progress };
        score += 15.0 * skew * bump * ramp;
    }

    // Mutation M: lookahead-aware new-bin arbitration.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        let open_can_chain = fitting_bins_count > 0
            && mean >= item_size as f64
            && (mean - item_size as f64) >= nxt;
        let new_can_chain = new_post >= nxt;
        if open_can_chain && !new_can_chain {
            score += 5.0 + 3.0 * (1.0 - progress);
        } else if !open_can_chain && new_can_chain {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Mutation N: utilization-maximizing tiebreak.
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Mutation O: two-step closure ladder.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 {
            let closeness = 1.0 - (after / cap).min(1.0);
            score -= 3.0 * closeness * closeness * (0.6 + 0.8 * progress);
        }
    }

    // Mutation P: fleet-aware dead-space cap.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Mutation Q: two-deep chain reward + mid-band dead-space penalty.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 == nxt || after as f64 == item_size as f64 {
            score -= 3.5 + 2.5 * (1.0 - progress);
        } else if (after as f64) >= nxt.min(item_size as f64) && after < 2 * next_item_size {
            score -= 1.0 * (1.0 - 0.5 * progress);
        }
        if after >= 30 && after <= 60 && progress > 0.3 {
            score += 1.8 * (progress - 0.3) / 0.7;
        }
    }

    // Mutation R: progress-adaptive snugness.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        let band = 20.0 - 10.0 * progress;
        if snug < band {
            score -= 1.6 * (1.0 - snug / band) * (0.5 + progress);
        }
    }

    // Mutation S: new-bin saturation hedge.
    if is_new_bin && open_bins_count > 8 {
        let frag = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
        score += 0.9 * frag * (0.4 + 0.6 * progress);
    }

    // Mutation T (refined gen 40): sharpen the dead-space bump peak toward
    // 0.27 of capacity with stronger late-stream scaling.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak2 = 0.27;
        let skew2 = if x < peak2 { 0.55 } else { 1.85 };
        let bump2 = (x - peak2) * (x - peak2);
        score += 7.0 * skew2 * bump2 * (1.0 + 1.6 * progress);
    }

    // Mutation U: exact-closure ladder — reward small closable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 15 {
            score -= 2.2 * (1.0 - after as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
    }

    // Mutation V: new-bin exact-chain gate.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if (new_post - nxt).abs() < 1.0 {
            score -= 4.0 * (1.0 - progress);
        } else if new_post < nxt && progress > 0.5 {
            score += 2.5 * (progress - 0.5) / 0.5;
        }
    }

    // Mutation W (gen 40): dead-space ratio diagnostic with convex excess margin.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.05 {
            score += 5.0 * (excess_frac - 0.05) * (excess_frac - 0.05) / (excess_frac + 0.05) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation X: complementarity bonus for jointly fillable leftover pairs.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_sum = after + mean;
        let pair_frac = pair_sum / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation Y: lookahead-fit calibration — escalate exact-fill reward late.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation Z (gen 40): waste-shape guard on the awkward middle band.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.4 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AA (gen 40): tight-fit residual ladder — reward bins whose
    // post-residual leaves a snug, closable remainder proportional to the
    // current item, reinforcing compaction along the diagnosed weakness.
    if !is_new_bin && nxt > 0.0 && post_residual > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        let cap_frac = gap / cap;
        if cap_frac < 0.08 {
            // Nearly fillable by next item: strong reward.
            score -= 3.0 * (1.0 - cap_frac / 0.08) * (0.7 + 0.6 * progress);
        } else if cap_frac < 0.2 {
            // Moderately close: mild reward.
            score -= 1.0 * (1.0 - (cap_frac - 0.08) / 0.12) * (0.5 + 0.5 * progress);
        }
    }

    // Mutation AB (gen 40): fleet-residual equalizer — prefer bins whose
    // post-residual moves the fleet toward homogeneous, chain-fillable
    // residuals; penalize outliers more when many bins compete.
    if !is_new_bin && mean > 0.0 && fitting_bins_count >= 2 {
        let dev = (post - mean).abs() / cap;
        let weight = 0.6 + 0.25 * (fitting_bins_count.min(6) as f64);
        score += weight * dev * (0.6 + 0.5 * progress);
    }

    // Mutation AC (gen 40): new-bin compaction trigger — open a fresh bin
    // only when no existing bin can leave a chainable remainder for the
    // next item; otherwise heavily discourage opening.
    if is_new_bin && nxt > 0.0 && fitting_bins_count > 0 {
        let new_post = cap - item_size as f64;
        let new_chains = new_post >= nxt && (new_post - nxt) <= item_size as f64;
        if !new_chains {
            score += 2.0 + 3.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
