        }
    }

    // Mutation Y: lookahead-fit calibration — when the next item
    // would exactly fill the post-residual, escalate the reward late in the
    // stream where closure value is highest.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation Z: waste-shape guard — penalize leftover shapes that
    // are neither small-closable nor large-reusable (the awkward middle band
    // 16..=29), which the diagnosed weakness suggests we accumulate.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AA (gen 45 new): dual-item lookahead — reward bins whose
    // post-residual can seat the next item AND still leave room for a
    // follow-up of at least half the current item, promoting chained fills
    // that directly attack residual dead space.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        let follow = (item_size as f64 * 0.5).ceil();
        if after as f64 >= follow {
            let depth = (after as f64 / cap).min(1.0);
            score -= 1.2 * (1.0 - depth) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation AB (gen 45 new): residual floor discipline — when the
    // post-residual lands in a thin unusable sliver (1..=6) that no realistic
    // item can fill, penalize it to keep residuals chunky and reusable.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 1 && after <= 6 {
            score += 0.9 * (1.0 - after as f64 / 6.0) * (0.6 + 0.8 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 8.0; // mid-size gap is reusable
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.2 * item_size as f64;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 6.0;
        }
        // Exact chain: item + next fills bin completely -> excellent.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // New-bin candidate logic: opening a fresh bin should be discouraged when the
    // stream is late or when open bins are already fragmented, encouraged early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 + 45.0 * progress + 1.5 * open_bins_count as f64;
        // A new bin is attractive only for huge items that fragment any bin anyway.
        if item_size >= 60 {
            score -= 30.0;
        }
    }

    // Global fragmentation pressure: if mean residual is high, prefer using the
    // emptiest bins (large residual) to consolidate space.
    let residual_gap = bin_residual as f64 - mean_residual;
    score -= 0.15 * residual_gap;

    // Mild penalty for spreading across too many open bins.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

