        let new_can_chain = new_post >= nxt;
        if open_can_chain && !new_can_chain {
            score += 5.0 + 3.0 * (1.0 - progress);
        } else if !open_can_chain && new_can_chain {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Mutation N: utilization-maximizing tiebreak.
    if !is_new_bin {
        let used_frac = 1.0 - (bin_residual as f64 / cap);
        score += 0.35 * used_frac.sqrt() * (1.0 - 0.3 * progress);
    }

    // Mutation O: two-step closure ladder.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        if after > 0.0 {
            let closeness = 1.0 - (after / cap).min(1.0);
            score -= 3.0 * closeness * closeness * (0.6 + 0.8 * progress);
        }
    }

    // Mutation P: fleet-aware dead-space cap.
    if !is_new_bin && mean > 0.0 && fitting_bins_count > 1 && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let excess = after - mean;
        if excess > 0.0 {
            score += 0.9 * excess * (1.0 - 0.3 * progress) / cap.max(1.0);
        }
    }

    // Mutation Q: two-deep chain reward + mid-band dead-space penalty.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 == nxt || after as f64 == item_size as f64 {
            score -= 3.5 + 2.5 * (1.0 - progress);
        } else if (after as f64) >= nxt.min(item_size as f64) && after < 2 * next_item_size {
            score -= 1.0 * (1.0 - 0.5 * progress);
        }
        if after >= 30 && after <= 60 && progress > 0.3 {
            score += 1.8 * (progress - 0.3) / 0.7;
        }
    }

    // Mutation R: progress-adaptive snugness.
    if !is_new_bin && bin_residual >= item_size {
        let snug = (bin_residual - item_size) as f64;
        let band = 20.0 - 10.0 * progress;
        if snug < band {
            score -= 1.6 * (1.0 - snug / band) * (0.5 + progress);
        }
    }

    // Mutation S: new-bin saturation hedge.
    if is_new_bin && open_bins_count > 8 {
        let frag = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
        score += 0.9 * frag * (0.4 + 0.6 * progress);
    }

    // Mutation T (gen 46 refinement): sharpen the dead-space bump peak toward
    // 0.28 of capacity with stronger late-stream scaling — continuing the
    // successful direction against suboptimal-residual accumulation.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = (post_residual - next_item_size) as f64;
        let x = (after / cap).min(1.0);
        let peak2 = 0.28;
        let skew2 = if x < peak2 { 0.55 } else { 1.85 };
        let bump2 = (x - peak2) * (x - peak2);
        score += 6.5 * skew2 * bump2 * (1.0 + 1.6 * progress);
    }

    // Mutation U: exact-closure ladder — reward small closable leftovers.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 15 {
            score -= 2.0 * (1.0 - after as f64 / 15.0) * (0.6 + 0.8 * (1.0 - progress));
        }
    }

    // Mutation V: new-bin exact-chain gate.
    if is_new_bin && nxt > 0.0 {
        let new_post = cap - item_size as f64;
        if (new_post - nxt).abs() < 1.0 {
            score -= 4.0 * (1.0 - progress);
        } else if new_post < nxt && progress > 0.5 {
            score += 2.5 * (progress - 0.5) / 0.5;
        }
    }

    // Mutation W: dead-space ratio diagnostic — convex excess penalty.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 && progress > 0.05 {
        let after = (post_residual - next_item_size) as f64;
        let excess_frac = ((after - mean) / cap).max(0.0);
        if excess_frac > 0.05 {
            score += 4.5 * (excess_frac - 0.05) * (excess_frac - 0.05) / (excess_frac + 0.05) * (0.7 + 0.6 * progress);
        }
    }

    // Mutation X: complementarity bonus — leftover pairs fillable by mid-size items.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let pair_sum = after + mean;
        let pair_frac = pair_sum / cap;
        if pair_frac >= 0.9 && pair_frac <= 1.15 {
            score -= 1.8 * (1.0 - (pair_frac - 0.9).abs() / 0.25).max(0.0) * (1.0 - 0.3 * progress);
        }
    }

    // Mutation Y: lookahead-fit calibration — escalate exact-fill reward late.
    if !is_new_bin && nxt > 0.0 && post_residual == next_item_size {
        score -= 2.0 * progress * (nxt / cap);
    }

    // Mutation Z: waste-shape guard — penalize awkward middle band 16..=29.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= 16 && after <= 29 {
            score += 1.2 * (1.0 - (after - 16) as f64 / 13.0) * (0.5 + 0.7 * progress);
        }
    }

    // Mutation AA (gen 46): residual-slope steering — when the fleet mean
    // residual is drifting high, prefer bins that close tighter (post small)
    // with a progress-scaled convex pull; this directly targets the diagnosed
    // dead-space-ratio weakness by amplifying the pressure as sigma_res grows.
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size && mean > 0.0 {
        let after = (post_residual - next_item_size) as f64;
        let ratio = after / mean;
        if ratio < 1.0 {
            score -= 1.4 * (1.0 - ratio) * (0.5 + 1.0 * progress);
        } else if ratio > 1.6 {
            score += 0.9 * (ratio - 1.6).min(2.0) * (0.4 + 0.8 * progress);
        }
    }

    // Mutation AB (gen 46): adaptive new-bin threshold — raise the opening
    // cost when the fleet mean residual still has room for the item, so a
    // fresh bin is opened only when existing bins genuinely cannot absorb it.
    if is_new_bin && nxt > 0.0 && mean > 0.0 {
        let fleet_room = mean - item_size as f64;
        if fleet_room >= nxt {
            score += 2.5 + 2.5 * (1.0 - progress);
        }
    }

    // Mutation AC (gen 46): dual-closure lookahead — reward bins where the
    // leftover after seating the item can host both the next item and the
    // current item class afterwards (two-step perfect refill ladder).
    if !is_new_bin && nxt > 0.0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= item_size && (after - item_size) <= 8 {
            score -= 2.2 * (1.0 - 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step lookahead match: post_residual equals next item size
    // -> perfect two-item packing, strongly reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits into the post residual (soft lookahead match).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (post_residual - next_item_size) as f64 * 0.05;
    } else if next_item_size > 0 {
        // Next item won't fit: penalize dead space proportionally.
        score += (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    // Reward tight fits (small post residual relative to capacity).
    score -= (bin_capacity - post_residual) as f64 * 0.2;

    // Penalize leaving residual far below mean residual (wasteful split).
    let diff = post_residual as f64 - mean_residual;
    score += diff * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Pairing two items into a fresh bin is fine.
            score -= 20.0;
        }
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let resid = bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mean = mean_residual.max(0.0);

    // Base: two-step waste — leftover after ideally seating the lookahead item too.
    let mut score = if nxt > 0.0 && post >= nxt { post - nxt } else { post };

    // Perfect closure / small leftovers.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score += 14.0 + 3.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 5.0;
    } else {
        let post_class = (post_residual * 10 + bin_capacity / 2) / bin_capacity;
        if post_class >= 7 {
            score -= 4.0;
        }
    }

    // Aggressive exact two-step match.
    if nxt > 0.0 && post_residual == next_item_size {
        score -= 25.0 + 8.0 * (1.0 - progress);
    } else if nxt > 0.0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 10.0;
        } else if slack < 20 {
            score -= 4.0;
        }
    } else if nxt > 0.0 && post > 0.0 && post < nxt {
        let waste_frac = (nxt - post) / nxt;
        score += 0.6 * (nxt - post).min(cap)
            + 7.0
            + 3.5 * waste_frac * waste_frac * (1.0 - 0.5 * progress)
            + 2.5 * waste_frac * (1.0 - progress);
